"""Control for a mechanical short-word preference at a fixed writing margin."""
import json
from random import Random
from statistics import median

from measure import test

WIDTHS = (40, 50, 60)
SEEDS = tuple(range(281145,281155))


def paragraphs(seed):
    rng=Random(seed)
    return [[rng.randint(1,3) if rng.random()<.25 else rng.randint(4,9) for _ in range(rng.randint(14,35))]
            for _ in range(120)]


def rows_of(pars,width):
    for para in pars:
        current=[]; length=0
        for word in para:
            cost=word+bool(current)
            if length+cost>width:
                yield current
                current=[]; length=0; cost=word
            current.append(word); length+=cost
        if current:
            yield current


def main():
    output={}
    for width in WIDTHS:
        outcomes=[]
        for seed in SEEDS:
            lines=list(rows_of(paragraphs(seed),width))
            flagged=[(True,[int(n<=3) for n in words],tuple((i==len(words)-1,0<i<len(words)-1) for i in range(len(words)))) for words in lines]
            outcomes.append({'seed':seed,'lines':len(lines),**test(flagged,99)})
        output[width]={'pass_count':sum(row['pass'] for row in outcomes), 'median_ratio':median(row['value'] for row in outcomes), 'rows':outcomes}
    print(json.dumps(output,indent=2))


if __name__=='__main__':
    main()

scripts.measure.py:
"""Replay the position ratio on the public practice partitions and transparent controls."""
from collections import defaultdict
import json
from pathlib import Path
from random import Random
from statistics import median
import sys

from vs import corpus, dsl


def group_toks(pages):
    groups=defaultdict(list)
    for t in dsl.tokens(pages):
        groups[t['line']].append(t)
    return groups


def flags_from_groups(groups, line_range=None, clear_only=False):
    flagged = []
    for group in groups.values():
        counted = group[0]['unit']=='P'
        if line_range is not None:
            counted &= line_range[0] <= group[0]['n'] <= line_range[1]
        # The null shuffles among every token on a line before selecting by certainty and position.
        values = [None if dsl.UNCERTAIN(t['w']) else int(1<=len(dsl.SEG(t['w']))<=3) for t in group]
        if clear_only and None in values:
            counted = False
        flagged.append((counted, values, tuple((t['k']==t['n']-1, 0<t['k']<t['n']-1) for t in group)))
    return flagged


def rates(rows):
    end_hits=end_n=mid_hits=mid_n=0
    for counted,flags,positions in rows:
        if not counted:
            continue
        for flag,(line_final,mid_line) in zip(flags,positions,strict=True):
            if flag is None:
                continue
            if line_final:
                end_n+=1; end_hits+=flag
            if mid_line:
                mid_n+=1; mid_hits+=flag
    a=end_hits/end_n
    b=mid_hits/mid_n
    return {'value':a/b, 'final': {'hits':end_hits,'words':end_n}, 'interior':{'hits':mid_hits,'words':mid_n}}


def permute(rows,rng):
    for condition,flags,positions in rows:
        drawn=list(flags)
        rng.shuffle(drawn)
        yield condition,drawn,positions


def test(rows, permutations):
    observed=rates(rows)
    rng=Random(408)
    null=[rates(permute(rows,rng))['value'] for _ in range(permutations)]
    p=(1+sum(value>=observed['value'] for value in null))/(len(null)+1)
    return {**observed,'p_upper':p,'null_median':median(null),'perms':permutations,'pass':observed['value']>1 and p<=.01}


def synthetic_layout(rows, rng, mode):
    """Keep the number of positions and short-word opportunities in each row."""
    for condition,flags,positions in rows:
        values = [int(rng.random() < .22) if flag is None else flag for flag in flags]
        rng.shuffle(values)
        if condition and mode!='exchangeable' and len(values)>=3:
            # Put a long word first, when one exists. Treat the rest alike unless the terminal mechanism is active.
            if 0 in values:
                i=values.index(0)
                values[0],values[i]=values[i],values[0]
                if mode=='short_terminal' and rng.random()<.35 and 1 in values[1:]:
                    i=values.index(1,1)
                    values[-1],values[i]=values[i],values[-1]
        yield condition, values, positions


def main():
    work=Path(sys.argv[1])
    registration=json.loads((work/'fact-draft.json').read_text())
    out={}
    for edition in ('zl','it','rf'):
        out[edition]={}
        for part,pages in zip(('training','evaluation'),corpus.split_pages('practice',edition),strict=True):
            grouped=group_toks(pages)
            data=flags_from_groups(grouped)
            result=test(data,399)
            if edition=='zl' and part=='evaluation':
                official=dsl.evaluate(registration['spec'],pages)
                assert official['value']==round(result['value'],6)
                assert official['detail']['shuffle_within_line']['p']==round(result['p_upper'],4)
                assert official['pass']==result['pass']
            out[edition][part]={'primary':result}
            if part=='evaluation':
                out[edition][part]['sensitivity']={name:test(flags_from_groups(grouped,interval,clear),99)
                    for name,interval,clear in [('3–5 words',(3,5),False),('6 or more words',(6,999),False),('completely certain lines',None,True)]}
    _,pages=corpus.split_pages('practice')
    controls=flags_from_groups(group_toks(pages))
    out['synthetic']={mode:[test(list(synthetic_layout(controls,Random(722401+i),mode)),99) for i in range(16)]
                      for mode in ('exchangeable','long_initial','short_terminal')}
    print(json.dumps(out,indent=2))


if __name__=='__main__':
    main()

scripts.write_book.py:
"""Generate length-only writing controls without consulting manuscript word identities."""
from bisect import bisect_left
from collections import Counter
from itertools import accumulate
from math import ceil
from random import Random
from pathlib import Path
import json
import sys

from vs import corpus, ivtff


def fit(train):
    word_lengths=Counter()
    ordinary,ends=[],[]
    for page in train:
        for line in page.lines:
            if line.unit!='P' or not line.words:
                continue
            lengths=[len(ivtff.segment(w,'eva-basic')) for w in line.words if not ivtff.uncertain(w)]
            word_lengths.update(lengths)
            if len(lengths)==len(line.words):
                width=sum(lengths)+len(lengths)-1
                (ends if line.para_end else ordinary).append(width)
    ordinary.sort()
    capacity=ordinary[ceil(.75*len(ordinary))-1]
    return {'capacity':capacity,'ends':ends,'widths':[max(3,min(capacity,w)) for w in ends],
            'length_counts':dict(sorted(word_lengths.items())), 'ordinary_training_lines':len(ordinary)}


def shape(pages):
    return [[(line.unit,line.para_end,len(line.words)) for line in page.lines if line.words] for page in pages]


class Writer:
    def __init__(self, settings,seed):
        self.settings=settings
        self.stream=Random(seed)
        keys=sorted(int(k) for k in settings['length_counts'])
        self.lengths=keys
        self.weights=list(accumulate(settings['length_counts'][str(k)] for k in keys))
        self.pending=None

    def draw(self,max_length=None):
        if max_length is None:
            limit=len(self.lengths)
        else:
            limit=bisect_left(self.lengths,max_length+1)
        position=bisect_left(self.weights,self.stream.random()*self.weights[limit-1],0,limit)
        return self.lengths[position]

    def within_capacity(self,width):
        lengths=[]
        remaining=width+1
        minimum=self.lengths[0]+1
        while remaining>=minimum:
            new=self.draw(remaining-1)
            lengths.append(new)
            remaining-=new+1
        return lengths

    def greedy(self,width):
        lengths=[]
        remaining=width+1
        while True:
            new=self.pending if self.pending is not None else self.draw()
            self.pending=None
            if new+1<=remaining or not lengths:
                lengths.append(new)
                remaining-=new+1
            else:
                self.pending=new
                return lengths

    def token(self,length):
        return 'Z'+''.join(self.stream.choices('aodyeqklrnpm',k=length-1))

    def rows(self, page_shapes,mode):
        for page in page_shapes:
            self.pending=None
            for unit,para_end,slots in page:
                if unit!='P' or mode=='fixed_slots':
                    lengths=[self.draw() for _ in range(slots)]
                else:
                    width=self.stream.choice(self.settings['widths']) if para_end else self.settings['capacity']
                    lengths=self.within_capacity(width) if mode=='capacity_fit' else self.greedy(width)
                    if para_end:
                        self.pending=None
                yield [self.token(length) for length in lengths]


def main():
    work=Path(sys.argv[1]); train,_=corpus.split_pages('practice')
    cfg=fit(train)
    book=shape(corpus.pages())
    cfg['length_counts']={str(k):v for k,v in cfg['length_counts'].items()}
    (work/'frozen.json').write_text(json.dumps({'settings':cfg,'layout':book},indent=2)+'\n')
    primary=list(Writer(cfg,643701).rows(book,'capacity_fit'))
    assert all(len(ivtff.segment(w,'eva-basic'))==len(w) for line in primary for w in line)
    (work/'primary-lines.json').write_text(json.dumps(primary,separators=(',',':'))+'\n')
    print(json.dumps({'width':cfg['capacity'],'length_counts':cfg['length_counts'],'lines':len(primary),'words':sum(map(len,primary))}))


if __name__=='__main__':
    main()

scripts.battery.py:
"""Character code lengths and sample entropy with train and evaluation works separated."""
from collections import Counter
from dataclasses import dataclass
from hashlib import sha256
import json
from math import isclose, log2
from pathlib import Path

MAX_ORDER = 8
PRIOR_STRENGTH = 2
PSEUDOCOUNT = 0.5
PAD_ALPHABETS = {
    'identity': '', 'substitution': '', 'addB': 'B',
    'matched_deterministic': 'BD', 'matched_random': 'BD', 'suffix_B': 'B',
}
SOURCE = 'abcdefghijklmnopqrstuvwxyz '


@dataclass
class Markov:
    alphabet: str
    counts: list
    totals: list

    @classmethod
    def fit(cls, blocks, alphabet, max_order=MAX_ORDER):
        counts = [dict() for _ in range(max_order + 1)]
        for block in blocks:
            if set(block) - set(alphabet):
                raise ValueError('training contains a symbol outside the declared alphabet')
            for i, symbol in enumerate(block):
                for order in range(min(i, max_order) + 1):
                    ctx = block[i-order:i]
                    table = counts[order].setdefault(ctx, Counter())
                    table[symbol] += 1
        if not counts[0]:
            raise ValueError('the training work is empty')
        totals = [{ctx: row.total() for ctx, row in table.items()} for table in counts]
        return cls(alphabet, counts, totals)

    def probabilities(self, symbol, context):
        if symbol not in self.alphabet:
            raise ValueError(f'evaluation contains a symbol outside the declared alphabet: {symbol!r}')
        cells = self.counts[0]['']
        prior = (cells[symbol] + PSEUDOCOUNT) / (self.totals[0][''] + PSEUDOCOUNT * len(self.alphabet))
        yield prior
        for order in range(1, len(self.counts)):
            if len(context) >= order:
                ctx = context[-order:]
                row = self.counts[order].get(ctx)
                if row is not None:
                    prior = (row[symbol] + PRIOR_STRENGTH * prior) / (self.totals[order][ctx] + PRIOR_STRENGTH)
            yield prior

    def bits(self, blocks):
        result = [0.0] * len(self.counts)
        for block in blocks:
            for i, symbol in enumerate(block):
                context = block[max(0, i-len(result)+1):i]
                for order, probability in enumerate(self.probabilities(symbol, context)):
                    result[order] -= log2(probability)
        return result


def sample_entropy_bits(blocks, max_order=MAX_ORDER):
    """Empirical conditional entropy, allowing shorter context at each block start."""
    histograms = [dict() for _ in range(max_order + 1)]
    for block in blocks:
        for i, symbol in enumerate(block):
            for order in range(max_order + 1):
                ctx = block[max(0, i-order):i]
                table = histograms[order].setdefault(ctx, Counter())
                table[symbol] += 1
    totals = []
    for order in range(max_order + 1):
        bits = 0.0
        for row in histograms[order].values():
            total = row.total()
            bits -= sum(n * log2(n / total) for n in row.values())
        totals.append(bits)
    return totals


def adjacent_entropy(blocks):
    pairs = {}
    for block in blocks:
        for left, right in zip(block, block[1:]):
            pairs.setdefault(left, Counter())[right] += 1
    transitions, bits = 0, 0.0
    for row in pairs.values():
        count = row.total()
        transitions += count
        bits -= sum(n * log2(n/count) for n in row.values())
    return {'transitions': transitions,
            'bits_per_transition': round(bits/transitions, 8) if transitions else None}


def digest(text):
    return sha256(text.encode()).hexdigest()


def evaluate(train, test, kinds, encode, decode, side_bits):
    train_text = '\n'.join(train)
    test_text = '\n'.join(test)
    source_count = sum(map(len, test))
    if not source_count or not sum(map(len, train)):
        raise ValueError('both disjoint works must have nonempty normalised blocks')
    hashes_train = {digest(block) for block in train}
    hashes_test = {digest(block) for block in test}
    if hashes_train & hashes_test:
        raise ValueError('an exact normalised block occurs in both works')

    identity = Markov.fit(train, SOURCE).bits(test)
    result = {}
    for kind in kinds:
        encoded_train = encode(train_text, kind, seed=40801)
        encoded_test = encode(test_text, kind, seed=40802)
        assert decode(encoded_train, kind) == train_text
        assert decode(encoded_test, kind) == test_text
        train_blocks = encoded_train.split('\n')
        test_blocks = encoded_test.split('\n')
        assert len(train_blocks) == len(train) and len(test_blocks) == len(test)
        assert [text.count(' ') for text in train_blocks] == [text.count(' ') for text in train]
        assert [text.count(' ') for text in test_blocks] == [text.count(' ') for text in test]
        if kind == 'matched_random':
            for raw, encoded in ((train_text, encoded_train), (test_text, encoded_test)):
                ordered_pads = (ch for ch in encoded if ch in 'BD')
                reconstructed = ''.join(ch if ch in ' \n' else ch + next(ordered_pads) for ch in raw)
                assert reconstructed == encoded and next(ordered_pads, None) is None
        output_count = sum(map(len, test_blocks))
        alphabet = SOURCE + PAD_ALPHABETS[kind]
        forward = Markov.fit(train_blocks, alphabet).bits(test_blocks)
        empirical = sample_entropy_bits(test_blocks)
        side = side_bits(test_text, kind)
        inverse = [raw + side for raw in identity]
        rows = []
        for order, (a, b, c) in enumerate(zip(forward, empirical, inverse)):
            assert isclose((a/source_count) * source_count, (a/output_count) * output_count)
            rows.append({'order': order, 'forward_bits': round(a, 6),
                         'forward_bits_per_source': round(a/source_count, 8),
                         'forward_bits_per_output': round(a/output_count, 8),
                         'empirical_bits_per_source': round(b/source_count, 8),
                         'empirical_bits_per_output': round(b/output_count, 8),
                         'inverse_bits': round(c, 6),
                         'inverse_bits_per_source': round(c/source_count, 8),
                         'inverse_bits_per_output': round(c/output_count, 8)})
        result[kind] = {'output_symbols': output_count, 'output_train_symbols': sum(map(len, train_blocks)),
                        'output_checksum': digest(encoded_test), 'train_output_checksum': digest(encoded_train),
                        'side_bits': round(side, 6), 'orders': rows,
                        'adjacent_empirical': adjacent_entropy(test_blocks),
                        'training_marker_counts': dict(Counter(ch for ch in encoded_train if ch in 'BD')),
                        'evaluation_marker_counts': dict(Counter(ch for ch in encoded_test if ch in 'BD'))}
        if kind in ('identity', 'substitution'):
            assert all(isclose(raw, transformed, rel_tol=1e-11) for raw, transformed in zip(identity, forward))
    a = result['matched_deterministic']
    b = result['matched_random']
    assert a['output_symbols'] == b['output_symbols']
    assert a['output_train_symbols'] == b['output_train_symbols']
    assert a['training_marker_counts'] == b['training_marker_counts']
    assert a['evaluation_marker_counts'] == b['evaluation_marker_counts']
    return {'train_blocks': len(train), 'eval_blocks': len(test), 'train_symbols': sum(map(len, train)),
            'eval_source_symbols': source_count, 'train_source_checksum': digest(train_text),
            'eval_source_checksum': digest(test_text), 'eval_spaces': test_text.count(' '),
            'exact_block_overlap': 0, 'modes': result}


def main():
    from transforms import KINDS, encode, decode, side_bits

    base = Path(__file__).resolve().parent
    works = json.loads((base/'clean_works.json').read_text())
    selection = json.loads((base/'works.json').read_text())
    output = {}
    for name, pair in selection['pairs'].items():
        train_id, test_id = pair['train'], pair['evaluation']
        assert train_id != test_id and len(works[train_id]) >= 64 and len(works[test_id]) >= 64
        print('Scoring', name, 'independent', train_id, '->', test_id, flush=True)
        output[name] = evaluate(works[train_id][:64], works[test_id][:64], KINDS, encode, decode, side_bits)
        output[name]['work_metadata'] = pair
        for mode, result in output[name]['modes'].items():
            last = result['orders'][-1]
            print(mode, 'output', result['output_symbols'], 'source', last['forward_bits_per_source'],
                  'output_rate', last['forward_bits_per_output'], 'inverse', last['inverse_bits_per_source'], flush=True)
        (base/'results.json').write_text(json.dumps(output, ensure_ascii=False, indent=2)+'\n')


if __name__ == '__main__':
    main()

scripts.extract_works.py:
"""Prepare six pinned, public-domain reference work spans for P-J-011."""
import hashlib
import json
from pathlib import Path
import re

from vs import path, refcorpus


WORKS = {
    "la_augustine": {
        "work": "Augustine, Confessiones, Books I–II",
        "start": "1. _Magnus es, Domine",
        "stop": "\nLIBER TERTIUS.",
        "cleaning": "Remove inline square-bracketed sidenotes and footnote calls, braced page numbers, and four-space-indented editorial summaries.",
        "confidence": "High. Main prose of the first two books in the 1838 Latin edition. Augustine’s own Biblical quotations remain.",
    },
    "la_vulg_daniel": {
        "work": "Clementine Vulgate, Daniel",
        "start": "\n1:1 Anno tertio",
        "stop": "\nPARALLELISMUS MEMBRORUM.",
        "cleaning": "Keep only blank-line-delimited paragraphs opening with a decimal chapter:verse token. The project normalizer removes the verse numbers.",
        "confidence": "High. The main verses only, independent of the English transcriber notes and Latin critical appendix. The Vulgate includes the Septuagint additions.",
    },
    "it_dante": {
        "work": "Dante, Commedia, Inferno",
        "start": "Nel mezzo del cammin di nostra vita",
        "stop": "\n  PURGATORIO",
        "cleaning": "Remove remaining Inferno canto-title lines. The raw pin contains the whole Commedia, while this span is Inferno only.",
        "confidence": "High. Starts at the first verse and ends after Inferno XXXIV.",
    },
    "it_villani": {
        "work": "Matteo Villani, Cronica, Book I",
        "start": "Esaminando nell’animo la vostra esortazione",
        "stop": "\nLIBRO SECONDO",
        "cleaning": "Keep the original author’s prologue and main Book I. Chapter headings remain. No modern introduction or table of contents.",
        "confidence": "High for main medieval prose. Chapter headings from the 1825 edition remain.",
    },
    "de_nibelunge": {
        "work": "Der Nibelunge liet, Middle High German text",
        "start": "Uns ist in alten mæren",
        "stop": None,
        "cleaning": "Drop letter-period-decimal manuscript and stanza tags, preserving the text of stanza and section headings. Use the text through its ending.",
        "confidence": "High. Gutenberg #48888 is Simrock’s Middle High German text. His modern German translation and editorial introduction are a different Gutenberg file (#14915).",
    },
    "de_walther": {
        "work": "Walther von der Vogelweide, Gedichte und Sprüche in Auswahl, poems",
        "start": "Uns hât der winter geschadet über al:",
        "stop": "\nANMERKUNGEN",
        "cleaning": "Omit all-uppercase section headings and bracket-initial editorial lines before the start of the commentary.",
        "confidence": "High. A single-author selection of lyric poetry independent of the Nibelungen epic. The modern notes are after the stop marker.",
    },
}
PAIRS = {
    "latin": {
        "train": "la_augustine",
        "evaluation": "la_vulg_daniel",
        "rationale": "Autobiographical theological prose versus an independent biblical book. Augustine’s own brief scriptural quotations are part of his work. No consecutive 12-word passage overlaps the selected Daniel edition.",
    },
    "italian": {
        "train": "it_dante",
        "evaluation": "it_villani",
        "rationale": "Dante’s narrative poem versus Matteo Villani’s historical chronicle. #426 used the same IDs, while these spans exclude Villani’s modern preface and reset the training and evaluation samples on actual medieval text.",
    },
    "german": {
        "train": "de_nibelunge",
        "evaluation": "de_walther",
        "rationale": "Anonymous heroic epic versus a selection of Walther’s lyrics and songs. Separate works and corpus editions, with no translation or anthology that contains the epic.",
    },
}


def sha256(s):
    return hashlib.sha256(s).hexdigest()


def extraction(cid, text):
    if cid == "la_augustine":
        return re.sub(r"\[[^\[\]]*\]|\{\d+\}|^    .*$", "", text, flags=re.M)
    if cid == "la_vulg_daniel":
        return "\n".join(p for p in text.split("\n\n") if re.match(r"^\d+:\d+ ", p.strip()))
    if cid == "it_dante":
        return re.sub(r"^\s*Inferno • Canto.*$", "", text, flags=re.M)
    if cid == "de_nibelunge":
        return re.sub(r"\s+[A-Z][.]\d+(?:[*a-z]?)", "", text)
    if cid == "de_walther":
        return "\n".join(line for line in text.splitlines()
                         if not (line.strip().isupper() or line.lstrip().startswith("[")))
    return text


def blocks(text):
    out, current, length = [], [], 0
    for word in text.split():
        current.append(word)
        length += len(word) + 1
        if length >= 400:
            out.append(" ".join(current))
            current, length = [], 0
    if current:
        out.append(" ".join(current))
    return out


def ngrams(text, n):
    words = text.split()
    return {tuple(words[i:i+n]) for i in range(len(words)-n+1)}


def main():
    refs = {e["id"]: e for e in refcorpus.pins()}
    archive, work_meta, texts = {}, {}, {}
    for cid, recipe in WORKS.items():
        e = refs[cid]
        source_file = Path(path(e["file"]))
        raw = source_file.read_bytes()
        assert sha256(raw) == e["sha256"], cid
        with source_file.open(encoding=e.get("encoding", "utf-8"), errors="replace") as src:
            stripped = refcorpus.strip_gutenberg(src.read())
        start = stripped.index(recipe["start"])
        stop = stripped.index(recipe["stop"], start + len(recipe["start"])) if recipe["stop"] else len(stripped)
        normalized = refcorpus.normalize(extraction(cid, stripped[start:stop]), e["lang"])
        texts[cid] = normalized
        archive[cid] = blocks(normalized)
        assert " ".join(archive[cid]) == normalized
        work_meta[cid] = {
            **recipe,
            "language": e["lang"],
            "catalog_period": e["period"],
            "raw_url": e["url"],
            "raw_sha256": e["sha256"],
            "catalog_url": f"https://www.gutenberg.org/ebooks/{e['gutenberg']}",
            "rights": "Project Gutenberg catalog marks public domain in the USA.",
            "encoding": e.get("encoding", "utf-8"),
            "span_start_stop": [start, stop],
            "normalized_symbols_including_spaces": len(normalized),
            "normalized_nonspace_symbols": len(normalized.replace(" ", "")),
            "blocks": len(archive[cid]),
            "sum_of_block_symbol_counts": sum(map(len, archive[cid])),
            "symbols_in_first_64_blocks": sum(map(len, archive[cid][:64])),
            "normalized_sha256": sha256(normalized.encode()),
            "newline_joined_blocks_sha256": sha256("\n".join(archive[cid]).encode()),
        }
    pair_meta = {lang: dict(pair) for lang, pair in PAIRS.items()}
    for lang, pair in pair_meta.items():
        a, b = pair["train"], pair["evaluation"]
        pair["exact_shared_blocks"] = len(set(archive[a]) & set(archive[b]))
        pair["exact_shared_distinct_12_word_windows"] = len(ngrams(texts[a], 12) & ngrams(texts[b], 12))
        assert not pair["exact_shared_blocks"]
    out = {
        "pairs": pair_meta,
        "works_by_corpus_id": work_meta,
        "extraction_order": "Decode the SHA-verified pinned file with universal newlines. Apply vs.refcorpus.strip_gutenberg. Find the literal start and stop markers, or use the end of the stripped file. Apply the listed per-work cleanup, then vs.refcorpus.normalize. Span offsets refer to the stripped decoded text before cleanup. Break at word boundaries once the same accounting as blocks_of reaches at least 400, keeping the final partial block. Counts including spaces treat each run of whitespace as one symbol.",
        "pr_426": {
            "url": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/426",
            "design": "First 100 training-work blocks and 30 evaluation-work blocks built directly with refcorpus.blocks_of, using Augustine/Erasmus, Dante/Villani, Lucanor/Buen Amor and Chaucer/Paston. Order 0–8 smoothed character models and several reversible padding controls were used.",
            "editorial_confounds": "The pins start with editorial text in Augustine (1838 Latin Monitum), Erasmus (digital production and bilingual title line plus 20th-century transcriber corrections elsewhere), Villani (1825 editor address), Lucanor (editorial transcription note), Buen Amor (edition front matter and extensive notes), Chaucer (Purves’s table of contents and biography), and Paston (Gairdner’s early-20th-century critical edition’s preface and long historical introduction). These are risks for any claim about source-language coding rates from untrimmed beginnings.",
        },
    }
    dest = Path(__file__).parent
    (dest / "works.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (dest / "clean_works.json").write_text(json.dumps(archive, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps(pair_meta, ensure_ascii=False, indent=2))
    for cid, e in work_meta.items():
        print(cid, e["normalized_symbols_including_spaces"], e["normalized_nonspace_symbols"], e["blocks"], e["symbols_in_first_64_blocks"])


if __name__ == "__main__":
    main()

scripts.battery.py:
"""Character code lengths and sample entropy with train and evaluation works separated."""
from collections import Counter
from dataclasses import dataclass
from hashlib import sha256
import json
from math import isclose, log2
from pathlib import Path

MAX_ORDER = 8
PRIOR_STRENGTH = 2
PSEUDOCOUNT = 0.5
PAD_ALPHABETS = {
    'identity': '', 'substitution': '', 'addB': 'B',
    'matched_deterministic': 'BD', 'matched_random': 'BD', 'suffix_B': 'B',
}
SOURCE = 'abcdefghijklmnopqrstuvwxyz '


@dataclass
class Markov:
    alphabet: str
    counts: list
    totals: list

    @classmethod
    def fit(cls, blocks, alphabet, max_order=MAX_ORDER):
        counts = [dict() for _ in range(max_order + 1)]
        for block in blocks:
            if set(block) - set(alphabet):
                raise ValueError('training contains a symbol outside the declared alphabet')
            for i, symbol in enumerate(block):
                for order in range(min(i, max_order) + 1):
                    ctx = block[i-order:i]
                    table = counts[order].setdefault(ctx, Counter())
                    table[symbol] += 1
        if not counts[0]:
            raise ValueError('the training work is empty')
        totals = [{ctx: row.total() for ctx, row in table.items()} for table in counts]
        return cls(alphabet, counts, totals)

    def probabilities(self, symbol, context):
        if symbol not in self.alphabet:
            raise ValueError(f'evaluation contains a symbol outside the declared alphabet: {symbol!r}')
        cells = self.counts[0]['']
        prior = (cells[symbol] + PSEUDOCOUNT) / (self.totals[0][''] + PSEUDOCOUNT * len(self.alphabet))
        yield prior
        for order in range(1, len(self.counts)):
            if len(context) >= order:
                ctx = context[-order:]
                row = self.counts[order].get(ctx)
                if row is not None:
                    prior = (row[symbol] + PRIOR_STRENGTH * prior) / (self.totals[order][ctx] + PRIOR_STRENGTH)
            yield prior

    def bits(self, blocks):
        result = [0.0] * len(self.counts)
        for block in blocks:
            for i, symbol in enumerate(block):
                context = block[max(0, i-len(result)+1):i]
                for order, probability in enumerate(self.probabilities(symbol, context)):
                    result[order] -= log2(probability)
        return result


def sample_entropy_bits(blocks, max_order=MAX_ORDER):
    """Empirical conditional entropy, allowing shorter context at each block start."""
    histograms = [dict() for _ in range(max_order + 1)]
    for block in blocks:
        for i, symbol in enumerate(block):
            for order in range(max_order + 1):
                ctx = block[max(0, i-order):i]
                table = histograms[order].setdefault(ctx, Counter())
                table[symbol] += 1
    totals = []
    for order in range(max_order + 1):
        bits = 0.0
        for row in histograms[order].values():
            total = row.total()
            bits -= sum(n * log2(n / total) for n in row.values())
        totals.append(bits)
    return totals


def adjacent_entropy(blocks):
    pairs = {}
    for block in blocks:
        for left, right in zip(block, block[1:]):
            pairs.setdefault(left, Counter())[right] += 1
    transitions, bits = 0, 0.0
    for row in pairs.values():
        count = row.total()
        transitions += count
        bits -= sum(n * log2(n/count) for n in row.values())
    return {'transitions': transitions,
            'bits_per_transition': round(bits/transitions, 8) if transitions else None}


def digest(text):
    return sha256(text.encode()).hexdigest()


def evaluate(train, test, kinds, encode, decode, side_bits):
    train_text = '\n'.join(train)
    test_text = '\n'.join(test)
    source_count = sum(map(len, test))
    if not source_count or not sum(map(len, train)):
        raise ValueError('both disjoint works must have nonempty normalised blocks')
    hashes_train = {digest(block) for block in train}
    hashes_test = {digest(block) for block in test}
    if hashes_train & hashes_test:
        raise ValueError('an exact normalised block occurs in both works')

    identity = Markov.fit(train, SOURCE).bits(test)
    result = {}
    for kind in kinds:
        encoded_train = encode(train_text, kind, seed=40801)
        encoded_test = encode(test_text, kind, seed=40802)
        assert decode(encoded_train, kind) == train_text
        assert decode(encoded_test, kind) == test_text
        train_blocks = encoded_train.split('\n')
        test_blocks = encoded_test.split('\n')
        assert len(train_blocks) == len(train) and len(test_blocks) == len(test)
        assert [text.count(' ') for text in train_blocks] == [text.count(' ') for text in train]
        assert [text.count(' ') for text in test_blocks] == [text.count(' ') for text in test]
        if kind == 'matched_random':
            for raw, encoded in ((train_text, encoded_train), (test_text, encoded_test)):
                ordered_pads = (ch for ch in encoded if ch in 'BD')
                reconstructed = ''.join(ch if ch in ' \n' else ch + next(ordered_pads) for ch in raw)
                assert reconstructed == encoded and next(ordered_pads, None) is None
        output_count = sum(map(len, test_blocks))
        alphabet = SOURCE + PAD_ALPHABETS[kind]
        forward = Markov.fit(train_blocks, alphabet).bits(test_blocks)
        empirical = sample_entropy_bits(test_blocks)
        side = side_bits(test_text, kind)
        inverse = [raw + side for raw in identity]
        rows = []
        for order, (a, b, c) in enumerate(zip(forward, empirical, inverse)):
            assert isclose((a/source_count) * source_count, (a/output_count) * output_count)
            rows.append({'order': order, 'forward_bits': round(a, 6),
                         'forward_bits_per_source': round(a/source_count, 8),
                         'forward_bits_per_output': round(a/output_count, 8),
                         'empirical_bits_per_source': round(b/source_count, 8),
                         'empirical_bits_per_output': round(b/output_count, 8),
                         'inverse_bits': round(c, 6),
                         'inverse_bits_per_source': round(c/source_count, 8),
                         'inverse_bits_per_output': round(c/output_count, 8)})
        result[kind] = {'output_symbols': output_count, 'output_train_symbols': sum(map(len, train_blocks)),
                        'output_checksum': digest(encoded_test), 'train_output_checksum': digest(encoded_train),
                        'side_bits': round(side, 6), 'orders': rows,
                        'adjacent_empirical': adjacent_entropy(test_blocks),
                        'training_marker_counts': dict(Counter(ch for ch in encoded_train if ch in 'BD')),
                        'evaluation_marker_counts': dict(Counter(ch for ch in encoded_test if ch in 'BD'))}
        if kind in ('identity', 'substitution'):
            assert all(isclose(raw, transformed, rel_tol=1e-11) for raw, transformed in zip(identity, forward))
    a = result['matched_deterministic']
    b = result['matched_random']
    assert a['output_symbols'] == b['output_symbols']
    assert a['output_train_symbols'] == b['output_train_symbols']
    assert a['training_marker_counts'] == b['training_marker_counts']
    assert a['evaluation_marker_counts'] == b['evaluation_marker_counts']
    return {'train_blocks': len(train), 'eval_blocks': len(test), 'train_symbols': sum(map(len, train)),
            'eval_source_symbols': source_count, 'train_source_checksum': digest(train_text),
            'eval_source_checksum': digest(test_text), 'eval_spaces': test_text.count(' '),
            'exact_block_overlap': 0, 'modes': result}


def main():
    from transforms import KINDS, encode, decode, side_bits

    base = Path(__file__).resolve().parent
    works = json.loads((base/'clean_works.json').read_text())
    selection = json.loads((base/'works.json').read_text())
    output = {}
    for name, pair in selection['pairs'].items():
        train_id, test_id = pair['train'], pair['evaluation']
        assert train_id != test_id and len(works[train_id]) >= 64 and len(works[test_id]) >= 64
        print('Scoring', name, 'independent', train_id, '->', test_id, flush=True)
        output[name] = evaluate(works[train_id][:64], works[test_id][:64], KINDS, encode, decode, side_bits)
        output[name]['work_metadata'] = pair
        for mode, result in output[name]['modes'].items():
            last = result['orders'][-1]
            print(mode, 'output', result['output_symbols'], 'source', last['forward_bits_per_source'],
                  'output_rate', last['forward_bits_per_output'], 'inverse', last['inverse_bits_per_source'], flush=True)
        (base/'results.json').write_text(json.dumps(output, ensure_ascii=False, indent=2)+'\n')


if __name__ == '__main__':
    main()

scripts.extract_works.py:
"""Prepare six pinned, public-domain reference work spans for P-J-011."""
import hashlib
import json
from pathlib import Path
import re

from vs import path, refcorpus


WORKS = {
    "la_augustine": {
        "work": "Augustine, Confessiones, Books I–II",
        "start": "1. _Magnus es, Domine",
        "stop": "\nLIBER TERTIUS.",
        "cleaning": "Remove inline square-bracketed sidenotes and footnote calls, braced page numbers, and four-space-indented editorial summaries.",
        "confidence": "High. Main prose of the first two books in the 1838 Latin edition. Augustine’s own Biblical quotations remain.",
    },
    "la_vulg_daniel": {
        "work": "Clementine Vulgate, Daniel",
        "start": "\n1:1 Anno tertio",
        "stop": "\nPARALLELISMUS MEMBRORUM.",
        "cleaning": "Keep only blank-line-delimited paragraphs opening with a decimal chapter:verse token. The project normalizer removes the verse numbers.",
        "confidence": "High. The main verses only, independent of the English transcriber notes and Latin critical appendix. The Vulgate includes the Septuagint additions.",
    },
    "it_dante": {
        "work": "Dante, Commedia, Inferno",
        "start": "Nel mezzo del cammin di nostra vita",
        "stop": "\n  PURGATORIO",
        "cleaning": "Remove remaining Inferno canto-title lines. The raw pin contains the whole Commedia, while this span is Inferno only.",
        "confidence": "High. Starts at the first verse and ends after Inferno XXXIV.",
    },
    "it_villani": {
        "work": "Matteo Villani, Cronica, Book I",
        "start": "Esaminando nell’animo la vostra esortazione",
        "stop": "\nLIBRO SECONDO",
        "cleaning": "Keep the original author’s prologue and main Book I. Chapter headings remain. No modern introduction or table of contents.",
        "confidence": "High for main medieval prose. Chapter headings from the 1825 edition remain.",
    },
    "de_nibelunge": {
        "work": "Der Nibelunge liet, Middle High German text",
        "start": "Uns ist in alten mæren",
        "stop": None,
        "cleaning": "Drop letter-period-decimal manuscript and stanza tags, preserving the text of stanza and section headings. Use the text through its ending.",
        "confidence": "High. Gutenberg #48888 is Simrock’s Middle High German text. His modern German translation and editorial introduction are a different Gutenberg file (#14915).",
    },
    "de_walther": {
        "work": "Walther von der Vogelweide, Gedichte und Sprüche in Auswahl, poems",
        "start": "Uns hât der winter geschadet über al:",
        "stop": "\nANMERKUNGEN",
        "cleaning": "Omit all-uppercase section headings and bracket-initial editorial lines before the start of the commentary.",
        "confidence": "High. A single-author selection of lyric poetry independent of the Nibelungen epic. The modern notes are after the stop marker.",
    },
}
PAIRS = {
    "latin": {
        "train": "la_augustine",
        "evaluation": "la_vulg_daniel",
        "rationale": "Autobiographical theological prose versus an independent biblical book. Augustine’s own brief scriptural quotations are part of his work. No consecutive 12-word passage overlaps the selected Daniel edition.",
    },
    "italian": {
        "train": "it_dante",
        "evaluation": "it_villani",
        "rationale": "Dante’s narrative poem versus Matteo Villani’s historical chronicle. #426 used the same IDs, while these spans exclude Villani’s modern preface and reset the training and evaluation samples on actual medieval text.",
    },
    "german": {
        "train": "de_nibelunge",
        "evaluation": "de_walther",
        "rationale": "Anonymous heroic epic versus a selection of Walther’s lyrics and songs. Separate works and corpus editions, with no translation or anthology that contains the epic.",
    },
}


def sha256(s):
    return hashlib.sha256(s).hexdigest()


def extraction(cid, text):
    if cid == "la_augustine":
        return re.sub(r"\[[^\[\]]*\]|\{\d+\}|^    .*$", "", text, flags=re.M)
    if cid == "la_vulg_daniel":
        return "\n".join(p for p in text.split("\n\n") if re.match(r"^\d+:\d+ ", p.strip()))
    if cid == "it_dante":
        return re.sub(r"^\s*Inferno • Canto.*$", "", text, flags=re.M)
    if cid == "de_nibelunge":
        return re.sub(r"\s+[A-Z][.]\d+(?:[*a-z]?)", "", text)
    if cid == "de_walther":
        return "\n".join(line for line in text.splitlines()
                         if not (line.strip().isupper() or line.lstrip().startswith("[")))
    return text


def blocks(text):
    out, current, length = [], [], 0
    for word in text.split():
        current.append(word)
        length += len(word) + 1
        if length >= 400:
            out.append(" ".join(current))
            current, length = [], 0
    if current:
        out.append(" ".join(current))
    return out


def ngrams(text, n):
    words = text.split()
    return {tuple(words[i:i+n]) for i in range(len(words)-n+1)}


def main():
    refs = {e["id"]: e for e in refcorpus.pins()}
    archive, work_meta, texts = {}, {}, {}
    for cid, recipe in WORKS.items():
        e = refs[cid]
        source_file = Path(path(e["file"]))
        raw = source_file.read_bytes()
        assert sha256(raw) == e["sha256"], cid
        with source_file.open(encoding=e.get("encoding", "utf-8"), errors="replace") as src:
            stripped = refcorpus.strip_gutenberg(src.read())
        start = stripped.index(recipe["start"])
        stop = stripped.index(recipe["stop"], start + len(recipe["start"])) if recipe["stop"] else len(stripped)
        normalized = refcorpus.normalize(extraction(cid, stripped[start:stop]), e["lang"])
        texts[cid] = normalized
        archive[cid] = blocks(normalized)
        assert " ".join(archive[cid]) == normalized
        work_meta[cid] = {
            **recipe,
            "language": e["lang"],
            "catalog_period": e["period"],
            "raw_url": e["url"],
            "raw_sha256": e["sha256"],
            "catalog_url": f"https://www.gutenberg.org/ebooks/{e['gutenberg']}",
            "rights": "Project Gutenberg catalog marks public domain in the USA.",
            "encoding": e.get("encoding", "utf-8"),
            "span_start_stop": [start, stop],
            "normalized_symbols_including_spaces": len(normalized),
            "normalized_nonspace_symbols": len(normalized.replace(" ", "")),
            "blocks": len(archive[cid]),
            "sum_of_block_symbol_counts": sum(map(len, archive[cid])),
            "symbols_in_first_64_blocks": sum(map(len, archive[cid][:64])),
            "normalized_sha256": sha256(normalized.encode()),
            "newline_joined_blocks_sha256": sha256("\n".join(archive[cid]).encode()),
        }
    pair_meta = {lang: dict(pair) for lang, pair in PAIRS.items()}
    for lang, pair in pair_meta.items():
        a, b = pair["train"], pair["evaluation"]
        pair["exact_shared_blocks"] = len(set(archive[a]) & set(archive[b]))
        pair["exact_shared_distinct_12_word_windows"] = len(ngrams(texts[a], 12) & ngrams(texts[b], 12))
        assert not pair["exact_shared_blocks"]
    out = {
        "pairs": pair_meta,
        "works_by_corpus_id": work_meta,
        "extraction_order": "Decode the SHA-verified pinned file with universal newlines. Apply vs.refcorpus.strip_gutenberg. Find the literal start and stop markers, or use the end of the stripped file. Apply the listed per-work cleanup, then vs.refcorpus.normalize. Span offsets refer to the stripped decoded text before cleanup. Break at word boundaries once the same accounting as blocks_of reaches at least 400, keeping the final partial block. Counts including spaces treat each run of whitespace as one symbol.",
        "pr_426": {
            "url": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/426",
            "design": "First 100 training-work blocks and 30 evaluation-work blocks built directly with refcorpus.blocks_of, using Augustine/Erasmus, Dante/Villani, Lucanor/Buen Amor and Chaucer/Paston. Order 0–8 smoothed character models and several reversible padding controls were used.",
            "editorial_confounds": "The pins start with editorial text in Augustine (1838 Latin Monitum), Erasmus (digital production and bilingual title line plus 20th-century transcriber corrections elsewhere), Villani (1825 editor address), Lucanor (editorial transcription note), Buen Amor (edition front matter and extensive notes), Chaucer (Purves’s table of contents and biography), and Paston (Gairdner’s early-20th-century critical edition’s preface and long historical introduction). These are risks for any claim about source-language coding rates from untrimmed beginnings.",
        },
    }
    dest = Path(__file__).parent
    (dest / "works.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (dest / "clean_works.json").write_text(json.dumps(archive, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps(pair_meta, ensure_ascii=False, indent=2))
    for cid, e in work_meta.items():
        print(cid, e["normalized_symbols_including_spaces"], e["normalized_nonspace_symbols"], e["blocks"], e["symbols_in_first_64_blocks"])


if __name__ == "__main__":
    main()

programs.audit_picture_gate.py:
"""Public coverage and in-memory picture-null controls. Never opens the hidden split."""
from collections import Counter
from functools import lru_cache
import json
from pathlib import Path
import random
from unittest.mock import patch

from vs import corpus, dsl, generators, ivtff, registry

WORK = Path(__file__).resolve().parent
SEEDS = (31, 57, 83, 107, 139, 167, 199, 227)
MIN_OBJECTS = 20
PERMS = 399


def preflight():
    items = registry.read('picture')
    records = [i for i in items if i.get('verdict') == 'AGREED']
    gate = {'record_counts': dict(Counter(i['verdict'] for i in items)),
            'agreed_records': [i['id'] for i in records], 'main_checkout': 'e160993',
            'distinct_picture_folios': len({i['detail']['folio'] for i in items}),
            'runtime_selected': {}, 'all_agreed_record_counters': [], 'practice': {}}
    for folio, objects in dsl.pictures().items():
        gate['runtime_selected'][folio] = {'objects': len(objects),
            'direct_loci': sum(bool(o.get('label')) for o in objects),
            'joined_loci': len(dsl._joined_labels(folio, objects))}
    for item in records:
        folio = item['detail']['folio']
        objects = item['detail']['objects']
        labels = {o['label'] for o in objects if o.get('label')}
        row = {'id': item['id'], 'folio':folio, 'objects':len(objects),
               'explicit_loci':len(labels), 'agreement':item.get('agreement'), 'transliterations':{}}
        for transliteration in ('zl', 'it', 'rf'):
            p = next(page for page in corpus.pages(transliteration) if page.id == folio)
            native = {l.id for l in p.lines if l.unit == 'L' and l.words}
            with patch.object(dsl, 'PICTURES', {folio: objects}):
                usable = dsl._picture_objects(dsl.tokens([p], None))
            alike = sum(x[1] == y[1] and any(x[2].get(k) == v for k,v in y[2].items())
                       for idx,x in enumerate(usable) for y in usable[idx+1:])
            row['transliterations'][transliteration] = {'P_lines':sum(l.unit=='P' and bool(l.words) for l in p.lines),
                'L_lines':len(native),'valid_explicit_loci':len(labels&native), 'hypothetically_usable':len(usable),
                'alike_pairs':alike,'other_pairs':len(usable)*(len(usable)-1)//2-alike}
        gate['all_agreed_record_counters'].append(row)
    for transliteration in ('zl','it','rf'):
        _, practice = corpus.split_pages('practice', transliteration)
        tokens = dsl.tokens(practice, None)
        gate['practice'][transliteration] = {'joined':len(dsl._picture_objects(tokens)),
                                              'P_pages':len({t['folio'] for t in tokens if t['unit']=='P'})}
    return gate


def fixtures():
    pages = []
    primary, sham, balanced = {}, {}, {}
    for k in range(12):
        page_id = f'example{k+1:02d}'
        page = ivtff.Page(page_id, k, {'I':'H','L':'A','H':'1'})
        pages.append(page)
        primary[page_id], sham[page_id], balanced[page_id] = [], [], []

        def add(unit,n):
            j = len(page.lines) + 1
            lid = f'{page_id}.{j}'
            page.lines.append(ivtff.Line(lid,page_id,j,unit,'0',['o']*n,False,False))
            return lid

        for t in range(6):
            add('P',8)
            a, b = add('L',1), add('L',1)
            if (k+t) % 2:
                a,b = b,a
            obj = {'id': f'figure{t+1}', 'kind':'star', 'features': {'shade': f's{1+k}'}, 'label':a}
            primary[page_id].append(obj)
            sham[page_id].append({**obj,'label':b})
            balanced[page_id].append({**obj,'features':{'shade':f's{1+t%3}'}})
            add('P',8)
    return pages, (primary, sham, balanced)


def shape_preserving_shuffle(pages, seed):
    words = [word for p in pages for line in p.lines for word in line.words]
    random.Random(f'{seed}/global-slot-shuffle').shuffle(words)
    filler = iter(words)
    out = []
    for p in pages:
        q = ivtff.Page(p.id,p.order,dict(p.meta))
        out.append(q)
        for line in p.lines:
            q.lines.append(ivtff.Line(line.id,line.page,line.n,line.unit,line.subtype,
                                    [next(filler) for _ in line.words],line.para_start,line.para_end))
    return out


def spec(statistic):
    return {'statistic':{'picture_label':{'test':statistic,'min_objects':MIN_OBJECTS}},
            'compare':[{'op':'>','value':0},
                       {'null':'shuffle_picture_labels','direction':'greater','perms':PERMS,'p':.01}]}


def evaluate(pages, objects, statistic):
    with patch.object(dsl,'PICTURES',objects):
        try:
            r = dsl.evaluate(spec(statistic), pages)
            n = len(dsl._picture_objects(dsl.tokens(pages,None)))
            return {'value':r['value'],'pass':r['pass'],'p':r['detail']['shuffle_picture_labels']['p'], 'objects':n}
        except dsl.SpecError as e:
            return {'undefined':str(e)}


def main():
    public = preflight()
    (WORK/'public-gate.json').write_text(json.dumps(public,indent=2,ensure_ascii=False)+'\n')
    train, _ = corpus.split_pages('practice')
    shape, (primary, sham, balanced) = fixtures()
    results = {}
    # Cache equality-preserving computations on the tiny synthetic fixture. No evaluator is replaced.
    cached_pairs = lru_cache(maxsize=None)(dsl._glyph_pairs)
    with patch.object(dsl, '_glyph_pairs', cached_pairs):
        for seed in SEEDS:
            generated = generators.g_self_citation(train, shape, seed)
            mixed = shape_preserving_shuffle(generated, seed)
            results[seed] = {
                'page_reuse_label_recurrence': evaluate(generated, primary, 'label_in_page_text'),
                'page_reuse_sham_recurrence': evaluate(generated, sham, 'label_in_page_text'),
                'shuffled_slot_recurrence': evaluate(mixed, primary, 'label_in_page_text'),
