"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts.verify_position.py:
"""Independent position-role table and entropy-form check of all recorded scores."""
import bisect
import json
import math
import random
import re
from collections import Counter, defaultdict
from itertools import accumulate
from pathlib import Path

import position_context as experiment

ROOT = Path(__file__).resolve().parent
ROLE = {(True, True): ((True, False), (False, True), (False, False)),
        (True, False): ((True, False), (False, False), (False, True)),
        (False, True): ((False, False), (False, True), (True, False)),
        (False, False): ((False, False), (False, False), (True, True))}


def entropy_js(p, q):
    symbols = sorted(p.keys() | q.keys())
    x = [p[s]/sum(p.values()) for s in symbols]
    y = [q[s]/sum(q.values()) for s in symbols]
    h = lambda v: -math.fsum(t*math.log2(t) for t in v if t)
    return h([(a+b)/2 for a, b in zip(x, y)])-(h(x)+h(y))/2


class Oracle:
    def __init__(self, text):
        self.events = defaultdict(list)
        for match in re.finditer(r'\S+', text):
            word = match.group()
            for i, c in enumerate(word):
                self.events[c].append(((i == 0, i == len(word)-1),
                                       word[i-1] if i else ' ',
                                       word[i+1] if i+1 < len(word) else ' '))
        self.cache = {}

    def context(self, symbol, position, direction):
        key = symbol, position, direction
        if key not in self.cache:
            self.cache[key] = Counter(e[direction] for e in self.events[symbol]
                                      if position is None or e[0] == position)
        return self.cache[key]

    def scores(self, c, a, b):
        result = dict.fromkeys(experiment.METHODS)
        if any(len(self.events[s]) < 40 for s in (c, a, b)):
            return result
        result['unconditioned'] = sum(entropy_js(self.context(c, None, d), self.context(s, None, d))
                                      for s, d in ((a, 1), (b, 2)))/2
        counts = Counter(e[0] for e in self.events[c])
        for method in ('position_all', 'position_info'):
            weighted, observations, informative = [], 0, 0
            valid = True
            for position, n in counts.items():
                ref_a, ref_b, active = ROLE[position]
                selected = (True, True) if method == 'position_all' else active
                informative += n if any(selected) else 0
                for d, symbol, ref, use in ((1, a, ref_a, selected[0]), (2, b, ref_b, selected[1])):
                    if not use:
                        continue
                    comparison = self.context(symbol, ref, d)
                    if sum(comparison.values()) < 20:
                        valid = False
                        break
                    weighted.append(n*entropy_js(self.context(c, position, d), comparison))
                    observations += n
                if not valid:
                    break
            if valid and observations and (method != 'position_info' or informative >= 40):
                result[method] = math.fsum(weighted)/observations
        return result


def compare(actual, recorded):
    maximum = 0
    for m in experiment.METHODS:
        assert (actual[m] is None) == (recorded[m] is None), (m, actual, recorded)
        if actual[m] is not None:
            maximum = max(maximum, abs(actual[m]-recorded[m]))
            assert abs(actual[m]-recorded[m]) < 2e-14, (m, actual, recorded)
    return maximum


def verify_pairs(data):
    rows = data['paired_rows'] + data.get('diagnostics', {}).get('us_um', [])
    count, maximum = 0, 0
    sources = {}
    for r in rows:
        key = r['language'], r['partition']
        if key not in sources:
            sources[key] = experiment.source(*key)
        text = sources[key]
        pairs = experiment.pool(text, r['target'], r['decoy'], r['mode'], r['seed'])
        if r['fraction'] == .5:
            pairs = pairs[:len(pairs)//2]
        oracle = Oracle(experiment.plant(text, pairs))
        for c in ('X', 'Z'):
            values = oracle.scores(c, *r['target'])
            maximum = max(maximum, compare(values, r['scores'][c]))
            for m in experiment.METHODS:
                assert experiment.accept(values[m], data['thresholds'][m]) == experiment.accept(r['scores'][c][m], data['thresholds'][m])
            count += len(experiment.METHODS)
    return count, maximum


def generate(language, seed):
    text = experiment.source(language, 'training').strip()
    counts = defaultdict(Counter)
    for i in range(1, len(text)):
        counts[text[i-1]][text[i]] += 1
    def cdf(cs):
        symbols = sorted(cs)
        return symbols, list(accumulate(cs[s] for s in symbols))
    starts = cdf(Counter(w[0] for w in text.split()))
    normal = {s: cdf(cs) for s, cs in counts.items()}
    final = {s: cdf({t: n for t, n in cs.items() if t != ' '}) for s, cs in counts.items()}
    rng = random.Random(seed)
    def draw(table):
        symbols, cumulative = table
        return symbols[bisect.bisect_right(cumulative, rng.randrange(cumulative[-1]))]
    length = len(experiment.source(language, 'evaluation'))-2
    chars = [draw(starts)]
    for i in range(1, length):
        table = (final if i == length-1 else normal).get(chars[-1])
        chars.append(draw(table if table and table[0] else starts))
    return ' '+''.join(chars)+' '


def verify_negatives(data):
    oracles = {}
    count, maximum = 0, 0
    for row in data['negative_controls']:
        key = row['language'], row['origin'], row['seed']
        if key not in oracles:
            text = experiment.source(row['language'], 'evaluation') if row['origin'] == 'natural' else generate(row['language'], row['seed'])
            assert experiment.sha(text.encode()) == row['sha256']
            oracles[key] = Oracle(text)
        oracle = oracles[key]
        for candidate in row['candidates']:
            values = oracle.scores(candidate['candidate'], *row['target'])
            maximum = max(maximum, compare(values, candidate['scores']))
            for m in experiment.METHODS:
                assert experiment.accept(values[m], data['thresholds'][m]) == candidate['accepted'][m]
            count += len(experiment.METHODS)
    return count, maximum, len(oracles)


def main():
    cal = json.loads((ROOT/'calibration.json').read_bytes())
    ev = json.loads((ROOT/'evaluation.json').read_bytes())
    n1, e1 = verify_pairs(cal)
    n2, e2 = verify_pairs(ev)
    n3, e3, streams = verify_negatives(ev)
    result = {'paired_score_values_including_abstentions': n1+n2,
              'negative_score_values_including_abstentions': n3,
              'negative_stream_hashes_matched': streams,
              'maximum_absolute_score_error': max(e1, e2, e3),
              'all_support_and_acceptance_decisions_match': True}
    experiment.save('verification.json', result)
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()

scripts.position_context.py:
"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts.verify_position.py:
"""Independent position-role table and entropy-form check of all recorded scores."""
import bisect
import json
import math
import random
import re
from collections import Counter, defaultdict
from itertools import accumulate
from pathlib import Path

import position_context as experiment

ROOT = Path(__file__).resolve().parent
ROLE = {(True, True): ((True, False), (False, True), (False, False)),
        (True, False): ((True, False), (False, False), (False, True)),
        (False, True): ((False, False), (False, True), (True, False)),
        (False, False): ((False, False), (False, False), (True, True))}


def entropy_js(p, q):
    symbols = sorted(p.keys() | q.keys())
    x = [p[s]/sum(p.values()) for s in symbols]
    y = [q[s]/sum(q.values()) for s in symbols]
    h = lambda v: -math.fsum(t*math.log2(t) for t in v if t)
    return h([(a+b)/2 for a, b in zip(x, y)])-(h(x)+h(y))/2


class Oracle:
    def __init__(self, text):
        self.events = defaultdict(list)
        for match in re.finditer(r'\S+', text):
            word = match.group()
            for i, c in enumerate(word):
                self.events[c].append(((i == 0, i == len(word)-1),
                                       word[i-1] if i else ' ',
                                       word[i+1] if i+1 < len(word) else ' '))
        self.cache = {}

    def context(self, symbol, position, direction):
        key = symbol, position, direction
        if key not in self.cache:
            self.cache[key] = Counter(e[direction] for e in self.events[symbol]
                                      if position is None or e[0] == position)
        return self.cache[key]

    def scores(self, c, a, b):
        result = dict.fromkeys(experiment.METHODS)
        if any(len(self.events[s]) < 40 for s in (c, a, b)):
            return result
        result['unconditioned'] = sum(entropy_js(self.context(c, None, d), self.context(s, None, d))
                                      for s, d in ((a, 1), (b, 2)))/2
        counts = Counter(e[0] for e in self.events[c])
        for method in ('position_all', 'position_info'):
            weighted, observations, informative = [], 0, 0
            valid = True
            for position, n in counts.items():
                ref_a, ref_b, active = ROLE[position]
                selected = (True, True) if method == 'position_all' else active
                informative += n if any(selected) else 0
                for d, symbol, ref, use in ((1, a, ref_a, selected[0]), (2, b, ref_b, selected[1])):
                    if not use:
                        continue
                    comparison = self.context(symbol, ref, d)
                    if sum(comparison.values()) < 20:
                        valid = False
                        break
                    weighted.append(n*entropy_js(self.context(c, position, d), comparison))
                    observations += n
                if not valid:
                    break
            if valid and observations and (method != 'position_info' or informative >= 40):
                result[method] = math.fsum(weighted)/observations
        return result


def compare(actual, recorded):
    maximum = 0
    for m in experiment.METHODS:
        assert (actual[m] is None) == (recorded[m] is None), (m, actual, recorded)
        if actual[m] is not None:
            maximum = max(maximum, abs(actual[m]-recorded[m]))
            assert abs(actual[m]-recorded[m]) < 2e-14, (m, actual, recorded)
    return maximum


def verify_pairs(data):
    rows = data['paired_rows'] + data.get('diagnostics', {}).get('us_um', [])
    count, maximum = 0, 0
    sources = {}
    for r in rows:
        key = r['language'], r['partition']
        if key not in sources:
            sources[key] = experiment.source(*key)
        text = sources[key]
        pairs = experiment.pool(text, r['target'], r['decoy'], r['mode'], r['seed'])
        if r['fraction'] == .5:
            pairs = pairs[:len(pairs)//2]
        oracle = Oracle(experiment.plant(text, pairs))
        for c in ('X', 'Z'):
            values = oracle.scores(c, *r['target'])
            maximum = max(maximum, compare(values, r['scores'][c]))
            for m in experiment.METHODS:
                assert experiment.accept(values[m], data['thresholds'][m]) == experiment.accept(r['scores'][c][m], data['thresholds'][m])
            count += len(experiment.METHODS)
    return count, maximum


def generate(language, seed):
    text = experiment.source(language, 'training').strip()
    counts = defaultdict(Counter)
    for i in range(1, len(text)):
        counts[text[i-1]][text[i]] += 1
    def cdf(cs):
        symbols = sorted(cs)
        return symbols, list(accumulate(cs[s] for s in symbols))
    starts = cdf(Counter(w[0] for w in text.split()))
    normal = {s: cdf(cs) for s, cs in counts.items()}
    final = {s: cdf({t: n for t, n in cs.items() if t != ' '}) for s, cs in counts.items()}
    rng = random.Random(seed)
    def draw(table):
        symbols, cumulative = table
        return symbols[bisect.bisect_right(cumulative, rng.randrange(cumulative[-1]))]
    length = len(experiment.source(language, 'evaluation'))-2
    chars = [draw(starts)]
    for i in range(1, length):
        table = (final if i == length-1 else normal).get(chars[-1])
        chars.append(draw(table if table and table[0] else starts))
    return ' '+''.join(chars)+' '


def verify_negatives(data):
    oracles = {}
    count, maximum = 0, 0
    for row in data['negative_controls']:
        key = row['language'], row['origin'], row['seed']
        if key not in oracles:
            text = experiment.source(row['language'], 'evaluation') if row['origin'] == 'natural' else generate(row['language'], row['seed'])
            assert experiment.sha(text.encode()) == row['sha256']
            oracles[key] = Oracle(text)
        oracle = oracles[key]
        for candidate in row['candidates']:
            values = oracle.scores(candidate['candidate'], *row['target'])
            maximum = max(maximum, compare(values, candidate['scores']))
            for m in experiment.METHODS:
                assert experiment.accept(values[m], data['thresholds'][m]) == candidate['accepted'][m]
            count += len(experiment.METHODS)
    return count, maximum, len(oracles)


def main():
    cal = json.loads((ROOT/'calibration.json').read_bytes())
    ev = json.loads((ROOT/'evaluation.json').read_bytes())
    n1, e1 = verify_pairs(cal)
    n2, e2 = verify_pairs(ev)
    n3, e3, streams = verify_negatives(ev)
    result = {'paired_score_values_including_abstentions': n1+n2,
              'negative_score_values_including_abstentions': n3,
              'negative_stream_hashes_matched': streams,
              'maximum_absolute_score_error': max(e1, e2, e3),
              'all_support_and_acceptance_decisions_match': True}
    experiment.save('verification.json', result)
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()

scripts.audit_gaps.py:
"""Independent public paragraph-gap and intact-word-null audit."""
import hashlib
import json
import math
import random
from collections import Counter
from pathlib import Path
from statistics import mean

import numpy as np
import bench
from vs import corpus, gaps

ROOT = Path(__file__).resolve().parent
SHORT = tuple(range(1, 6))
SEEDS = (408, 19026011, 28027)


def save(name, data):
    (ROOT/name).write_bytes((json.dumps(data, indent=2)+'\n').encode())


def independent_layout(pages, selected):
    book = []
    for page in pages:
        paragraphs, current = [], []
        for line in page.lines:
            if line.unit != 'P':
                continue
            admitted = line.id in selected
            if current and (line.para_start or not admitted):
                paragraphs.append(current)
                current = []
            if admitted:
                current.append(list(line.words))
            if current and line.para_end:
                paragraphs.append(current)
                current = []
        if current:
            paragraphs.append(current)
        if paragraphs:
            book.append((page.id, paragraphs))
    return book


def hit_positions(words, symbol):
    positions, offset = [], 0
    for word in words:
        for i in range(len(word)):
            if word[i:i+1] == symbol:
                positions.append(offset+i)
        offset += len(word)+1
    return positions


def curve(groups, lags):
    residuals = []
    for hits in groups:
        differences = [hits[i]-hits[i-1] for i in range(1, len(hits))]
        if len(differences) > 2:
            average = math.fsum(differences)/len(differences)
            residuals.append([d-average for d in differences])
    out = {}
    for lag in lags:
        moments, pairs = [], 0
        for residual in residuals:
            if len(residual) <= lag+1:
                continue
            x, y = residual[:-lag], residual[lag:]
            pairs += len(x)
            moments.append((math.fsum(v*v for v in x), math.fsum(v*v for v in y),
                            math.fsum(a*b for a, b in zip(x, y))))
        xx, yy, xy = [math.fsum(row[k] for row in moments) for k in range(3)]
        out[lag] = (xy/math.sqrt(xx*yy) if pairs >= 25 and xx and yy else None, pairs)
    return out


def shuffled_runs(lines_by_run, rng, linewise):
    for lines in lines_by_run:
        if linewise:
            words = []
            for line in lines:
                copy = list(line)
                rng.shuffle(copy)
                words.extend(copy)
        else:
            words = [w for line in lines for w in line]
            rng.shuffle(words)
        yield words


def word_test(lines_by_run, symbol, permutations, seed, linewise=False):
    words = [[w for line in run for w in line] for run in lines_by_run]
    observed = curve([hit_positions(run, symbol) for run in words], SHORT)
    rng = random.Random(seed)
    draws = []
    maximum_error = 0.0
    for i in range(permutations):
        shuffled = list(shuffled_runs(lines_by_run, rng, linewise))
        if i == 0:
            assert all(Counter(original) == Counter(new) for original, new in zip(words, shuffled))
        hits = [hit_positions(run, symbol) for run in shuffled]
        measured = curve(hits, SHORT)
        if i % 97 == 0:
            reference = gaps.gap_curve(hits, SHORT)
            for lag in SHORT:
                assert measured[lag][1] == reference[lag][1]
                assert (measured[lag][0] is None) == (reference[lag][0] is None)
                if measured[lag][0] is not None:
                    maximum_error = max(maximum_error, abs(measured[lag][0]-reference[lag][0]))
                    assert abs(measured[lag][0]-reference[lag][0]) < 1e-12
        draws.append(measured)
    usable = [lag for lag in SHORT if all(c[lag][0] is not None for c in [observed, *draws])]
    result = {'seed': seed, 'permutations': permutations, 'linewise': linewise,
              'pairs_by_lag': {str(lag): observed[lag][1] for lag in SHORT}, 'lags': usable,
              'observed': None, 'null_mean': None, 'p': None, 'maximum_merged_curve_error': maximum_error}
    if usable:
        statistic = mean(observed[lag][0] for lag in usable)
        values = [mean(draw[lag][0] for lag in usable) for draw in draws]
        upper = sum(value >= statistic-1e-12 for value in values)
        ordered = sorted(values)
        result.update(observed=statistic, null_mean=mean(values), excess=statistic-mean(values),
                      p=(1+upper)/(permutations+1), exceedances=upper,
                      null_quantiles={str(q): ordered[round(q*(len(ordered)-1))] for q in (.025, .5, .975)},
                      draw_statistics=values)
    return result


def differences(a, b, path=''):
    errors = []
    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            return [path+': keys differ']
        for key in a:
            errors += differences(a[key], b[key], path+'/'+str(key))
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return [path+': lengths differ']
        for i, (x, y) in enumerate(zip(a, b)):
            errors += differences(x, y, path+'/'+str(i))
    elif isinstance(a, (float, int)) and isinstance(b, (float, int)):
        if not math.isclose(a, b, rel_tol=1e-12, abs_tol=1e-12):
            errors.append(path+': '+repr(a)+' != '+repr(b))
    elif a != b:
        errors.append(path+': '+repr(a)+' != '+repr(b))
    return errors


def published_observation(books, matched):
    outputs = {}
    maximum_error = 0.0
    for edition, book in books.items():
        slots, pages, slices = bench.masks(book)
        outputs[edition] = {}
        for index, symbol in enumerate(('o', 'r')):
            rng = np.random.default_rng(np.random.SeedSequence([bench.SEED, 100, index]))
            hits = bench.observed(book, symbol)
            scores = bench.compare(hits, slots, pages, slices, 99, rng)
            scores.update(bench.word_order_comparison(book, symbol, hits, slices, 99, rng))
            independent = curve([list(h) for h in hits], bench.LAGS)
            reference, counts = bench.gap_curve([h[None, :] for h in hits], True)
            for lag in bench.LAGS:
                assert independent[lag][1] == counts[lag]
                if independent[lag][0] is not None:
                    error = abs(independent[lag][0]-reference[0, lag])
                    maximum_error = max(maximum_error, float(error))
                    assert error < 1e-12
            outputs[edition][symbol] = {'hits': sum(map(len, hits)), 'slots': sum(map(len, pages)), 'scores': scores}
    actual = {'matched_lines': len(matched),
              'layouts': {edition: {'pages': len(book), 'runs': sum(len(groups) for _, groups in book)} for edition, book in books.items()},
              'results': outputs}
    expected = json.loads((ROOT/'published-record.json').read_bytes())['detail']['observed_practice']
    errors = differences(actual, expected)
    save('published-observation.json', actual)
    assert not errors, errors[:10]
    return {'all_published_observation_fields_match': True, 'maximum_independent_curve_error': maximum_error}


def main():
    assert hashlib.sha256((ROOT/'bench.py').read_bytes()).hexdigest() == '7fdadf75a4790f458be50373a69afbbd48ed6409c3729114e709b8eaa318d12a'
    practice = {edition: corpus.split_pages('practice', edition)[1] for edition in ('zl', 'it')}
    eligible = {}
    for edition, pages in practice.items():
        eligible[edition] = {line.id for page in pages for line in page.lines
                             if line.unit == 'P' and line.words and not any(set(w)-set('acdefghiklmnopqrsty') for w in line.words)}
    retained = eligible['zl'] & eligible['it']
    assert retained == gaps.eligible_line_ids(practice['zl']) & gaps.eligible_line_ids(practice['it'])
    books = {edition: bench.template(bench.layout(pages, retained)) for edition, pages in practice.items()}
    result = {'matched_lines': len(retained), 'published_observation_audit': published_observation(books, retained),
              'editions': {}}
    for edition, pages in practice.items():
        own = independent_layout(pages, retained)
        lines_by_run = [run for _, runs in own for run in runs]
        words = [[w for line in run for w in line] for run in lines_by_run]
        assert words == gaps.paragraph_runs(pages, retained)
        assert len(words) == sum(len(groups) for _, groups in books[edition])
        measurements = []
        for seed in SEEDS:
            for linewise in (False, True):
                item = word_test(lines_by_run, 'o', 999, seed, linewise)
                if seed == 408 and not linewise:
                    reference = gaps.word_order_test(words, 'o', 399)
                    own399 = item['draw_statistics'][:399]
                    assert math.isclose(reference['observed'], item['observed'], abs_tol=1e-12)
                    assert math.isclose(reference['null_mean'], mean(own399), abs_tol=1e-12)
                    assert reference['p'] == (1+sum(x >= item['observed']-1e-12 for x in own399))/400
                    item['merged_default_399'] = reference
                measurements.append(item)
        null_books = []
        for index in range(32):
            rng = random.Random(991307+index)
            shuffled = [[list(run)] for run in shuffled_runs(lines_by_run, rng, False)]
            item = word_test(shuffled, 'o', 99, 55201+index)
            item.pop('draw_statistics', None)
            null_books.append({'index': index, **item})
        result['editions'][edition] = {'pages': len(own), 'runs': len(lines_by_run),
            'words': sum(map(len, words)), 'run_word_stock_sha256': hashlib.sha256(json.dumps(words).encode()).hexdigest(),
            'measurements': measurements, 'word_null_calibration': null_books,
            'word_null_rejections_at_005': sum(r['p'] is not None and r['p'] <= .05 for r in null_books)}
    save('audit.json', result)
    print(json.dumps({'matched_lines': len(retained), 'editions': {
        e: {'pages': d['pages'], 'runs': d['runs'], 'null_rejections': d['word_null_rejections_at_005'],
            'measurements': [{k:v for k,v in r.items() if k not in ('draw_statistics', 'merged_default_399')} for r in d['measurements']]}
        for e,d in result['editions'].items()}}, indent=2))


if __name__ == '__main__':
    main()

scripts.bench.py:
"""Public experimental calibration for conditional EVA occurrence-gap tests."""
import argparse
import json
from pathlib import Path
import sys

import numpy as np

sys.path.insert(0, str(Path.cwd()))
from vs import corpus

ALPHABET = frozenset('acdefghiklmnopqrsty')
BANDS = {'short_1_5': tuple(range(1, 6)), 'long_11_40': tuple(range(11, 41)), 'lag_20': (20,)}
LAGS = tuple(sorted({i for band in BANDS.values() for i in band}))
MAX_LAG = max(LAGS)
BASE_RATE = 0.16
SEED = 19026011
MIN_PAIRS = 25
RUNS = 64
PERMUTATIONS = 99
ALPHA = 0.05
SCENARIOS = (
    ('iid_constant', 'iid', 0.0, 0.0),
    ('iid_page_rate_shifts', 'iid', 1.2, 0.0),
    ('iid_paragraph_rate_shifts', 'iid', 0.0, 1.2),
    ('iid_page_and_paragraph_shifts', 'iid', 1.2, 1.2),
    ('bursts_amplitude_0_20', 'burst', 0.20, 5.0),
    ('bursts_amplitude_0_45', 'burst', 0.45, 5.0),
    ('bursts_amplitude_0_75', 'burst', 0.75, 5.0),
    ('lag20_copy_probability_0_30', 'gap_copy', 0.30, 20),
    ('lag20_copy_probability_0_80', 'gap_copy', 0.80, 20),
)


def line_ids(pages):
    return {line.id for page in pages for line in page.lines
            if line.unit == 'P' and line.words and all(set(w) <= ALPHABET for w in line.words)}


def layout(pages, keep):
    books = []
    for page in pages:
        paragraphs = []
        paragraph = []
        for line in page.lines:
            if line.unit != 'P':
                continue
            if (line.para_start or line.id not in keep) and paragraph:
                paragraphs.append(paragraph)
                paragraph = []
            if line.id in keep:
                paragraph.append((line.id, ' '.join(line.words)))
            if line.para_end and paragraph:
                paragraphs.append(paragraph)
                paragraph = []
        if paragraph:
            paragraphs.append(paragraph)
        if paragraphs:
            books.append((page.id, paragraphs))
    return books


def template(book):
    offset = 0
    pages = []
    for page_id, paragraphs in book:
        groups = []
        for lines in paragraphs:
            text = ' '.join(text for _, text in lines)
            positions = np.fromiter((offset + i for i, c in enumerate(text) if c != ' '), dtype=np.int32)
            groups.append((lines[0][0], text, positions, offset))
            offset += len(text) + 1
        pages.append((page_id, groups))
    return pages


def masks(book):
    paragraphs = [g[2] for _, groups in book for g in groups]
    group_ids = []
    start = 0
    for _, groups in book:
        group_ids.append(slice(start, start + len(groups)))
        start += len(groups)
    pages = [np.concatenate(paragraphs[s]) for s in group_ids]
    return paragraphs, pages, group_ids


def concatenate_groups(paragraphs, group_slices):
    return [np.concatenate(paragraphs[s], axis=-1) for s in group_slices]


def sample_positions(slots, count, repetitions, rng):
    if not count:
        return np.empty((repetitions, 0), dtype=np.int32)
    scores = rng.random((repetitions, len(slots)))
    draw = np.argpartition(scores, count - 1, axis=1)[:, :count]
    draw.sort(axis=1)
    return slots[draw]


def gap_curve(groups, centered):
    repetitions = groups[0].shape[0]
    counts = np.zeros(MAX_LAG + 1, dtype=np.int64)
    moments = np.zeros((5, repetitions, MAX_LAG + 1))
    for hits in groups:
        gaps = np.diff(hits, axis=1).astype(np.float64)
        n = gaps.shape[1]
        if n <= 2:
            continue
        if centered:
            gaps -= gaps.mean(axis=1, keepdims=True)
        for h in LAGS:
            if n <= h + 1:
                break
            x, y = gaps[:, :-h], gaps[:, h:]
            counts[h] += n - h
            moments[0, :, h] += x.sum(axis=1)
            moments[1, :, h] += y.sum(axis=1)
            moments[2, :, h] += np.einsum('ij,ij->i', x, x)
            moments[3, :, h] += np.einsum('ij,ij->i', y, y)
            moments[4, :, h] += np.einsum('ij,ij->i', x, y)
    x, y, xx, yy, xy = moments
    with np.errstate(divide='ignore', invalid='ignore'):
        if centered:
            coefficient = xy / np.sqrt(xx * yy)
        else:
            coefficient = (xy - x * y / counts) / np.sqrt((xx - x*x/counts)*(yy-y*y/counts))
    coefficient[:, counts < MIN_PAIRS] = np.nan
    return coefficient, counts


def outcome(groups, centered):
    curve, counts = gap_curve(groups, centered)
    result = {}
    for name, lags in BANDS.items():
        lags = np.asarray(lags)
        viable = lags[np.isfinite(curve[:, lags]).all(axis=0)]
        if not len(viable):
            result[name] = None
            continue
        samples = curve[:, viable].mean(axis=1)
        first, simulations = samples[0], samples[1:]
        p = (1 + np.count_nonzero(simulations >= first - 1e-12)) / len(samples)
        result[name] = {'observed': float(first), 'null_mean': float(simulations.mean()),
                        'p': float(p), 'lags': int(len(viable)),
                        'pairs_by_lag': {str(h): int(counts[h]) for h in viable}}
    return result


def with_observed(obs, nulls):
    return [np.concatenate((first[None,:], otherwise), axis=0)
            for first, otherwise in zip(obs, nulls, strict=True)]


def compare(observed, paragraph_slots, page_slots, slices, repetitions, rng):
    actual_pages = concatenate_groups(observed, slices)
    actual_global = np.concatenate(actual_pages)
    null_paragraphs = [sample_positions(slots, len(hits), repetitions, rng)
                       for slots, hits in zip(paragraph_slots, observed, strict=True)]
    null_pages = [sample_positions(slots, len(hits), repetitions, rng)
                  for slots, hits in zip(page_slots, actual_pages, strict=True)]
    both_paragraphs = with_observed(observed, null_paragraphs)
    both_pages = with_observed(actual_pages, null_pages)
    global_null = [sample_positions(np.concatenate(page_slots), len(actual_global), repetitions, rng)]
    return {
        'pooled_given_global_count': outcome(with_observed([actual_global], global_null), False),
        'page_centered_given_page_counts': outcome(both_pages, True),
        'page_centered_given_paragraph_counts': outcome(concatenate_groups(both_paragraphs, slices), True),
        'paragraph_centered_given_paragraph_counts': outcome(both_paragraphs, True),
    }


def adjusted_rates(lengths, contrast, target):
    offsets = contrast * np.where(np.arange(len(lengths)) % 2 == 0, -1., 1.)
    low, high = -35., 35.
    for _ in range(60):
        midpoint = (low + high) / 2
        rates = 1 / (1 + np.exp(-(midpoint + offsets)))
        if np.average(rates, weights=lengths) < target:
            low = midpoint
        else:
            high = midpoint
    return 1 / (1 + np.exp(-((low + high) / 2 + offsets)))


def burst_hits(length, amplitude, lifetime_gaps, rng):
    resample = -np.expm1(-BASE_RATE / lifetime_gaps)
    transitions = np.flatnonzero(rng.random(length) < resample)
    states = rng.choice([-1., 1.], size=len(transitions) + 1)
    lifecycle = np.searchsorted(transitions, np.arange(length), side='right')
    rates = BASE_RATE * (1 + amplitude * states[lifecycle])
    return np.flatnonzero(rng.random(length) < rates)


def recurrence_hits(length, probability, lag, rng):
    eligible = length + 1200
    past = rng.geometric(BASE_RATE, size=lag)
    out = []
    at = 0
    i = 0
    while at < eligible:
        for j in range(lag):
            if i == 0 or rng.random() >= probability:
                if i > 0:
                    past[j] = rng.geometric(BASE_RATE)
            at += past[j]
            if 1200 <= at < eligible:
                out.append(at - 1200)
        i += 1
    return np.asarray(out, dtype=int)


def synthetic(regime, paragraph_slots, page_slots, slices, rng):
    _, name, a, b = regime
    if name == 'iid':
        rates = adjusted_rates([len(slot) for slot in page_slots], a, BASE_RATE)
        assigned = []
        for s, p in zip(slices, rates, strict=True):
            assigned.extend(adjusted_rates([len(slot) for slot in paragraph_slots[s]], b, p))
        return [slots[np.flatnonzero(rng.random(len(slots)) < p)]
                for slots, p in zip(paragraph_slots, assigned, strict=True)]
    found = []
    for slots, s in zip(page_slots, slices, strict=True):
        indices = burst_hits(len(slots), a, b, rng) if name == 'burst' else recurrence_hits(len(slots), a, b, rng)
        page_hits = slots[indices]
        for para in paragraph_slots[s]:
            start = np.searchsorted(page_hits, para[0], side='left')
            end = np.searchsorted(page_hits, para[-1], side='right')
            found.append(page_hits[start:end])
    return found


def observed(book, symbol):
    return [np.fromiter((offset + i for i, c in enumerate(text) if c == symbol), dtype=np.int32)
            for _, groups in book for _,text,_,offset in groups]


def word_order_comparison(book, symbol, actual, slices, repetitions, rng):
    draws = []
    for _, groups in book:
        for _, text, _, offset in groups:
            words = text.split()
            shuffled = []
            for _ in range(repetitions):
                trial = ' '.join(rng.permutation(words))
                shuffled.append([offset + i for i, c in enumerate(trial) if c == symbol])
            draws.append(np.asarray(shuffled, dtype=np.int32))
    paired = with_observed(actual, draws)
    return {
        'page_centered_given_paragraph_word_multisets': outcome(concatenate_groups(paired, slices), True),
        'paragraph_centered_given_paragraph_word_multisets': outcome(paired, True),
    }


def scalar_lag_stats(row):
    flat = {}
    for kind, bands in row.items():
        for band, values in bands.items():
            if values is not None:
                flat[kind + '/' + band] = values
    return flat


def run_scenario(index, book, runs, permutations):
    rng = np.random.default_rng(np.random.SeedSequence([SEED, index]))
    pslots, pages, slices = masks(book)
    regime = SCENARIOS[index]
    data = []
    for iteration in range(runs):
        hits = synthetic(regime, pslots, pages, slices, rng)
        row = scalar_lag_stats(compare(hits, pslots, pages, slices, permutations, rng))
        data.append({'hit_count':sum(len(h) for h in hits),'scores':row})
    return {'regime':regime, 'total_slots':sum(map(len,pages)), 'replicates':data}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--scenario', type=int, choices=range(len(SCENARIOS)))
    mode.add_argument('--observe', action='store_true')
    parser.add_argument('--runs', type=int, default=RUNS)
    parser.add_argument('--permutations', type=int, default=PERMUTATIONS)
    args = parser.parse_args()
    practice = {code: corpus.split_pages('practice', code)[1] for code in ('zl', 'it')}
    matched = line_ids(practice['zl']) & line_ids(practice['it'])
    books = {code:template(layout(pages,matched)) for code,pages in practice.items()}
    if args.observe:
        outputs = {}
        for code, book in books.items():
            pslots, pages, slices = masks(book)
            outputs[code] = {}
            for i, symbol in enumerate(('o','r')):
                rng = np.random.default_rng(np.random.SeedSequence([SEED, 100, i]))
                hits = observed(book, symbol)
                scores = compare(hits, pslots, pages, slices, args.permutations, rng)
                scores.update(word_order_comparison(book, symbol, hits, slices, args.permutations, rng))
                outputs[code][symbol] = {'hits':sum(map(len,hits)), 'slots':sum(map(len,pages)),
                                         'scores':scores}
        print(json.dumps({'matched_lines':len(matched),'layouts':{code: {'pages':len(book), 'runs':sum(len(groups) for _,groups in book)} for code,book in books.items()}, 'results':outputs}, sort_keys=True))
    else:
        print(json.dumps(run_scenario(args.scenario, books['zl'], args.runs, args.permutations), sort_keys=True))


if __name__ == '__main__':
    main()

scripts.audit_gaps.py:
"""Independent public paragraph-gap and intact-word-null audit."""
import hashlib
import json
import math
import random
from collections import Counter
from pathlib import Path
from statistics import mean

import numpy as np
import bench
from vs import corpus, gaps

ROOT = Path(__file__).resolve().parent
SHORT = tuple(range(1, 6))
SEEDS = (408, 19026011, 28027)


def save(name, data):
    (ROOT/name).write_bytes((json.dumps(data, indent=2)+'\n').encode())


def independent_layout(pages, selected):
    book = []
    for page in pages:
        paragraphs, current = [], []
        for line in page.lines:
            if line.unit != 'P':
                continue
            admitted = line.id in selected
            if current and (line.para_start or not admitted):
                paragraphs.append(current)
                current = []
            if admitted:
                current.append(list(line.words))
            if current and line.para_end:
                paragraphs.append(current)
                current = []
        if current:
            paragraphs.append(current)
        if paragraphs:
            book.append((page.id, paragraphs))
    return book


def hit_positions(words, symbol):
    positions, offset = [], 0
    for word in words:
        for i in range(len(word)):
            if word[i:i+1] == symbol:
                positions.append(offset+i)
        offset += len(word)+1
    return positions


def curve(groups, lags):
    residuals = []
    for hits in groups:
        differences = [hits[i]-hits[i-1] for i in range(1, len(hits))]
        if len(differences) > 2:
            average = math.fsum(differences)/len(differences)
            residuals.append([d-average for d in differences])
    out = {}
    for lag in lags:
        moments, pairs = [], 0
        for residual in residuals:
            if len(residual) <= lag+1:
                continue
            x, y = residual[:-lag], residual[lag:]
            pairs += len(x)
            moments.append((math.fsum(v*v for v in x), math.fsum(v*v for v in y),
                            math.fsum(a*b for a, b in zip(x, y))))
        xx, yy, xy = [math.fsum(row[k] for row in moments) for k in range(3)]
        out[lag] = (xy/math.sqrt(xx*yy) if pairs >= 25 and xx and yy else None, pairs)
    return out


def shuffled_runs(lines_by_run, rng, linewise):
    for lines in lines_by_run:
        if linewise:
            words = []
            for line in lines:
                copy = list(line)
                rng.shuffle(copy)
                words.extend(copy)
        else:
            words = [w for line in lines for w in line]
            rng.shuffle(words)
        yield words


def word_test(lines_by_run, symbol, permutations, seed, linewise=False):
    words = [[w for line in run for w in line] for run in lines_by_run]
    observed = curve([hit_positions(run, symbol) for run in words], SHORT)
    rng = random.Random(seed)
    draws = []
    maximum_error = 0.0
    for i in range(permutations):
        shuffled = list(shuffled_runs(lines_by_run, rng, linewise))
        if i == 0:
            assert all(Counter(original) == Counter(new) for original, new in zip(words, shuffled))
        hits = [hit_positions(run, symbol) for run in shuffled]
        measured = curve(hits, SHORT)
        if i % 97 == 0:
            reference = gaps.gap_curve(hits, SHORT)
            for lag in SHORT:
                assert measured[lag][1] == reference[lag][1]
                assert (measured[lag][0] is None) == (reference[lag][0] is None)
                if measured[lag][0] is not None:
                    maximum_error = max(maximum_error, abs(measured[lag][0]-reference[lag][0]))
                    assert abs(measured[lag][0]-reference[lag][0]) < 1e-12
        draws.append(measured)
    usable = [lag for lag in SHORT if all(c[lag][0] is not None for c in [observed, *draws])]
    result = {'seed': seed, 'permutations': permutations, 'linewise': linewise,
              'pairs_by_lag': {str(lag): observed[lag][1] for lag in SHORT}, 'lags': usable,
              'observed': None, 'null_mean': None, 'p': None, 'maximum_merged_curve_error': maximum_error}
    if usable:
        statistic = mean(observed[lag][0] for lag in usable)
        values = [mean(draw[lag][0] for lag in usable) for draw in draws]
        upper = sum(value >= statistic-1e-12 for value in values)
        ordered = sorted(values)
        result.update(observed=statistic, null_mean=mean(values), excess=statistic-mean(values),
                      p=(1+upper)/(permutations+1), exceedances=upper,
                      null_quantiles={str(q): ordered[round(q*(len(ordered)-1))] for q in (.025, .5, .975)},
                      draw_statistics=values)
    return result


def differences(a, b, path=''):
    errors = []
    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            return [path+': keys differ']
        for key in a:
            errors += differences(a[key], b[key], path+'/'+str(key))
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return [path+': lengths differ']
        for i, (x, y) in enumerate(zip(a, b)):
            errors += differences(x, y, path+'/'+str(i))
    elif isinstance(a, (float, int)) and isinstance(b, (float, int)):
        if not math.isclose(a, b, rel_tol=1e-12, abs_tol=1e-12):
            errors.append(path+': '+repr(a)+' != '+repr(b))
    elif a != b:
        errors.append(path+': '+repr(a)+' != '+repr(b))
    return errors


def published_observation(books, matched):
    outputs = {}
    maximum_error = 0.0
    for edition, book in books.items():
        slots, pages, slices = bench.masks(book)
        outputs[edition] = {}
        for index, symbol in enumerate(('o', 'r')):
            rng = np.random.default_rng(np.random.SeedSequence([bench.SEED, 100, index]))
            hits = bench.observed(book, symbol)
            scores = bench.compare(hits, slots, pages, slices, 99, rng)
            scores.update(bench.word_order_comparison(book, symbol, hits, slices, 99, rng))
            independent = curve([list(h) for h in hits], bench.LAGS)
            reference, counts = bench.gap_curve([h[None, :] for h in hits], True)
            for lag in bench.LAGS:
                assert independent[lag][1] == counts[lag]
                if independent[lag][0] is not None:
                    error = abs(independent[lag][0]-reference[0, lag])
                    maximum_error = max(maximum_error, float(error))
                    assert error < 1e-12
            outputs[edition][symbol] = {'hits': sum(map(len, hits)), 'slots': sum(map(len, pages)), 'scores': scores}
    actual = {'matched_lines': len(matched),
              'layouts': {edition: {'pages': len(book), 'runs': sum(len(groups) for _, groups in book)} for edition, book in books.items()},
              'results': outputs}
    expected = json.loads((ROOT/'published-record.json').read_bytes())['detail']['observed_practice']
    errors = differences(actual, expected)
    save('published-observation.json', actual)
    assert not errors, errors[:10]
    return {'all_published_observation_fields_match': True, 'maximum_independent_curve_error': maximum_error}


def main():
    assert hashlib.sha256((ROOT/'bench.py').read_bytes()).hexdigest() == '7fdadf75a4790f458be50373a69afbbd48ed6409c3729114e709b8eaa318d12a'
    practice = {edition: corpus.split_pages('practice', edition)[1] for edition in ('zl', 'it')}
    eligible = {}
    for edition, pages in practice.items():
        eligible[edition] = {line.id for page in pages for line in page.lines
                             if line.unit == 'P' and line.words and not any(set(w)-set('acdefghiklmnopqrsty') for w in line.words)}
    retained = eligible['zl'] & eligible['it']
    assert retained == gaps.eligible_line_ids(practice['zl']) & gaps.eligible_line_ids(practice['it'])
    books = {edition: bench.template(bench.layout(pages, retained)) for edition, pages in practice.items()}
    result = {'matched_lines': len(retained), 'published_observation_audit': published_observation(books, retained),
              'editions': {}}
    for edition, pages in practice.items():
        own = independent_layout(pages, retained)
        lines_by_run = [run for _, runs in own for run in runs]
        words = [[w for line in run for w in line] for run in lines_by_run]
        assert words == gaps.paragraph_runs(pages, retained)
        assert len(words) == sum(len(groups) for _, groups in books[edition])
        measurements = []
        for seed in SEEDS:
            for linewise in (False, True):
                item = word_test(lines_by_run, 'o', 999, seed, linewise)
                if seed == 408 and not linewise:
                    reference = gaps.word_order_test(words, 'o', 399)
                    own399 = item['draw_statistics'][:399]
                    assert math.isclose(reference['observed'], item['observed'], abs_tol=1e-12)
                    assert math.isclose(reference['null_mean'], mean(own399), abs_tol=1e-12)
                    assert reference['p'] == (1+sum(x >= item['observed']-1e-12 for x in own399))/400
                    item['merged_default_399'] = reference
                measurements.append(item)
        null_books = []
        for index in range(32):
            rng = random.Random(991307+index)
            shuffled = [[list(run)] for run in shuffled_runs(lines_by_run, rng, False)]
            item = word_test(shuffled, 'o', 99, 55201+index)
            item.pop('draw_statistics', None)
            null_books.append({'index': index, **item})
        result['editions'][edition] = {'pages': len(own), 'runs': len(lines_by_run),
            'words': sum(map(len, words)), 'run_word_stock_sha256': hashlib.sha256(json.dumps(words).encode()).hexdigest(),
            'measurements': measurements, 'word_null_calibration': null_books,
            'word_null_rejections_at_005': sum(r['p'] is not None and r['p'] <= .05 for r in null_books)}
    save('audit.json', result)
    print(json.dumps({'matched_lines': len(retained), 'editions': {
        e: {'pages': d['pages'], 'runs': d['runs'], 'null_rejections': d['word_null_rejections_at_005'],
            'measurements': [{k:v for k,v in r.items() if k not in ('draw_statistics', 'merged_default_399')} for r in d['measurements']]}
        for e,d in result['editions'].items()}}, indent=2))


if __name__ == '__main__':
    main()

