"""The stationary order-two/order-four line writer described in P-R-009."""

from collections import Counter, defaultdict, deque
import random

from vs import dsl


SPACE = " "
END = "$"
ORDER_SHORT = 2
ORDER_LONG = 4
WORD_MEMORY = 300


def start_for(opener):
    return ("^P" if opener else "^L",) * ORDER_LONG


def layout_lines(pages):
    for page_index, page in enumerate(pages):
        first_line = True
        for line in page.lines:
            if not line.words:
                continue
            paragraph = line.unit == "P"
            opener = paragraph and (line.para_start or first_line)
            yield page_index, page.section, line, opener
            if paragraph:
                first_line = line.para_end


def learn(pages):
    contexts = {order: defaultdict(Counter) for order in (0, 1, ORDER_SHORT, ORDER_LONG)}
    for _, _, line, opener in layout_lines(pages):
        if line.unit != "P" or any("?" in word or "*" in word for word in line.words):
            continue
        symbols = []
        for word in line.words:
            symbols.extend(dsl.SEG(word))
            symbols.append(SPACE)
        symbols[-1] = END
        history = list(start_for(opener))
        for glyph in symbols:
            for order, table in contexts.items():
                context = tuple(history[-order:]) if order else ()
                table[context][glyph] += 1
            history.append(glyph)
    return contexts


class Writer:
    def __init__(self, contexts, seed, forbidden):
        self.contexts = contexts
        self.random = random.Random(seed)
        self.forbidden = forbidden
        self.memory = deque()
        self.counts = Counter()

    def draw(self, weights):
        return self.random.choices(list(weights), weights=list(weights.values()))[0]

    def distribution(self, history, order):
        for size in (order, ORDER_SHORT, 1):
            options = self.contexts[size].get(tuple(history[-size:]))
            if options:
                return options
        return self.contexts[0][()]

    def glyph(self, history):
        order = ORDER_SHORT if self.random.random() < 0.60 else ORDER_LONG
        return self.draw(self.distribution(history, order))

    def remember(self, word):
        self.memory.append(word)
        self.counts[word] += 1
        if len(self.memory) > WORD_MEMORY:
            expired = self.memory.popleft()
            self.counts[expired] -= 1
            if not self.counts[expired]:
                del self.counts[expired]

    def whole_copy(self, history):
        candidates = {word: n for word, n in self.counts.items() if n >= 2}
        if not candidates:
            return ()
        options = self.distribution(history, ORDER_SHORT)
        preferred = {word: n for word, n in candidates.items() if word[0] in options}
        return self.draw(preferred or candidates)

    def line(self, opener):
        while True:
            previous = tuple(self.memory)
            history = list(start_for(opener))
            words = []
            current = []
            while len(history) < 504:
                if words and not current and not opener and self.random.random() < 0.25:
                    copied = self.whole_copy(history)
                    if copied:
                        current = list(copied)
                        history.extend(copied)
                        boundaries = {
                            key: weight for key, weight in self.distribution(history, ORDER_SHORT).items()
                            if key in (SPACE, END)
                        }
                        glyph = self.draw(boundaries or {SPACE: 1, END: 1})
                    else:
                        glyph = self.glyph(history)
                else:
                    glyph = self.glyph(history)
                if glyph in (SPACE, END):
                    if current:
                        words.append("".join(current))
                        self.remember(tuple(current))
                        current = []
                    elif glyph == SPACE:
                        continue
                    if glyph == END and words:
                        break
                    if not words:
                        continue
                else:
                    current.append(glyph)
                history.append(glyph)
            if current:
                words.append("".join(current))
                self.remember(tuple(current))
            if words and not any(tuple(words[i:i + 4]) in self.forbidden for i in range(len(words) - 3)):
                return words
            self.memory = deque(previous)
            self.counts = Counter(previous)

summarize_calibration.py.text:
"""Summarize the frozen section calibration and package a single step proposal."""

from collections import defaultdict
import json
import math
from pathlib import Path
from statistics import median


WORK = Path(__file__).resolve().parent
PLAN = json.loads((WORK / "plan.json").read_text())
ORDER_ID = {name: index for index, name in enumerate(PLAN["orders"])}
ROUTING_ID = {name: index for index, name in enumerate(PLAN["routing"])}
CONDITION_ID = {"base": 0, "plant": 1, "placebo": 2}


def interval(hits, total):
    z = 1.959964
    estimate = hits / total
    denominator = 1 + z**2 / total
    center = (estimate + z**2 / (2 * total)) / denominator
    half = z * math.sqrt(estimate * (1 - estimate) / total + z**2 / (4 * total**2)) / denominator
    return [round(max(0, center - half), 4), round(min(1, center + half), 4)]


def read_rows():
    rows = [
        row
        for filename in ("pilot.jsonl", "remaining.jsonl")
        for line in (WORK / filename).read_text().splitlines()
        for row in json.loads(line)
    ]
    expected = len(PLAN["background_seeds"]) * len(PLAN["sizes"]) * len(PLAN["orders"]) * len(PLAN["routing"])
    assert len(rows) == expected * (1 + 2 * len(PLAN["doses_percent"]))
    assert len({tuple(row[:6]) for row in rows}) == len(rows)
    return sorted(rows)


def summarize(rows):
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(row[1:6])].append(row[6:])
    counts = []
    for (size, order, routing, case, dose), group in sorted(groups.items()):
        assert len(group) == len(PLAN["background_seeds"])
        token_hits = sum(row[1] / 200 <= 0.05 for row in group)
        page_hits = sum(row[2] / 200 <= 0.05 for row in group)
        cyclic_hits = sum(row[3] / size <= 0.05 for row in group)
        rank = [row[3] for row in group]
        counts.append({
            "design": [size, order, routing, case, dose],
            "reject_at_0.05": [token_hits, page_hits, cyclic_hits],
            "wilson_95_intervals": [interval(hits, len(group)) for hits in (token_hits, page_hits, cyclic_hits)],
            "reject_at_0.01": [
                sum(row[1] / 200 <= 0.01 for row in group),
                sum(row[2] / 200 <= 0.01 for row in group),
                sum(row[3] / size <= 0.01 for row in group),
            ],
            "cyclic_rank_min_median_max": [min(rank), median(rank), max(rank)],
            "median_observed_bits": round(median(row[0] for row in group), 6),
        })
    return counts


def compact(row):
    seed, size, order, routing, case, dose, *measured = row
    return [seed, size, ORDER_ID[order], ROUTING_ID[routing], CONDITION_ID[case], dose, *measured]


def main():
    rows = read_rows()
    results = summarize(rows)
    (WORK / "summary.json").write_text(json.dumps(results, indent=2) + "\n")
    return rows, results


if __name__ == "__main__":
    main()

