"""Apply the published context scores to charter-document controls."""
from collections import Counter, defaultdict
from dataclasses import dataclass
import argparse
import hashlib
import importlib.util
from importlib.machinery import SourceFileLoader
import json
import math
from pathlib import Path
import random

from latin_corpus import iter_sentences


ROOT = Path(__file__).resolve().parent
PLAN_PATH = ROOT / "plan.json"
PLAN = json.loads(PLAN_PATH.read_text())
AMBIENT = ("all", "terminal", "terminal_same_stem_case", "internal",
           "internal_same_morph", "internal_new_lemma", "both_sides_matched")
TOL = 1e-12
prior_loader = SourceFileLoader("prior_position", str(ROOT / "prior-position_context.py"))
prior_spec = importlib.util.spec_from_loader(prior_loader.name, prior_loader)
prior = importlib.util.module_from_spec(prior_spec)
prior_loader.exec_module(prior)
METHODS = tuple(PLAN["methods"])
assert METHODS == prior.METHODS


@dataclass(frozen=True)
class Word:
    index: int
    surface_index: int
    form: str
    lemma: str
    upos: str
    case: str
    number: str
    gender: str


@dataclass(frozen=True)
class Site:
    word: Word
    onset: int
    before: str
    after: str


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_words(split):
    words = []
    chars = Counter()
    surface_no = 0
    path = ROOT / "corpus" / f"{split}.conllu"
    for sentence in iter_sentences(path, split=split):
        chars[sentence.doc_id] += 1
        for token in sentence.tokens:
            surface_no += 1
            morphology = token.morphology
            if morphology is None:
                lemma = upos = case = number = gender = ""
            else:
                lemma = morphology.lemma_ascii or ""
                if " " in lemma:
                    lemma = ""
                upos = morphology.upos or ""
                case = morphology.case or ""
                number = morphology.number or ""
                gender = morphology.gender or ""
            for part in token.ascii_parts:
                words.append(Word(len(words), surface_no, part, lemma, upos, case, number, gender))
    assert chars and words
    return words, {"sha256": sha(path), "documents": sorted(chars), "sentences": sum(chars.values()),
                   "normalized_words": len(words), "surface_tokens_with_punctuation": surface_no}


def all_sites(words, target, decoy):
    sites = []
    for word in words:
        for index in range(len(word.form) - 1):
            pair = word.form[index:index + 2]
            if pair in (target, decoy):
                previous = word.form[index - 1] if index else " "
                following = word.form[index + 2] if index + 2 < len(word.form) else " "
                sites.append((pair == decoy, Site(word, index, previous, following)))
    return sites


def stratum(site, decoy, mode, new_lemmas):
    initial = site.onset == 0
    final = site.after == " "
    basic = (initial, final, site.before)
    word = site.word
    if mode == "all":
        return basic
    if mode == "both_sides_matched":
        return (*basic, site.after)
    if mode == "terminal":
        return basic if final else None
    if mode == "terminal_same_stem_case":
        eligible = (
            final and word.lemma and word.upos in ("NOUN", "ADJ", "PROPN")
            and word.number == "Sing" and word.gender == "Masc"
            and word.case == ("Acc" if decoy else "Nom")
        )
        if eligible:
            return (*basic, word.lemma, word.upos, word.form[:-2])
        return None
    if final:
        return None
    if mode == "internal":
        return basic
    if mode == "internal_same_morph":
        return (*basic, word.upos, word.case, word.number) if word.upos else None
    if mode == "internal_new_lemma":
        return basic if word.lemma in new_lemmas else None
    raise ValueError(mode)


def make_pairs(sites, mode, seed, new_lemmas):
    groups = defaultdict(lambda: ([], []))
    for decoy, site in sites:
        key = stratum(site, decoy, mode, new_lemmas)
        if key is not None:
            groups[key][decoy].append(site)
    counts = [sum(len(pool[side]) for pool in groups.values()) for side in (0, 1)]
    unlimited = sum(min(len(left), len(right)) for left, right in groups.values())
    rng = random.Random(seed)
    matched = []
    used = set()
    group_keys = sorted(groups)
    rng.shuffle(group_keys)
    for key in group_keys:
        left, right = groups[key]
        rng.shuffle(left)
        rng.shuffle(right)
        cursor = 0
        for x in left:
            if x.word.surface_index in used:
                continue
            while cursor < len(right) and right[cursor].word.surface_index in used:
                cursor += 1
            if cursor == len(right):
                break
            choice = cursor
            while choice < len(right) and (
                right[choice].word.surface_index in used
                or right[choice].word.surface_index == x.word.surface_index
            ):
                choice += 1
            if choice == len(right):
                continue
            right[cursor], right[choice] = right[choice], right[cursor]
            z = right[cursor]
            cursor += 1
            used.update((x.word.surface_index, z.word.surface_index))
            matched.append((x, z))
    return matched, {"source_sites": counts, "stratum_unrestricted_upper_bound": unlimited,
                     "shared_nonempty_strata": sum(bool(left and right) for left, right in groups.values())}


def planted_context(words, pairs, target, decoy):
    edited = [word.form for word in words]
    for a, b in pairs:
        assert a.word.form[a.onset:a.onset + 2] == target
        assert b.word.form[b.onset:b.onset + 2] == decoy
        for marker, location in (("X", a), ("Z", b)):
            form = location.word.form
            start = location.onset
            edited[location.word.index] = form[:start] + marker + form[start + 2:]
    return prior.Context(" ".join(edited))


def assess(words, sites, target, decoy, group, seed, new_lemmas):
    pairs, support = make_pairs(sites, group, seed, new_lemmas)
    assert all(a.before == b.before and (a.after == " ") == (b.after == " ") for a, b in pairs)
    outer_match = sum(a.after == b.after for a, b in pairs)
    if group in ("terminal", "terminal_same_stem_case", "both_sides_matched"):
        assert outer_match == len(pairs)
    if len(pairs) < PLAN["candidate_minimum"]:
        values = {marker: dict.fromkeys(METHODS) for marker in ("X", "Z")}
    else:
        context = planted_context(words, pairs, target, decoy)
        assert context.all["X"]["n"] == context.all["Z"]["n"] == len(pairs)
        values = {marker: context.scores(marker, *target) for marker in ("X", "Z")}
        if outer_match == len(pairs):
            assert values["X"] == values["Z"]
    return {
        "target": target, "decoy": decoy, "mode": group, "seed": seed, "pairs": len(pairs),
        "same_right_context": outer_match, "support": support, "scores": values,
        "paired_unique_lemmas": [
            len({pair[side].word.lemma for pair in pairs if pair[side].word.lemma})
            for side in (0, 1)
        ],
        "position_counts": {
            "word_final": sum(a.after == " " for a, _ in pairs),
            "word_initial": sum(a.onset == 0 for a, _ in pairs),
        },
        "case_counts": [
            dict(Counter(pair[side].word.case or "_" for pair in pairs))
            for side in (0, 1)
        ],
    }


def run_rows(words, pairs, modes, new_lemmas):
    output = []
    for target, decoy in pairs:
        sites = all_sites(words, target, decoy)
        for mode in modes:
            for seed in PLAN["seeds"]:
                output.append(assess(words, sites, target, decoy, mode, seed, new_lemmas))
    return output


def common(row):
    return all(row["scores"][marker][method] is not None
               for marker in ("X", "Z") for method in METHODS)


def accepted(value, threshold):
    return value is not None and threshold is not None and value < threshold - TOL


def summarized(rows, thresholds):
    reports = {}
    groups = sorted({(row["target"], row["decoy"], row["mode"]) for row in rows})
    for target, decoy, mode in groups:
        selected = [r for r in rows if (r["target"], r["decoy"], r["mode"]) == (target, decoy, mode)]
        results = {}
        for method in METHODS:
            scores = [(r["scores"]["X"][method], r["scores"]["Z"][method]) for r in selected]
            paired = [(x, z) for x, z in scores if x is not None and z is not None]
            threshold = thresholds[method]
            results[method] = {
                "supported_seeds": len(paired),
                "genuine_wins": sum(x < z - TOL for x, z in paired),
                "decoy_wins": sum(z < x - TOL for x, z in paired),
                "ties": sum(abs(x - z) <= TOL for x, z in paired),
                "genuine_accepted": sum(accepted(x, threshold) for x, _ in paired),
                "decoy_accepted": sum(accepted(z, threshold) for _, z in paired),
            }
        reports["/".join((target, decoy, mode))] = {
            "support_range_by_seed": [min(r["pairs"] for r in selected), max(r["pairs"] for r in selected)],
            "common_supported_seeds": sum(common(r) for r in selected),
            "methods": results,
        }
    return reports


def negative_controls(words, thresholds):
    context = prior.Context(" ".join(w.form for w in words))
    rows = []
    for target in ("us", "in", "er"):
        for letter in "qtrn":
            if letter in target:
                continue
            values = context.scores(letter, *target)
            rows.append({
                "target": target, "standalone_letter": letter,
                "scores": values,
                "acceptances": {method: accepted(value, thresholds[method]) for method, value in values.items()},
            })
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=["calibrate", "evaluate"])
    args = parser.parse_args()
    split = "dev" if args.phase == "calibrate" else "test"
    words, info = read_words(split)
    base = {"plan_sha256": sha(PLAN_PATH), "runner_sha256": sha(Path(__file__)),
            "parser_sha256": sha(ROOT / "latin_corpus.py"),
            "prior_context_sha256": sha(ROOT / "prior-position_context.py"),
            "source": info}
    if args.phase == "calibrate":
        all_rows = run_rows(words, PLAN["calibration_pairs"], ("all",), set())
        valid = [r for r in all_rows if common(r)]
        thresholds = {}
        for method in METHODS:
            decoys = sorted(r["scores"]["Z"][method] for r in valid)
            thresholds[method] = decoys[math.floor(.05 * len(decoys))] if decoys else None
        base.update({"thresholds": thresholds, "calibration_common_rows": len(valid),
                     "summary": summarized(all_rows, thresholds), "rows": all_rows})
        result = ROOT / "calibration.json"
    else:
        frozen_path = ROOT / "calibration.json"
        frozen = json.loads(frozen_path.read_text())
        for key in ("plan_sha256", "runner_sha256", "parser_sha256", "prior_context_sha256"):
            assert base[key] == frozen[key]
        train, train_info = read_words("train")
        dev, dev_info = read_words("dev")
        doc_sets = [set(meta["documents"]) for meta in (train_info, dev_info, info)]
        assert not any(doc_sets[i] & doc_sets[j] for i, j in ((0, 1), (0, 2), (1, 2)))
        observed_lemmas = {x.lemma for x in train + dev if x.lemma}
        new_lemmas = {x.lemma for x in words if x.lemma} - observed_lemmas
        thresholds = frozen["thresholds"]
        normal = run_rows(words, PLAN["calibration_pairs"], ("all",), new_lemmas)
        focus = run_rows(words, [PLAN["focus_pair"]], AMBIENT, new_lemmas)
        base.update({"calibration_sha256": sha(frozen_path), "thresholds": thresholds,
                     "document_sets_disjoint": True, "train_source": train_info, "dev_source": dev_info,
                     "new_test_lemmas": len(new_lemmas), "summary": summarized(normal + focus, thresholds),
                     "rows": normal + focus, "negative_controls": negative_controls(words, thresholds)})
        result = ROOT / "evaluation.json"
    result.write_text(json.dumps(base, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"result": result.name, "thresholds": thresholds, "summary": base["summary"]}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.latin_corpus.py:
"""Surface-token and document input for the Latin LLCT context experiment.

The UD r2.18 LLCT split files identify each charter in the sentence's
``# reference = document_id='…'-span='…'`` comment. The complete quoted
identifier is interpreted consistently across split files, and the span is a separate
within-document locator. A ``# newdoc id`` can also identify documents in
other CoNLL-U sources. Sentence order and all source split labels stay intact.
"""

from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
import re
import unicodedata


_SPECIAL = {
    "ß": "ss", "æ": "ae", "œ": "oe", "þ": "th", "ð": "d",
    "ȝ": "y", "ſ": "s", "ø": "o", "ł": "l",
}
_NON_ASCII_LETTERS = re.compile(r"[^a-z]+")
_NEW_DOC = re.compile(r"^#\s*newdoc(?:\s+id\s*=\s*(\S.*))?\s*$")
_REFERENCE = re.compile(r"^#\s*reference\s*=")
_REFERENCE_DOC = re.compile(r"\bdocument_id\s*=\s*(['\"])(.*?)\1")
_REFERENCE_SPAN = re.compile(r"\bspan\s*=\s*(['\"])(.*?)\1")
_SENT_ID = re.compile(r"^#\s*sent_id\s*=\s*(\S+)\s*$")
_TEXT = re.compile(r"^#\s*text\s*=\s*(.*)$")
_WORD_ID = re.compile(r"[1-9][0-9]*\Z")
_RANGE_ID = re.compile(r"([1-9][0-9]*)-([1-9][0-9]*)\Z")
_EMPTY_ID = re.compile(r"[0-9]+\.[1-9][0-9]*\Z")


@dataclass(frozen=True, slots=True)
class Morphology:
    lemma: str | None
    lemma_ascii: str | None
    upos: str | None
    case: str | None
    number: str | None
    gender: str | None


@dataclass(frozen=True, slots=True)
class SyntacticWord:
    index: int
    form: str
    morphology: Morphology


@dataclass(frozen=True, slots=True)
class SurfaceToken:
    id: str
    form: str
    ascii_parts: tuple[str, ...]
    words: tuple[SyntacticWord, ...]
    space_after: bool

    @property
    def morphology(self) -> Morphology | None:
        """Single-word analysis only; a multiword token has several analyses."""
        if len(self.words) != 1 or len(self.ascii_parts) != 1:
            return None
        return self.words[0].morphology


@dataclass(frozen=True, slots=True)
class Sentence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    text: str | None
    tokens: tuple[SurfaceToken, ...]


@dataclass(frozen=True, slots=True)
class Occurrence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    token_id: str
    word: str
    part_index: int
    pair: str
    start: int
    left: str
    right: str
    role: str
    morphology: Morphology | None
    terminal_morphology: Morphology | None

    @property
    def word_initial(self) -> bool:
        return self.role in ("initial", "whole_word")

    @property
    def word_final(self) -> bool:
        return self.role in ("terminal", "whole_word")


def normalize_latin(text: str) -> str:
    """Use the pinned #623 Latin normalization, including j→i and v→u."""
    lowered = text.lower()
    for source, replacement in _SPECIAL.items():
        lowered = lowered.replace(source, replacement)
    unaccented = "".join(c for c in unicodedata.normalize("NFKD", lowered)
                         if not unicodedata.combining(c))
    return _NON_ASCII_LETTERS.sub(" ", unaccented).strip().replace("j", "i").replace("v", "u")


def _maybe(value: str) -> str | None:
    return None if value == "_" else value


def _field_pairs(features: str) -> dict[str, str]:
    if features == "_":
        return {}
    output = {}
    for entry in features.split("|"):
        key, sep, value = entry.partition("=")
        if not sep or not key or not value or key in output:
            raise ValueError(f"invalid or repeated CoNLL-U morphological feature: {entry!r}")
        output[key] = value
    return output


def _word(row: list[str]) -> SyntacticWord:
    lemma = _maybe(row[2])
    feat = _field_pairs(row[5])
    return SyntacticWord(int(row[0]), row[1], Morphology(
        lemma=lemma,
        lemma_ascii=(normalize_latin(lemma) or None) if lemma is not None else None,
        upos=_maybe(row[3]),
        case=feat.get("Case"),
        number=feat.get("Number"),
        gender=feat.get("Gender"),
    ))


def _sentence_blocks(path):
    with Path(path).open(encoding="utf-8-sig") as src:
        comments, rows = [], []
        for line in src:
            line = line.rstrip("\r\n")
            if not line:
                if rows:
                    yield comments, rows
                    comments, rows = [], []
                continue
            if line.startswith("#"):
                if rows:
                    raise ValueError(f"mid-sentence comment in {path}")
                comments.append(line)
            else:
                rows.append(line)
        if rows:
            yield comments, rows


def _identity(comments, active_doc, path):
    sent_id, text, ref_doc, span = None, None, None, None
    for line in comments:
        newdoc = _NEW_DOC.fullmatch(line)
        if newdoc:
            active_doc = newdoc[1].strip() if newdoc[1] is not None else None
        if match := _SENT_ID.fullmatch(line):
            if sent_id is not None:
                raise ValueError(f"repeated sent_id in {path}")
            sent_id = match[1]
        if match := _TEXT.fullmatch(line):
            text = match[1]
        if _REFERENCE.match(line):
            if match := _REFERENCE_DOC.search(line):
                if ref_doc is not None and ref_doc != match[2]:
                    raise ValueError(f"conflicting document_id values in {path}")
                ref_doc = match[2]
            if match := _REFERENCE_SPAN.search(line):
                span = match[2]
    if sent_id is None:
        raise ValueError(f"missing sent_id in {path}")
    if active_doc is not None and ref_doc is not None and active_doc != ref_doc:
        raise ValueError(f"newdoc and reference identify different documents in {path}, {sent_id}")
    return active_doc, ref_doc or active_doc, span, sent_id, text


def _surface_tokens(raw_rows, sent_id):
    word_rows = {}
    surface_rows = []
    covered = set()
    expected = 1
    for line in raw_rows:
        row = line.split("\t")
        if len(row) != 10:
            raise ValueError(f"expected 10 CoNLL-U fields in {sent_id}")
        locator = row[0]
        if _EMPTY_ID.fullmatch(locator):
            continue
        if match := _RANGE_ID.fullmatch(locator):
            start, end = map(int, match.groups())
            if start != expected or end <= start or start in covered:
                raise ValueError(f"misplaced or overlapping multiword token {locator} in {sent_id}")
            covered.update(range(start, end + 1))
            surface_rows.append((row, start, end))
        elif _WORD_ID.fullmatch(locator):
            index = int(locator)
            if index != expected:
                raise ValueError(f"nonconsecutive syntactic word ID {locator} in {sent_id}")
            expected += 1
            word_rows[index] = row
            if index not in covered:
                surface_rows.append((row, index, index))
        else:
            raise ValueError(f"unrecognized CoNLL-U ID {locator!r} in {sent_id}")
    if not covered <= word_rows.keys():
        raise ValueError(f"missing syntactic words for a multiword token in {sent_id}")
    return tuple(SurfaceToken(
        id=row[0], form=row[1], ascii_parts=tuple(normalize_latin(row[1]).split()),
        words=tuple(_word(word_rows[i]) for i in range(start, end + 1)),
        space_after="SpaceAfter=No" not in row[9].split("|"),
    ) for row, start, end in surface_rows)


def iter_sentences(path, *, split: str | None = None):
    """Read sentences and emit each orthographic surface token exactly once."""
    declared_split = Path(path).stem if split is None else split
    active_doc = None
    for comments, raw_rows in _sentence_blocks(path):
        active_doc, doc, span, sent_id, text = _identity(comments, active_doc, path)
        yield Sentence(declared_split, doc, span, sent_id, text, _surface_tokens(raw_rows, sent_id))


def document_membership(paths_by_split, *, require_ids=True):
    """Index raw document IDs by their named source splits, before scoring.

    IDs present in multiple partitions are visible as multiple memberships.
    Do not infer a new identity from the filename, sentence ID, or span.
    """
    membership = defaultdict(set)
    for split, path in paths_by_split.items():
        active_doc = None
        for comments, _ in _sentence_blocks(path):
            active_doc, doc, _, sent_id, _ = _identity(comments, active_doc, path)
            if doc is None:
                if require_ids:
                    raise ValueError(f"missing document identity in {path}, {sent_id}")
                continue
            membership[doc].add(split)
    return {doc: frozenset(splits) for doc, splits in sorted(membership.items())}


def iter_occurrences(sentences, pairs=("us", "um"), *, include_fragments=False):
    """Yield observable contexts without assuming that terminal letters are morphemes.

    Each context uses exactly one intra-word ASCII character per side and a
    virtual space at a word edge, as in #623. Default matching skips tokens
    whose normalization has introduced an internal word break. When enabled
    for a sensitivity, such fragments get character contexts only. A whole
    two-letter word has a role separate from terminal pairs with a stem.
    """
    pairs = frozenset(pairs)
    if any(not isinstance(pair, str) or not re.fullmatch(r"[a-z]{2}", pair) for pair in pairs):
        raise ValueError("pairs must be lowercase ASCII bigrams")
    for sentence in sentences:
        for token in sentence.tokens:
            if len(token.ascii_parts) > 1 and not include_fragments:
                continue
            morphology = token.morphology
            for part_index, word in enumerate(token.ascii_parts):
                for start in range(len(word) - 1):
                    end = start + 2
                    pair = word[start:end]
                    if pair not in pairs:
                        continue
                    if start == 0:
                        role = "whole_word" if end == len(word) else "initial"
                    else:
                        role = "terminal" if end == len(word) else "interior"
                    yield Occurrence(
                        sentence.split, sentence.doc_id, sentence.span, sentence.sent_id,
                        token.id, word, part_index, pair, start,
                        word[start-1] if start else " ", word[end] if end < len(word) else " ",
                        role, morphology, morphology if role == "terminal" else None,
                    )

scripts_as_text.prior-position_context.py:
"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts_as_text.verify_prior_experiment.py:
"""Check prior PR 623 replay against the published structured outputs."""
import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent / "prior-reproduction"
TOLERANCE = 1e-12


def load(path):
    return json.loads(path.read_bytes())


def compare(expected, actual):
    floating = []
    structural = []

    def walk(a, b, key):
        if isinstance(a, dict) and isinstance(b, dict) and a.keys() == b.keys():
            for field in a:
                walk(a[field], b[field], key + [field])
        elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
            for index, pair in enumerate(zip(a, b, strict=True)):
                walk(*pair, key + [str(index)])
        elif a != b:
            if isinstance(a, float) and isinstance(b, float):
                floating.append(abs(a - b))
            else:
                structural.append("/".join(key))

    walk(expected, actual, [])
    return {
        "floating_point_differences": len(floating),
        "maximum_absolute_floating_point_difference": max(floating, default=0.0),
        "other_differences": structural,
        "equal_within_existing_score_tolerance": not structural and max(floating, default=0.0) <= TOLERANCE,
    }


def summarize_negative(rows):
    results = []
    for row in rows:
        candidates = row["candidates"]
        common = [c for c in candidates if all(v is not None for v in c["scores"].values())]
        result = {k: v for k, v in row.items() if k != "candidates"}
        result.update({"candidate_count": len(candidates), "common_supported": len(common), "methods": {}})
        for method in ("unconditioned", "position_all", "position_info"):
            supported = [c["scores"][method] for c in candidates if c["scores"][method] is not None]
            result["methods"][method] = {
                "accepted_candidates": [c["candidate"] for c in candidates if c["accepted"][method]],
                "common_accepted_candidates": [c["candidate"] for c in common if c["accepted"][method]],
                "minimum_loss": min(supported) if supported else None,
                "supported": len(supported),
            }
        results.append(result)
    return results


def main():
    previous = load(ROOT / "previous-spec.json")
    frozen = load(ROOT / "public/calibration-freeze.json")
    public_plan = load(ROOT / "public/preregistered.json")
    assert previous["plan_sha256"] == public_plan["plan_sha256"] == frozen["plan_sha256"]
    assert public_plan["reproduction"]["plan_json_bytes"] == frozen["reproduction"]["plan_json_bytes"]
    preregistered_cutoffs = frozen["calibration_frozen_before_evaluation"]
    assert preregistered_cutoffs["thresholds"] == previous["results"]["calibration"]["thresholds"]
    assert preregistered_cutoffs["sha256"] == previous["output_digests"]["calibration.json"]
    cal = load(ROOT / "run/calibration.json")
    ev = load(ROOT / "run/evaluation.json")
    verification = load(ROOT / "run/verification.json")
    expected_eval = {k: v for k, v in previous["results"]["evaluation"].items() if k != "calibration_sha256"}
    eval_overlap = {k: ev[k] for k in expected_eval}
    archived = {}
    for filename in ("calibration.json", "evaluation.json", "verification.json"):
        recorded = previous["output_digests"][filename]
        found = hashlib.sha256((ROOT / "run" / filename).read_bytes()).hexdigest()
        archived[filename] = {"expected": recorded, "observed": found, "byte_exact": recorded == found}
    tests = {
        "calibration": compare(previous["results"]["calibration"], cal),
        "evaluation_shared_public_fields_excluding_calibration_digest": compare(expected_eval, eval_overlap),
        "independent_verification": compare(previous["results"]["independent_verification"], verification),
        "negative_control_published_summaries": compare(
            previous["results"]["negative_control_sample_results"], summarize_negative(ev["negative_controls"]),
        ),
    }
    assert tests["calibration"]["equal_within_existing_score_tolerance"]
    assert tests["evaluation_shared_public_fields_excluding_calibration_digest"]["equal_within_existing_score_tolerance"]
    assert tests["independent_verification"]["equal_within_existing_score_tolerance"]
    assert tests["negative_control_published_summaries"]["equal_within_existing_score_tolerance"]
    assert verification["all_support_and_acceptance_decisions_match"]
    result = {
        "pr": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/623",
        "runtime_base": previous["runtime_base"],
        "plan_commit": previous["preregistration_commit"],
        "calibration_freeze_commit": previous["calibration_freeze_commit"],
        "public_plan_sha_verified": previous["plan_sha256"],
        "public_freeze_contains_identical_plan": True,
        "formal_launcher_verification": "The bundled launcher verified the inputs and initial scripts and stopped at the calibration byte SHA mismatch. The original evaluation and verification scripts were then run without editing the published corpus, algorithms or thresholds.",
        "runtime_version": "Python 3.12.14 on Linux",
        "published_score_tolerance": TOLERANCE,
        "structured_comparisons": tests,
        "sha_checks": archived,
        "scope": "The archived evaluation contains additional negative-control details outside the compared summary. This distinguishes structured numerical reproduction and agreement of pairing, threshold and acceptance decisions from byte-for-byte identity.",
    }
    (ROOT / "reproduction-result.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.audit_morphology_support.py:
"""Count the charter, lexical and word-position support of frozen us/um matches.

Uses only the annotated test corpus and the frozen matching functions. Never
constructs a Context object, calculates a score, or changes a reported cutoff.
"""

from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path

from charter_context import Site, Word, make_pairs
from latin_corpus import iter_occurrences, iter_sentences


ROOT = Path(__file__).resolve().parent
FOCUS = ("us", "um")


def digest(path):
    return sha256(path.read_bytes()).hexdigest()


def _build_input(path):
    sentences = list(iter_sentences(path, split="test"))
    documents = {}
    words = {}
    ordinal = 0
    for sentence in sentences:
        for token in sentence.tokens:
            ordinal += 1
            morph = token.morphology
            lemma = morph.lemma_ascii or "" if morph is not None else ""
            fields = (
                morph.upos or "", morph.case or "", morph.number or "", morph.gender or ""
            ) if morph is not None else ("", "", "", "")
            for part, form in enumerate(token.ascii_parts):
                index = len(words)
                words[sentence.sent_id, token.id, part] = Word(
                    index, ordinal, form, lemma if " " not in lemma else "", *fields,
                )
                documents[index] = sentence.doc_id

    occurrences = list(iter_occurrences(sentences, FOCUS, include_fragments=True))
    sites = [
        (o.pair == FOCUS[1], Site(words[o.sent_id, o.token_id, o.part_index], o.start, o.left, o.right))
        for o in occurrences
    ]
    return occurrences, sites, documents


def _internal_support(occurrences):
    strata = defaultdict(Counter)
    for o in occurrences:
        if o.role in ("initial", "interior"):
            strata[o.role, o.left][o.pair] += 1
    by_role = {}
    for role in ("initial", "interior"):
        groups = {left: count for (kind, left), count in strata.items() if kind == role}
        raw = {pair: sum(count[pair] for count in groups.values()) for pair in FOCUS}
        by_role[role] = {
            "source_occurrences": raw,
            "upper_bound_matching_only_role": min(raw.values()),
            "upper_bound_matching_role_and_immediate_left": sum(min(c[p] for p in FOCUS) for c in groups.values()),
            "nonempty_exact_left_strata": sum(all(c[p] for p in FOCUS) for c in groups.values()),
            "left_strata_with_both": [
                {"left": left, "source_occurrences": {p: count[p] for p in FOCUS},
                 "pair_upper_bound": min(count[p] for p in FOCUS)}
                for left, count in sorted(groups.items()) if all(count[p] for p in FOCUS)
            ],
        }
    return {
        "source_occurrences": {pair: sum(row["source_occurrences"][pair] for row in by_role.values()) for pair in FOCUS},
        "upper_bound_matching_role_and_immediate_left": sum(row["upper_bound_matching_role_and_immediate_left"] for row in by_role.values()),
        "by_role": by_role,
    }


def _terminal_summary(pairs, documents):
    groups = Counter()
    docs_by_group = defaultdict(set)
    sides = [Counter(), Counter()]
    for a, b in pairs:
        key = (a.word.lemma, a.word.form[:-2], a.word.upos)
        assert key == (b.word.lemma, b.word.form[:-2], b.word.upos)
        groups[key] += 1
        for i, site in enumerate((a, b)):
            doc = documents[site.word.index]
            assert doc is not None
            sides[i][doc] += 1
            docs_by_group[key].add(doc)
    docs = sides[0] + sides[1]
    rows = [{"lemma": lemma, "stem": stem, "upos": upos, "matched_pairs": n,
             "share_of_pairs": n / len(pairs), "contributing_charters": len(docs_by_group[lemma, stem, upos])}
            for (lemma, stem, upos), n in sorted(groups.items(), key=lambda row: (-row[1], row[0]))]
    return {
        "matched_pairs": len(pairs), "matched_occurrence_slots": 2 * len(pairs),
        "charters_either_side": len(docs),
        "charters_us_side": len(sides[0]), "charters_um_side": len(sides[1]),
        "charters_both_sides": len(sides[0].keys() & sides[1].keys()),
        "same_charter_matched_pairs": sum(documents[a.word.index] == documents[b.word.index] for a, b in pairs),
        "lemma_stem_upos_groups": len(groups), "groups": rows,
        "largest_charter_matched_slots": max(docs.values()),
        "largest_charters": [doc for doc in sorted(docs) if docs[doc] == max(docs.values())],
    }


def main():
    corpus = ROOT / "corpus" / "test.conllu"
    frozen = ROOT / "evaluation.json"
    evaluation = json.loads(frozen.read_text(encoding="utf-8"))
    assert evaluation["source"]["sha256"] == digest(corpus)
    assert evaluation["parser_sha256"] == digest(ROOT / "latin_corpus.py")
    assert evaluation["runner_sha256"] == digest(ROOT / "charter_context.py")
    occurrences, sites, documents = _build_input(corpus)
    by_mode = {mode: {r["seed"]: r for r in evaluation["rows"] if (r["target"], r["decoy"]) == FOCUS and r["mode"] == mode}
               for mode in ("internal", "terminal_same_stem_case")}
    internal = _internal_support(occurrences)
    terminal = []
    union_slots = set()
    union_docs = set()
    for seed, row in sorted(by_mode["terminal_same_stem_case"].items()):
        pairs, support = make_pairs(sites, "terminal_same_stem_case", seed, frozenset())
        assert len(pairs) == row["pairs"] and support == row["support"]
        terminal.append({"seed": seed, **_terminal_summary(pairs, documents)})
        union_slots.update((site.word.index, site.onset) for pair in pairs for site in pair)
        union_docs.update(documents[site.word.index] for pair in pairs for site in pair)
    for row in by_mode["internal"].values():
        assert row["support"]["source_sites"] == [internal["source_occurrences"][p] for p in FOCUS]
        assert row["support"]["stratum_unrestricted_upper_bound"] == internal["upper_bound_matching_role_and_immediate_left"]
        assert row["position_counts"]["word_initial"] == internal["by_role"]["initial"]["upper_bound_matching_role_and_immediate_left"]
    report = {
        "scope": "UD Latin LLCT test charters only. Support and concentration from the same frozen match, with no new scores. Counts per matched seed reuse source charters and are not independent observations.",
        "evaluation_sha256": digest(frozen), "test_sha256": digest(corpus),
        "internal_us_um": internal,
        "terminal_same_stem_case": {
            "unique_occurrence_slots_across_seeds": len(union_slots),
            "unique_charters_across_seeds": len(union_docs),
            "seeds": terminal,
        },
    }
    (ROOT / "morphology_support.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(internal)
    for row in terminal:
        print(row["seed"], row["charters_either_side"], row["charters_us_side"], row["charters_um_side"],
              row["lemma_stem_upos_groups"], row["groups"][0])
    print("unique across seeds", len(union_slots), "slots and", len(union_docs), "charters")


if __name__ == "__main__":
    main()

scripts_as_text.charter_context.py:
"""Apply the published context scores to charter-document controls."""
from collections import Counter, defaultdict
from dataclasses import dataclass
import argparse
import hashlib
import importlib.util
from importlib.machinery import SourceFileLoader
import json
import math
from pathlib import Path
import random

from latin_corpus import iter_sentences


ROOT = Path(__file__).resolve().parent
PLAN_PATH = ROOT / "plan.json"
PLAN = json.loads(PLAN_PATH.read_text())
AMBIENT = ("all", "terminal", "terminal_same_stem_case", "internal",
           "internal_same_morph", "internal_new_lemma", "both_sides_matched")
TOL = 1e-12
prior_loader = SourceFileLoader("prior_position", str(ROOT / "prior-position_context.py"))
prior_spec = importlib.util.spec_from_loader(prior_loader.name, prior_loader)
prior = importlib.util.module_from_spec(prior_spec)
prior_loader.exec_module(prior)
METHODS = tuple(PLAN["methods"])
assert METHODS == prior.METHODS


@dataclass(frozen=True)
class Word:
    index: int
    surface_index: int
    form: str
    lemma: str
    upos: str
    case: str
    number: str
    gender: str


@dataclass(frozen=True)
class Site:
    word: Word
    onset: int
    before: str
    after: str


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_words(split):
    words = []
    chars = Counter()
    surface_no = 0
    path = ROOT / "corpus" / f"{split}.conllu"
    for sentence in iter_sentences(path, split=split):
        chars[sentence.doc_id] += 1
        for token in sentence.tokens:
            surface_no += 1
            morphology = token.morphology
            if morphology is None:
                lemma = upos = case = number = gender = ""
            else:
                lemma = morphology.lemma_ascii or ""
                if " " in lemma:
                    lemma = ""
                upos = morphology.upos or ""
                case = morphology.case or ""
                number = morphology.number or ""
                gender = morphology.gender or ""
            for part in token.ascii_parts:
                words.append(Word(len(words), surface_no, part, lemma, upos, case, number, gender))
    assert chars and words
    return words, {"sha256": sha(path), "documents": sorted(chars), "sentences": sum(chars.values()),
                   "normalized_words": len(words), "surface_tokens_with_punctuation": surface_no}


def all_sites(words, target, decoy):
    sites = []
    for word in words:
        for index in range(len(word.form) - 1):
            pair = word.form[index:index + 2]
            if pair in (target, decoy):
                previous = word.form[index - 1] if index else " "
                following = word.form[index + 2] if index + 2 < len(word.form) else " "
                sites.append((pair == decoy, Site(word, index, previous, following)))
    return sites


def stratum(site, decoy, mode, new_lemmas):
    initial = site.onset == 0
    final = site.after == " "
    basic = (initial, final, site.before)
    word = site.word
    if mode == "all":
        return basic
    if mode == "both_sides_matched":
        return (*basic, site.after)
    if mode == "terminal":
        return basic if final else None
    if mode == "terminal_same_stem_case":
        eligible = (
            final and word.lemma and word.upos in ("NOUN", "ADJ", "PROPN")
            and word.number == "Sing" and word.gender == "Masc"
            and word.case == ("Acc" if decoy else "Nom")
        )
        if eligible:
            return (*basic, word.lemma, word.upos, word.form[:-2])
        return None
    if final:
        return None
    if mode == "internal":
        return basic
    if mode == "internal_same_morph":
        return (*basic, word.upos, word.case, word.number) if word.upos else None
    if mode == "internal_new_lemma":
        return basic if word.lemma in new_lemmas else None
    raise ValueError(mode)


def make_pairs(sites, mode, seed, new_lemmas):
    groups = defaultdict(lambda: ([], []))
    for decoy, site in sites:
        key = stratum(site, decoy, mode, new_lemmas)
        if key is not None:
            groups[key][decoy].append(site)
    counts = [sum(len(pool[side]) for pool in groups.values()) for side in (0, 1)]
    unlimited = sum(min(len(left), len(right)) for left, right in groups.values())
    rng = random.Random(seed)
    matched = []
    used = set()
    group_keys = sorted(groups)
    rng.shuffle(group_keys)
    for key in group_keys:
        left, right = groups[key]
        rng.shuffle(left)
        rng.shuffle(right)
        cursor = 0
        for x in left:
            if x.word.surface_index in used:
                continue
            while cursor < len(right) and right[cursor].word.surface_index in used:
                cursor += 1
            if cursor == len(right):
                break
            choice = cursor
            while choice < len(right) and (
                right[choice].word.surface_index in used
                or right[choice].word.surface_index == x.word.surface_index
            ):
                choice += 1
            if choice == len(right):
                continue
            right[cursor], right[choice] = right[choice], right[cursor]
            z = right[cursor]
            cursor += 1
            used.update((x.word.surface_index, z.word.surface_index))
            matched.append((x, z))
    return matched, {"source_sites": counts, "stratum_unrestricted_upper_bound": unlimited,
                     "shared_nonempty_strata": sum(bool(left and right) for left, right in groups.values())}


def planted_context(words, pairs, target, decoy):
    edited = [word.form for word in words]
    for a, b in pairs:
        assert a.word.form[a.onset:a.onset + 2] == target
        assert b.word.form[b.onset:b.onset + 2] == decoy
        for marker, location in (("X", a), ("Z", b)):
            form = location.word.form
            start = location.onset
            edited[location.word.index] = form[:start] + marker + form[start + 2:]
    return prior.Context(" ".join(edited))


def assess(words, sites, target, decoy, group, seed, new_lemmas):
    pairs, support = make_pairs(sites, group, seed, new_lemmas)
    assert all(a.before == b.before and (a.after == " ") == (b.after == " ") for a, b in pairs)
    outer_match = sum(a.after == b.after for a, b in pairs)
    if group in ("terminal", "terminal_same_stem_case", "both_sides_matched"):
        assert outer_match == len(pairs)
    if len(pairs) < PLAN["candidate_minimum"]:
        values = {marker: dict.fromkeys(METHODS) for marker in ("X", "Z")}
    else:
        context = planted_context(words, pairs, target, decoy)
        assert context.all["X"]["n"] == context.all["Z"]["n"] == len(pairs)
        values = {marker: context.scores(marker, *target) for marker in ("X", "Z")}
        if outer_match == len(pairs):
            assert values["X"] == values["Z"]
    return {
        "target": target, "decoy": decoy, "mode": group, "seed": seed, "pairs": len(pairs),
        "same_right_context": outer_match, "support": support, "scores": values,
        "paired_unique_lemmas": [
            len({pair[side].word.lemma for pair in pairs if pair[side].word.lemma})
            for side in (0, 1)
        ],
        "position_counts": {
            "word_final": sum(a.after == " " for a, _ in pairs),
            "word_initial": sum(a.onset == 0 for a, _ in pairs),
        },
        "case_counts": [
            dict(Counter(pair[side].word.case or "_" for pair in pairs))
            for side in (0, 1)
        ],
    }


def run_rows(words, pairs, modes, new_lemmas):
    output = []
    for target, decoy in pairs:
        sites = all_sites(words, target, decoy)
        for mode in modes:
            for seed in PLAN["seeds"]:
                output.append(assess(words, sites, target, decoy, mode, seed, new_lemmas))
    return output


def common(row):
    return all(row["scores"][marker][method] is not None
               for marker in ("X", "Z") for method in METHODS)


def accepted(value, threshold):
    return value is not None and threshold is not None and value < threshold - TOL


def summarized(rows, thresholds):
    reports = {}
    groups = sorted({(row["target"], row["decoy"], row["mode"]) for row in rows})
    for target, decoy, mode in groups:
        selected = [r for r in rows if (r["target"], r["decoy"], r["mode"]) == (target, decoy, mode)]
        results = {}
        for method in METHODS:
            scores = [(r["scores"]["X"][method], r["scores"]["Z"][method]) for r in selected]
            paired = [(x, z) for x, z in scores if x is not None and z is not None]
            threshold = thresholds[method]
            results[method] = {
                "supported_seeds": len(paired),
                "genuine_wins": sum(x < z - TOL for x, z in paired),
                "decoy_wins": sum(z < x - TOL for x, z in paired),
                "ties": sum(abs(x - z) <= TOL for x, z in paired),
                "genuine_accepted": sum(accepted(x, threshold) for x, _ in paired),
                "decoy_accepted": sum(accepted(z, threshold) for _, z in paired),
            }
        reports["/".join((target, decoy, mode))] = {
            "support_range_by_seed": [min(r["pairs"] for r in selected), max(r["pairs"] for r in selected)],
            "common_supported_seeds": sum(common(r) for r in selected),
            "methods": results,
        }
    return reports


def negative_controls(words, thresholds):
    context = prior.Context(" ".join(w.form for w in words))
    rows = []
    for target in ("us", "in", "er"):
        for letter in "qtrn":
            if letter in target:
                continue
            values = context.scores(letter, *target)
            rows.append({
                "target": target, "standalone_letter": letter,
                "scores": values,
                "acceptances": {method: accepted(value, thresholds[method]) for method, value in values.items()},
            })
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=["calibrate", "evaluate"])
    args = parser.parse_args()
    split = "dev" if args.phase == "calibrate" else "test"
    words, info = read_words(split)
    base = {"plan_sha256": sha(PLAN_PATH), "runner_sha256": sha(Path(__file__)),
            "parser_sha256": sha(ROOT / "latin_corpus.py"),
            "prior_context_sha256": sha(ROOT / "prior-position_context.py"),
            "source": info}
    if args.phase == "calibrate":
        all_rows = run_rows(words, PLAN["calibration_pairs"], ("all",), set())
        valid = [r for r in all_rows if common(r)]
        thresholds = {}
        for method in METHODS:
            decoys = sorted(r["scores"]["Z"][method] for r in valid)
            thresholds[method] = decoys[math.floor(.05 * len(decoys))] if decoys else None
        base.update({"thresholds": thresholds, "calibration_common_rows": len(valid),
                     "summary": summarized(all_rows, thresholds), "rows": all_rows})
        result = ROOT / "calibration.json"
    else:
        frozen_path = ROOT / "calibration.json"
        frozen = json.loads(frozen_path.read_text())
        for key in ("plan_sha256", "runner_sha256", "parser_sha256", "prior_context_sha256"):
            assert base[key] == frozen[key]
        train, train_info = read_words("train")
        dev, dev_info = read_words("dev")
        doc_sets = [set(meta["documents"]) for meta in (train_info, dev_info, info)]
        assert not any(doc_sets[i] & doc_sets[j] for i, j in ((0, 1), (0, 2), (1, 2)))
        observed_lemmas = {x.lemma for x in train + dev if x.lemma}
        new_lemmas = {x.lemma for x in words if x.lemma} - observed_lemmas
        thresholds = frozen["thresholds"]
        normal = run_rows(words, PLAN["calibration_pairs"], ("all",), new_lemmas)
        focus = run_rows(words, [PLAN["focus_pair"]], AMBIENT, new_lemmas)
        base.update({"calibration_sha256": sha(frozen_path), "thresholds": thresholds,
                     "document_sets_disjoint": True, "train_source": train_info, "dev_source": dev_info,
                     "new_test_lemmas": len(new_lemmas), "summary": summarized(normal + focus, thresholds),
                     "rows": normal + focus, "negative_controls": negative_controls(words, thresholds)})
        result = ROOT / "evaluation.json"
    result.write_text(json.dumps(base, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"result": result.name, "thresholds": thresholds, "summary": base["summary"]}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.latin_corpus.py:
"""Surface-token and document input for the Latin LLCT context experiment.

The UD r2.18 LLCT split files identify each charter in the sentence's
``# reference = document_id='…'-span='…'`` comment. The complete quoted
identifier is interpreted consistently across split files, and the span is a separate
within-document locator. A ``# newdoc id`` can also identify documents in
other CoNLL-U sources. Sentence order and all source split labels stay intact.
"""

from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
import re
import unicodedata


_SPECIAL = {
    "ß": "ss", "æ": "ae", "œ": "oe", "þ": "th", "ð": "d",
    "ȝ": "y", "ſ": "s", "ø": "o", "ł": "l",
}
_NON_ASCII_LETTERS = re.compile(r"[^a-z]+")
_NEW_DOC = re.compile(r"^#\s*newdoc(?:\s+id\s*=\s*(\S.*))?\s*$")
_REFERENCE = re.compile(r"^#\s*reference\s*=")
_REFERENCE_DOC = re.compile(r"\bdocument_id\s*=\s*(['\"])(.*?)\1")
_REFERENCE_SPAN = re.compile(r"\bspan\s*=\s*(['\"])(.*?)\1")
_SENT_ID = re.compile(r"^#\s*sent_id\s*=\s*(\S+)\s*$")
_TEXT = re.compile(r"^#\s*text\s*=\s*(.*)$")
_WORD_ID = re.compile(r"[1-9][0-9]*\Z")
_RANGE_ID = re.compile(r"([1-9][0-9]*)-([1-9][0-9]*)\Z")
_EMPTY_ID = re.compile(r"[0-9]+\.[1-9][0-9]*\Z")


@dataclass(frozen=True, slots=True)
class Morphology:
    lemma: str | None
    lemma_ascii: str | None
    upos: str | None
    case: str | None
    number: str | None
    gender: str | None


@dataclass(frozen=True, slots=True)
class SyntacticWord:
    index: int
    form: str
    morphology: Morphology


@dataclass(frozen=True, slots=True)
class SurfaceToken:
    id: str
    form: str
    ascii_parts: tuple[str, ...]
    words: tuple[SyntacticWord, ...]
    space_after: bool

    @property
    def morphology(self) -> Morphology | None:
        """Single-word analysis only; a multiword token has several analyses."""
        if len(self.words) != 1 or len(self.ascii_parts) != 1:
            return None
        return self.words[0].morphology


@dataclass(frozen=True, slots=True)
class Sentence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    text: str | None
    tokens: tuple[SurfaceToken, ...]


@dataclass(frozen=True, slots=True)
class Occurrence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    token_id: str
    word: str
    part_index: int
    pair: str
    start: int
    left: str
    right: str
    role: str
    morphology: Morphology | None
    terminal_morphology: Morphology | None

    @property
    def word_initial(self) -> bool:
        return self.role in ("initial", "whole_word")

    @property
    def word_final(self) -> bool:
        return self.role in ("terminal", "whole_word")


def normalize_latin(text: str) -> str:
    """Use the pinned #623 Latin normalization, including j→i and v→u."""
    lowered = text.lower()
    for source, replacement in _SPECIAL.items():
        lowered = lowered.replace(source, replacement)
    unaccented = "".join(c for c in unicodedata.normalize("NFKD", lowered)
                         if not unicodedata.combining(c))
    return _NON_ASCII_LETTERS.sub(" ", unaccented).strip().replace("j", "i").replace("v", "u")


def _maybe(value: str) -> str | None:
    return None if value == "_" else value


def _field_pairs(features: str) -> dict[str, str]:
    if features == "_":
        return {}
    output = {}
    for entry in features.split("|"):
        key, sep, value = entry.partition("=")
        if not sep or not key or not value or key in output:
            raise ValueError(f"invalid or repeated CoNLL-U morphological feature: {entry!r}")
        output[key] = value
    return output


def _word(row: list[str]) -> SyntacticWord:
    lemma = _maybe(row[2])
    feat = _field_pairs(row[5])
    return SyntacticWord(int(row[0]), row[1], Morphology(
        lemma=lemma,
        lemma_ascii=(normalize_latin(lemma) or None) if lemma is not None else None,
        upos=_maybe(row[3]),
        case=feat.get("Case"),
        number=feat.get("Number"),
        gender=feat.get("Gender"),
    ))


def _sentence_blocks(path):
    with Path(path).open(encoding="utf-8-sig") as src:
        comments, rows = [], []
        for line in src:
            line = line.rstrip("\r\n")
            if not line:
                if rows:
                    yield comments, rows
                    comments, rows = [], []
                continue
            if line.startswith("#"):
                if rows:
                    raise ValueError(f"mid-sentence comment in {path}")
                comments.append(line)
            else:
                rows.append(line)
        if rows:
            yield comments, rows


def _identity(comments, active_doc, path):
    sent_id, text, ref_doc, span = None, None, None, None
    for line in comments:
        newdoc = _NEW_DOC.fullmatch(line)
        if newdoc:
            active_doc = newdoc[1].strip() if newdoc[1] is not None else None
        if match := _SENT_ID.fullmatch(line):
            if sent_id is not None:
                raise ValueError(f"repeated sent_id in {path}")
            sent_id = match[1]
        if match := _TEXT.fullmatch(line):
            text = match[1]
        if _REFERENCE.match(line):
            if match := _REFERENCE_DOC.search(line):
                if ref_doc is not None and ref_doc != match[2]:
                    raise ValueError(f"conflicting document_id values in {path}")
                ref_doc = match[2]
            if match := _REFERENCE_SPAN.search(line):
                span = match[2]
    if sent_id is None:
        raise ValueError(f"missing sent_id in {path}")
    if active_doc is not None and ref_doc is not None and active_doc != ref_doc:
        raise ValueError(f"newdoc and reference identify different documents in {path}, {sent_id}")
    return active_doc, ref_doc or active_doc, span, sent_id, text


def _surface_tokens(raw_rows, sent_id):
    word_rows = {}
    surface_rows = []
    covered = set()
    expected = 1
    for line in raw_rows:
        row = line.split("\t")
        if len(row) != 10:
            raise ValueError(f"expected 10 CoNLL-U fields in {sent_id}")
        locator = row[0]
        if _EMPTY_ID.fullmatch(locator):
            continue
        if match := _RANGE_ID.fullmatch(locator):
            start, end = map(int, match.groups())
            if start != expected or end <= start or start in covered:
                raise ValueError(f"misplaced or overlapping multiword token {locator} in {sent_id}")
            covered.update(range(start, end + 1))
            surface_rows.append((row, start, end))
        elif _WORD_ID.fullmatch(locator):
            index = int(locator)
            if index != expected:
                raise ValueError(f"nonconsecutive syntactic word ID {locator} in {sent_id}")
            expected += 1
            word_rows[index] = row
            if index not in covered:
                surface_rows.append((row, index, index))
        else:
            raise ValueError(f"unrecognized CoNLL-U ID {locator!r} in {sent_id}")
    if not covered <= word_rows.keys():
        raise ValueError(f"missing syntactic words for a multiword token in {sent_id}")
    return tuple(SurfaceToken(
        id=row[0], form=row[1], ascii_parts=tuple(normalize_latin(row[1]).split()),
        words=tuple(_word(word_rows[i]) for i in range(start, end + 1)),
        space_after="SpaceAfter=No" not in row[9].split("|"),
    ) for row, start, end in surface_rows)


def iter_sentences(path, *, split: str | None = None):
    """Read sentences and emit each orthographic surface token exactly once."""
    declared_split = Path(path).stem if split is None else split
    active_doc = None
    for comments, raw_rows in _sentence_blocks(path):
        active_doc, doc, span, sent_id, text = _identity(comments, active_doc, path)
        yield Sentence(declared_split, doc, span, sent_id, text, _surface_tokens(raw_rows, sent_id))


def document_membership(paths_by_split, *, require_ids=True):
    """Index raw document IDs by their named source splits, before scoring.

    IDs present in multiple partitions are visible as multiple memberships.
    Do not infer a new identity from the filename, sentence ID, or span.
    """
    membership = defaultdict(set)
    for split, path in paths_by_split.items():
        active_doc = None
        for comments, _ in _sentence_blocks(path):
            active_doc, doc, _, sent_id, _ = _identity(comments, active_doc, path)
            if doc is None:
                if require_ids:
                    raise ValueError(f"missing document identity in {path}, {sent_id}")
                continue
            membership[doc].add(split)
    return {doc: frozenset(splits) for doc, splits in sorted(membership.items())}


def iter_occurrences(sentences, pairs=("us", "um"), *, include_fragments=False):
    """Yield observable contexts without assuming that terminal letters are morphemes.

    Each context uses exactly one intra-word ASCII character per side and a
    virtual space at a word edge, as in #623. Default matching skips tokens
    whose normalization has introduced an internal word break. When enabled
    for a sensitivity, such fragments get character contexts only. A whole
    two-letter word has a role separate from terminal pairs with a stem.
    """
    pairs = frozenset(pairs)
    if any(not isinstance(pair, str) or not re.fullmatch(r"[a-z]{2}", pair) for pair in pairs):
        raise ValueError("pairs must be lowercase ASCII bigrams")
    for sentence in sentences:
        for token in sentence.tokens:
            if len(token.ascii_parts) > 1 and not include_fragments:
                continue
            morphology = token.morphology
            for part_index, word in enumerate(token.ascii_parts):
                for start in range(len(word) - 1):
                    end = start + 2
                    pair = word[start:end]
                    if pair not in pairs:
                        continue
                    if start == 0:
                        role = "whole_word" if end == len(word) else "initial"
                    else:
                        role = "terminal" if end == len(word) else "interior"
                    yield Occurrence(
                        sentence.split, sentence.doc_id, sentence.span, sentence.sent_id,
                        token.id, word, part_index, pair, start,
                        word[start-1] if start else " ", word[end] if end < len(word) else " ",
                        role, morphology, morphology if role == "terminal" else None,
                    )

scripts_as_text.prior-position_context.py:
"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts_as_text.verify_prior_experiment.py:
"""Check prior PR 623 replay against the published structured outputs."""
import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent / "prior-reproduction"
TOLERANCE = 1e-12


def load(path):
    return json.loads(path.read_bytes())


def compare(expected, actual):
    floating = []
    structural = []

    def walk(a, b, key):
        if isinstance(a, dict) and isinstance(b, dict) and a.keys() == b.keys():
            for field in a:
                walk(a[field], b[field], key + [field])
        elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
            for index, pair in enumerate(zip(a, b, strict=True)):
                walk(*pair, key + [str(index)])
        elif a != b:
            if isinstance(a, float) and isinstance(b, float):
                floating.append(abs(a - b))
            else:
                structural.append("/".join(key))

    walk(expected, actual, [])
    return {
        "floating_point_differences": len(floating),
        "maximum_absolute_floating_point_difference": max(floating, default=0.0),
        "other_differences": structural,
        "equal_within_existing_score_tolerance": not structural and max(floating, default=0.0) <= TOLERANCE,
    }


def summarize_negative(rows):
    results = []
    for row in rows:
        candidates = row["candidates"]
        common = [c for c in candidates if all(v is not None for v in c["scores"].values())]
        result = {k: v for k, v in row.items() if k != "candidates"}
        result.update({"candidate_count": len(candidates), "common_supported": len(common), "methods": {}})
        for method in ("unconditioned", "position_all", "position_info"):
            supported = [c["scores"][method] for c in candidates if c["scores"][method] is not None]
            result["methods"][method] = {
                "accepted_candidates": [c["candidate"] for c in candidates if c["accepted"][method]],
                "common_accepted_candidates": [c["candidate"] for c in common if c["accepted"][method]],
                "minimum_loss": min(supported) if supported else None,
                "supported": len(supported),
            }
        results.append(result)
    return results


def main():
    previous = load(ROOT / "previous-spec.json")
    frozen = load(ROOT / "public/calibration-freeze.json")
    public_plan = load(ROOT / "public/preregistered.json")
    assert previous["plan_sha256"] == public_plan["plan_sha256"] == frozen["plan_sha256"]
    assert public_plan["reproduction"]["plan_json_bytes"] == frozen["reproduction"]["plan_json_bytes"]
    preregistered_cutoffs = frozen["calibration_frozen_before_evaluation"]
    assert preregistered_cutoffs["thresholds"] == previous["results"]["calibration"]["thresholds"]
    assert preregistered_cutoffs["sha256"] == previous["output_digests"]["calibration.json"]
    cal = load(ROOT / "run/calibration.json")
    ev = load(ROOT / "run/evaluation.json")
    verification = load(ROOT / "run/verification.json")
    expected_eval = {k: v for k, v in previous["results"]["evaluation"].items() if k != "calibration_sha256"}
    eval_overlap = {k: ev[k] for k in expected_eval}
    archived = {}
    for filename in ("calibration.json", "evaluation.json", "verification.json"):
        recorded = previous["output_digests"][filename]
        found = hashlib.sha256((ROOT / "run" / filename).read_bytes()).hexdigest()
        archived[filename] = {"expected": recorded, "observed": found, "byte_exact": recorded == found}
    tests = {
        "calibration": compare(previous["results"]["calibration"], cal),
        "evaluation_shared_public_fields_excluding_calibration_digest": compare(expected_eval, eval_overlap),
        "independent_verification": compare(previous["results"]["independent_verification"], verification),
        "negative_control_published_summaries": compare(
            previous["results"]["negative_control_sample_results"], summarize_negative(ev["negative_controls"]),
        ),
    }
    assert tests["calibration"]["equal_within_existing_score_tolerance"]
    assert tests["evaluation_shared_public_fields_excluding_calibration_digest"]["equal_within_existing_score_tolerance"]
    assert tests["independent_verification"]["equal_within_existing_score_tolerance"]
    assert tests["negative_control_published_summaries"]["equal_within_existing_score_tolerance"]
    assert verification["all_support_and_acceptance_decisions_match"]
    result = {
        "pr": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/623",
        "runtime_base": previous["runtime_base"],
        "plan_commit": previous["preregistration_commit"],
        "calibration_freeze_commit": previous["calibration_freeze_commit"],
        "public_plan_sha_verified": previous["plan_sha256"],
        "public_freeze_contains_identical_plan": True,
        "formal_launcher_verification": "The bundled launcher verified the inputs and initial scripts and stopped at the calibration byte SHA mismatch. The original evaluation and verification scripts were then run without editing the published corpus, algorithms or thresholds.",
        "runtime_version": "Python 3.12.14 on Linux",
        "published_score_tolerance": TOLERANCE,
        "structured_comparisons": tests,
        "sha_checks": archived,
        "scope": "The archived evaluation contains additional negative-control details outside the compared summary. This distinguishes structured numerical reproduction and agreement of pairing, threshold and acceptance decisions from byte-for-byte identity.",
    }
    (ROOT / "reproduction-result.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.audit_archive_alignment.py:
"""Reconstruct the previous exact-pair S47 audit and its one-row sensitivity."""
from collections import Counter, defaultdict
import csv
import itertools
import json
import math
from pathlib import Path
import random
import re
import statistics


ROOT = Path(__file__).resolve().parent
LINE_RE = re.compile(r"^<(f\d+[rv]\d*)\.(\d+),[^>]*P\d*>\s*(\S+)")
PAGE_RE = re.compile(r"^<(f\d+[rv]\d*)>\s*<!.*?\$Q=([A-Z])")
CLEAN = re.compile(r"[a-z]+(?:[.,][a-z]+)*$")
SEGMENT = re.compile(r"cth|ckh|cph|cfh|iiin|iin|iir|ch|sh|in|ir|ee|[a-z]")
PRIOR = ROOT / "predecessor" / "gap-audit-spec.json"


def read_zl(path):
    metadata, transcribed = {}, {}
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        match = PAGE_RE.match(line)
        if match:
            metadata[match[1]] = match[2]
        m = LINE_RE.match(line)
        if m:
            raw = m[3].removeprefix("<%>").removesuffix("<$>")
            if CLEAN.fullmatch(raw):
                transcribed[(m[1], int(m[2]))] = raw
    return metadata, transcribed


def expected_positions(text):
    words = re.split(r"[.,]", text)
    separators = re.findall(r"[.,]", text)
    glyph_words = [SEGMENT.findall(word) for word in words]
    result = []
    for index, glyphs in enumerate(glyph_words):
        result.extend(("N", (a, b)) for a, b in itertools.pairwise(glyphs))
        if index < len(separators):
            kind = "D" if separators[index] == "." else "C"
            result.append((kind, (glyphs[-1], glyph_words[index + 1][0])))
    return result


def reconstruct(path, metadata, transcribed):
    with path.open(newline="", encoding="utf-8-sig") as stream:
        by_line = defaultdict(list)
        for row in csv.DictReader(stream, delimiter="\t"):
            by_line[(row["page"], int(row["line"]))].append(row)
    excluded = Counter()
    results = []
    for (page, line_n), observations in by_line.items():
        line = (page, line_n)
        if line not in transcribed or page not in metadata:
            excluded["unmapped_or_editorial_line"] += 1
            continue
        expected = expected_positions(transcribed[line])
        if [kind for kind, _ in expected] != [row["cls"] for row in observations]:
            excluded["glyph_or_separator_alignment_mismatch"] += 1
            continue
        try:
            widths = [float(row["w_px"]) for row in observations]
        except ValueError:
            excluded["unmeasured_width"] += 1
            continue
        options = []
        for i, (kind, pair) in enumerate(expected):
            if kind != "D":
                continue
            for j, (kind2, pair2) in enumerate(expected):
                if kind2 == "C" and pair == pair2:
                    options.append((abs(i - j), i, j, pair))
        if not options:
            excluded["lacks_mixed_label_pair"] += 1
            continue
        distance, period, comma, pair = min(options)
        threshold = float(observations[period]["thr"])
        assert threshold == float(observations[comma]["thr"])
        equal = observations[period]["counts_equal"] == "1"
        results.append({
            "locus": f"{page}.{line_n}", "folio": page, "quire": metadata[page],
            "pair": list(pair), "glyph_distance": distance, "certain_left": period < comma,
            "certain_px": widths[period], "uncertain_px": widths[comma], "threshold": threshold,
            "difference": (widths[period] - widths[comma]) / threshold,
            "counts_equal": equal,
        })
    return results, dict(excluded), len(by_line)


def summary(rows):
    by_quire = defaultdict(list)
    for row in rows:
        by_quire[row["quire"]].append(row["difference"])
    values = {q: statistics.mean(v) for q, v in sorted(by_quire.items())}
    pool = list(values.values())
    rng = random.Random(1947)
    boot = sorted(statistics.mean(rng.choices(pool, k=len(pool))) for _ in range(4000))
    return {
        "lines": len(rows), "folios": len(set(row["folio"] for row in rows)), "quires": len(pool),
        "certain_larger": sum(row["difference"] > 0 for row in rows),
        "equal": sum(row["difference"] == 0 for row in rows),
        "pooled_mean": statistics.mean(row["difference"] for row in rows),
        "equal_quire_mean": statistics.mean(pool), "quire_effects": values,
        "bootstrap_quire_95": [boot[int(.025 * len(boot))], boot[math.ceil(.975 * len(boot)) - 1]],
    }


def main():
    zl = ROOT.parent / "voynich-swarm" / "data" / "raw" / "ZL3b-n.txt"
    observed = json.loads(PRIOR.read_text())["s47_reanalysis"]
    rows, excluded, examined = reconstruct(ROOT / "predecessor/s47/positions.tsv", *read_zl(zl))
    old = {r["locus"]: r for r in observed["rows"]}
    rebuilt = {r["locus"]: r for r in rows}
    common = sorted(old.keys() & rebuilt.keys())
    fields = ("folio", "quire", "pair", "glyph_distance", "certain_left", "certain_px",
              "uncertain_px", "threshold", "difference", "counts_equal")
    mismatched = {key: {field: [old[key][field], rebuilt[key][field]]
                        for field in fields if old[key][field] != rebuilt[key][field]}
                  for key in common if any(old[key][field] != rebuilt[key][field] for field in fields)}
    control = {
        "examined_lines": examined, "reconstructed_lines": len(rows),
        "archive_completed_lines": len(old), "shared_loci": len(common),
        "old_only": sorted(old.keys() - rebuilt.keys()),
        "rebuilt_only": sorted(rebuilt.keys() - old.keys()),
        "mismatched_fields": mismatched, "exclusions": excluded,
        "original_rows_report": summary(list(old.values())),
        "original_rows_minus_original_alignment_fault": summary(
            [r for r in old.values() if r["locus"] != "f35r.8"]
        ),
    }
    (ROOT / "archive-recount.json").write_text(json.dumps(control, indent=2) + "\n")
    print(json.dumps(control, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.compare_blind_edges.py:
"""Unmask the agreed optical readings and trace the source detector intervals."""
import hashlib
import json
from pathlib import Path
import re
from statistics import mean


ROOT = Path(__file__).resolve().parent
Q = {
    "T24": ("f35r.8", 6, "f35r", "The 242-pixel group gap lies on the preceding detected row."),
    "T67": ("f115v.28", 27, "f115v", "The first detected group at x388–498 contains the red-centered star. The 76-pixel interval reaches from its envelope to the first text group."),
    "T39W": ("f56v.9", 8, "f56v", "Twelve detected groups are aligned to five words. The interval x1386–1428 reported for the comma falls at the measured period transition."),
    "T15": ("f58r.41", 41, "f58r", "The reported 40-pixel interval x1130–1170 lies earlier in the row. The actual comma transition lies inside the last combined detector group."),
}


def load(relative):
    return json.loads((ROOT / relative).read_text())


def gap(x_edges):
    return max(0, x_edges[1] - x_edges[0] - 1)


def bounds(ranges):
    left, right = ranges
    return gap((left[1], right[0])), gap((left[0], right[1]))


def extract_transcripts(locus):
    result = {}
    raw = ROOT.parent / "voynich-swarm" / "data" / "raw"
    for edition in ("ZL3b-n", "IT2a-n", "RF1b-e"):
        with (raw / (edition + ".txt")).open(encoding="utf-8-sig") as fh:
            entries = [line.partition(">")[2].strip()
                       for line in fh if line.startswith(f"<{locus},")]
        assert len(entries) == 1, (edition, locus)
        result[edition] = entries[0].removeprefix("<%>").removesuffix("<$>")
    return result


def marker_classes(text):
    classes = {}
    continuous = 0
    for char in text:
        if char in ".,":
            classes[continuous] = "period" if char == "." else "comma"
        else:
            continuous += 1
    return classes


def summarize(panel, locus, index, page, explanation, reads, old):
    masked = load(f"blind-read/{panel}.json")
    transcripts = extract_transcripts(locus)
    assert re.sub("[.,]", "", transcripts["ZL3b-n"]) == masked["separator_erased_eva"]
    by_pos = marker_classes(transcripts["ZL3b-n"])
    classes = {name: by_pos[pos] for name, pos in masked["transition_after_eva_chars"].items()}
    assert set(classes.values()) == {"period", "comma"}
    reverse = {kind: name for name, kind in classes.items()}
    a, b = reads.values()
    interreader = {
        name: [abs(i - j) for i, j in zip(a["edges"][name], b["edges"][name], strict=True)]
        for name in classes
    }
    assert max(all_values := [v for parts in interreader.values() for v in parts]) <= 10
    tape = {}
    for name, reader in reads.items():
        dot, comma = (reverse[k] for k in ("period", "comma"))
        point_d, point_c = (gap(reader["edges"][k]) for k in (dot, comma))
        lo_d, hi_d = bounds(reader["edge_ranges"][dot])
        lo_c, hi_c = bounds(reader["edge_ranges"][comma])
        tape[name] = {
            "period_gap_native_px": point_d, "comma_gap_native_px": point_c,
            "period_minus_comma_native_px": point_d - point_c,
            "conservative_range_from_edge_estimates": [lo_d - hi_c, hi_d - lo_c],
        }
    path = f"predecessor/s45/{page}.json"
    detector = load(path)
    assigned = next(row for row in detector["alignment"] if index in row["det"])
    groups = detector["lines"][index]["tokens"]
    measured_gap_origins = {
        key: [[left["x1"], right["x0"]] for left, right in zip(groups[:-1], groups[1:])
              if right["x0"] - left["x1"] == old[key]]
        for key in ("certain_px", "uncertain_px")
    }
    outcome = {
        "locus": locus, "panel": panel, "transliterations": transcripts, "ZL_marker_classes": classes,
        "prior_S47_row": old, "reported_S45_alignment": assigned,
        "native_detection_bbox": detector["lines"][index]["bbox"],
        "selected_detector_index_0_based": index,
        "S45_source_digest": hashlib.sha256((ROOT / path).read_bytes()).hexdigest(),
        "detector_x_group_intervals": [[row["x0"], row["x1"]] for row in groups],
        "detector_intervals_with_same_recorded_width": measured_gap_origins,
        "detector_link_diagnosis": explanation,
        "edges": {name: {key: mean([a["edges"][marker][i], b["edges"][marker][i]])
                         for i, key in enumerate(("left_glyph_right_edge", "right_glyph_left_edge"))}
                  for name, marker in reverse.items()},
        "interreader_edge_differences": interreader,
        "maximum_interreader_edge_difference": max(all_values),
        "both_20px_and_10px_edge_agreement": all(v <= 10 for v in all_values),
        "per_reader_gaps_native_px": tape,
        "mean_gap_native_px": {
            name: mean(row[f"{name}_gap_native_px"] for row in tape.values())
            for name in ("period", "comma")
        },
        "mean_difference_native_px": mean(row["period_minus_comma_native_px"] for row in tape.values()),
        "worst_case_sign_range_native_px": [
            min(row["conservative_range_from_edge_estimates"][0] for row in tape.values()),
            max(row["conservative_range_from_edge_estimates"][1] for row in tape.values()),
        ],
    }
    return outcome


def main():
    rows = load("blind-reads.json")["panels"]
    archived = {r["locus"]: r for r in load("predecessor/gap-audit-spec.json")["s47_reanalysis"]["rows"]}
    results = {
        panel: summarize(panel, locus, det, page, note, rows[panel], archived[locus])
        for panel, (locus, det, page, note) in Q.items()
    }
    assert all(result["mean_difference_native_px"] > 0 for result in results.values())
    assert all(result["prior_S47_row"]["difference"] < 0 for result in results.values())
    (ROOT / "native-edge-results.json").write_text(json.dumps(results, indent=2) + "\n")
    for result in results.values():
        print(result["locus"], result["mean_gap_native_px"], result["mean_difference_native_px"],
              result["worst_case_sign_range_native_px"], result["detector_intervals_with_same_recorded_width"])


if __name__ == "__main__":
    main()

scripts_as_text.audit_archive_alignment.py:
"""Reconstruct the previous exact-pair S47 audit and its one-row sensitivity."""
from collections import Counter, defaultdict
import csv
import itertools
import json
import math
from pathlib import Path
import random
import re
import statistics


ROOT = Path(__file__).resolve().parent
LINE_RE = re.compile(r"^<(f\d+[rv]\d*)\.(\d+),[^>]*P\d*>\s*(\S+)")
PAGE_RE = re.compile(r"^<(f\d+[rv]\d*)>\s*<!.*?\$Q=([A-Z])")
CLEAN = re.compile(r"[a-z]+(?:[.,][a-z]+)*$")
SEGMENT = re.compile(r"cth|ckh|cph|cfh|iiin|iin|iir|ch|sh|in|ir|ee|[a-z]")
PRIOR = ROOT / "predecessor" / "gap-audit-spec.json"


def read_zl(path):
    metadata, transcribed = {}, {}
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        match = PAGE_RE.match(line)
        if match:
            metadata[match[1]] = match[2]
        m = LINE_RE.match(line)
        if m:
            raw = m[3].removeprefix("<%>").removesuffix("<$>")
            if CLEAN.fullmatch(raw):
                transcribed[(m[1], int(m[2]))] = raw
    return metadata, transcribed


def expected_positions(text):
    words = re.split(r"[.,]", text)
    separators = re.findall(r"[.,]", text)
    glyph_words = [SEGMENT.findall(word) for word in words]
    result = []
    for index, glyphs in enumerate(glyph_words):
        result.extend(("N", (a, b)) for a, b in itertools.pairwise(glyphs))
        if index < len(separators):
            kind = "D" if separators[index] == "." else "C"
            result.append((kind, (glyphs[-1], glyph_words[index + 1][0])))
    return result


def reconstruct(path, metadata, transcribed):
    with path.open(newline="", encoding="utf-8-sig") as stream:
        by_line = defaultdict(list)
        for row in csv.DictReader(stream, delimiter="\t"):
            by_line[(row["page"], int(row["line"]))].append(row)
    excluded = Counter()
    results = []
    for (page, line_n), observations in by_line.items():
        line = (page, line_n)
        if line not in transcribed or page not in metadata:
            excluded["unmapped_or_editorial_line"] += 1
            continue
        expected = expected_positions(transcribed[line])
        if [kind for kind, _ in expected] != [row["cls"] for row in observations]:
            excluded["glyph_or_separator_alignment_mismatch"] += 1
            continue
        try:
            widths = [float(row["w_px"]) for row in observations]
        except ValueError:
            excluded["unmeasured_width"] += 1
            continue
        options = []
        for i, (kind, pair) in enumerate(expected):
            if kind != "D":
                continue
            for j, (kind2, pair2) in enumerate(expected):
                if kind2 == "C" and pair == pair2:
                    options.append((abs(i - j), i, j, pair))
        if not options:
            excluded["lacks_mixed_label_pair"] += 1
            continue
        distance, period, comma, pair = min(options)
        threshold = float(observations[period]["thr"])
        assert threshold == float(observations[comma]["thr"])
        equal = observations[period]["counts_equal"] == "1"
        results.append({
            "locus": f"{page}.{line_n}", "folio": page, "quire": metadata[page],
            "pair": list(pair), "glyph_distance": distance, "certain_left": period < comma,
            "certain_px": widths[period], "uncertain_px": widths[comma], "threshold": threshold,
            "difference": (widths[period] - widths[comma]) / threshold,
            "counts_equal": equal,
        })
    return results, dict(excluded), len(by_line)


def summary(rows):
    by_quire = defaultdict(list)
    for row in rows:
        by_quire[row["quire"]].append(row["difference"])
    values = {q: statistics.mean(v) for q, v in sorted(by_quire.items())}
    pool = list(values.values())
    rng = random.Random(1947)
    boot = sorted(statistics.mean(rng.choices(pool, k=len(pool))) for _ in range(4000))
    return {
        "lines": len(rows), "folios": len(set(row["folio"] for row in rows)), "quires": len(pool),
        "certain_larger": sum(row["difference"] > 0 for row in rows),
        "equal": sum(row["difference"] == 0 for row in rows),
        "pooled_mean": statistics.mean(row["difference"] for row in rows),
        "equal_quire_mean": statistics.mean(pool), "quire_effects": values,
        "bootstrap_quire_95": [boot[int(.025 * len(boot))], boot[math.ceil(.975 * len(boot)) - 1]],
    }


def main():
    zl = ROOT.parent / "voynich-swarm" / "data" / "raw" / "ZL3b-n.txt"
    observed = json.loads(PRIOR.read_text())["s47_reanalysis"]
    rows, excluded, examined = reconstruct(ROOT / "predecessor/s47/positions.tsv", *read_zl(zl))
    old = {r["locus"]: r for r in observed["rows"]}
    rebuilt = {r["locus"]: r for r in rows}
    common = sorted(old.keys() & rebuilt.keys())
    fields = ("folio", "quire", "pair", "glyph_distance", "certain_left", "certain_px",
              "uncertain_px", "threshold", "difference", "counts_equal")
    mismatched = {key: {field: [old[key][field], rebuilt[key][field]]
                        for field in fields if old[key][field] != rebuilt[key][field]}
                  for key in common if any(old[key][field] != rebuilt[key][field] for field in fields)}
    control = {
        "examined_lines": examined, "reconstructed_lines": len(rows),
        "archive_completed_lines": len(old), "shared_loci": len(common),
        "old_only": sorted(old.keys() - rebuilt.keys()),
        "rebuilt_only": sorted(rebuilt.keys() - old.keys()),
        "mismatched_fields": mismatched, "exclusions": excluded,
        "original_rows_report": summary(list(old.values())),
        "original_rows_minus_original_alignment_fault": summary(
            [r for r in old.values() if r["locus"] != "f35r.8"]
        ),
    }
    (ROOT / "archive-recount.json").write_text(json.dumps(control, indent=2) + "\n")
    print(json.dumps(control, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.compare_blind_edges.py:
"""Unmask the agreed optical readings and trace the source detector intervals."""
import hashlib
import json
from pathlib import Path
import re
from statistics import mean


ROOT = Path(__file__).resolve().parent
Q = {
    "T24": ("f35r.8", 6, "f35r", "The 242-pixel group gap lies on the preceding detected row."),
    "T67": ("f115v.28", 27, "f115v", "The first detected group at x388–498 contains the red-centered star. The 76-pixel interval reaches from its envelope to the first text group."),
    "T39W": ("f56v.9", 8, "f56v", "Twelve detected groups are aligned to five words. The interval x1386–1428 reported for the comma falls at the measured period transition."),
    "T15": ("f58r.41", 41, "f58r", "The reported 40-pixel interval x1130–1170 lies earlier in the row. The actual comma transition lies inside the last combined detector group."),
}


def load(relative):
    return json.loads((ROOT / relative).read_text())


def gap(x_edges):
    return max(0, x_edges[1] - x_edges[0] - 1)


def bounds(ranges):
    left, right = ranges
    return gap((left[1], right[0])), gap((left[0], right[1]))


def extract_transcripts(locus):
    result = {}
    raw = ROOT.parent / "voynich-swarm" / "data" / "raw"
    for edition in ("ZL3b-n", "IT2a-n", "RF1b-e"):
        with (raw / (edition + ".txt")).open(encoding="utf-8-sig") as fh:
            entries = [line.partition(">")[2].strip()
                       for line in fh if line.startswith(f"<{locus},")]
        assert len(entries) == 1, (edition, locus)
        result[edition] = entries[0].removeprefix("<%>").removesuffix("<$>")
    return result


def marker_classes(text):
    classes = {}
    continuous = 0
    for char in text:
        if char in ".,":
            classes[continuous] = "period" if char == "." else "comma"
        else:
            continuous += 1
    return classes


def summarize(panel, locus, index, page, explanation, reads, old):
    masked = load(f"blind-read/{panel}.json")
    transcripts = extract_transcripts(locus)
    assert re.sub("[.,]", "", transcripts["ZL3b-n"]) == masked["separator_erased_eva"]
    by_pos = marker_classes(transcripts["ZL3b-n"])
    classes = {name: by_pos[pos] for name, pos in masked["transition_after_eva_chars"].items()}
    assert set(classes.values()) == {"period", "comma"}
    reverse = {kind: name for name, kind in classes.items()}
    a, b = reads.values()
    interreader = {
        name: [abs(i - j) for i, j in zip(a["edges"][name], b["edges"][name], strict=True)]
        for name in classes
    }
    assert max(all_values := [v for parts in interreader.values() for v in parts]) <= 10
    tape = {}
    for name, reader in reads.items():
        dot, comma = (reverse[k] for k in ("period", "comma"))
        point_d, point_c = (gap(reader["edges"][k]) for k in (dot, comma))
        lo_d, hi_d = bounds(reader["edge_ranges"][dot])
        lo_c, hi_c = bounds(reader["edge_ranges"][comma])
        tape[name] = {
            "period_gap_native_px": point_d, "comma_gap_native_px": point_c,
            "period_minus_comma_native_px": point_d - point_c,
            "conservative_range_from_edge_estimates": [lo_d - hi_c, hi_d - lo_c],
        }
    path = f"predecessor/s45/{page}.json"
    detector = load(path)
    assigned = next(row for row in detector["alignment"] if index in row["det"])
    groups = detector["lines"][index]["tokens"]
    measured_gap_origins = {
        key: [[left["x1"], right["x0"]] for left, right in zip(groups[:-1], groups[1:])
              if right["x0"] - left["x1"] == old[key]]
        for key in ("certain_px", "uncertain_px")
    }
    outcome = {
        "locus": locus, "panel": panel, "transliterations": transcripts, "ZL_marker_classes": classes,
        "prior_S47_row": old, "reported_S45_alignment": assigned,
        "native_detection_bbox": detector["lines"][index]["bbox"],
        "selected_detector_index_0_based": index,
        "S45_source_digest": hashlib.sha256((ROOT / path).read_bytes()).hexdigest(),
        "detector_x_group_intervals": [[row["x0"], row["x1"]] for row in groups],
        "detector_intervals_with_same_recorded_width": measured_gap_origins,
        "detector_link_diagnosis": explanation,
        "edges": {name: {key: mean([a["edges"][marker][i], b["edges"][marker][i]])
                         for i, key in enumerate(("left_glyph_right_edge", "right_glyph_left_edge"))}
                  for name, marker in reverse.items()},
        "interreader_edge_differences": interreader,
        "maximum_interreader_edge_difference": max(all_values),
        "both_20px_and_10px_edge_agreement": all(v <= 10 for v in all_values),
        "per_reader_gaps_native_px": tape,
        "mean_gap_native_px": {
            name: mean(row[f"{name}_gap_native_px"] for row in tape.values())
            for name in ("period", "comma")
        },
        "mean_difference_native_px": mean(row["period_minus_comma_native_px"] for row in tape.values()),
        "worst_case_sign_range_native_px": [
            min(row["conservative_range_from_edge_estimates"][0] for row in tape.values()),
            max(row["conservative_range_from_edge_estimates"][1] for row in tape.values()),
        ],
    }
    return outcome


def main():
    rows = load("blind-reads.json")["panels"]
    archived = {r["locus"]: r for r in load("predecessor/gap-audit-spec.json")["s47_reanalysis"]["rows"]}
    results = {
        panel: summarize(panel, locus, det, page, note, rows[panel], archived[locus])
        for panel, (locus, det, page, note) in Q.items()
    }
    assert all(result["mean_difference_native_px"] > 0 for result in results.values())
    assert all(result["prior_S47_row"]["difference"] < 0 for result in results.values())
    (ROOT / "native-edge-results.json").write_text(json.dumps(results, indent=2) + "\n")
    for result in results.values():
        print(result["locus"], result["mean_gap_native_px"], result["mean_difference_native_px"],
              result["worst_case_sign_range_native_px"], result["detector_intervals_with_same_recorded_width"])


if __name__ == "__main__":
    main()

reproduction.label_onset_sensitivity.py:
"""Public-practice label-versus-paragraph onset sensitivity, without fact scoring."""

import argparse
from bisect import bisect_right
from collections import Counter, defaultdict
from dataclasses import dataclass
from itertools import accumulate
import json
from math import comb, fsum
from pathlib import Path
import random

from vs import corpus, dsl, ivtff


SEED = 125601
PERMUTATIONS = 999
UNITS = ("L", "P")


@dataclass(frozen=True)
class Layer:
    n: int
    o: int


@dataclass(frozen=True)
class Stratum:
    folio: str
    quire: str
    length: int
    label: Layer
    paragraph: Layer

    @property
    def weight(self):
        return self.label.n * self.paragraph.n / (self.label.n + self.paragraph.n)


def cells(pages, scope):
    quire = {page.id: page.meta.get("Q", "unknown") for page in pages}
    counts = defaultdict(lambda: {unit: Counter() for unit in UNITS})
    selection = {"unit": list(UNITS), "position": "line_initial", "certain": True}
    for token in dsl.select(dsl.tokens(pages, scope), selection):
        glyphs = ivtff.segment(token["w"], "eva-basic")
        if glyphs:
            counts[token["folio"], len(glyphs)][token["unit"]][glyphs[0] == "o"] += 1
    return [Stratum(folio, quire[folio], length,
                    *(Layer(sum(c[unit].values()), c[unit][True]) for unit in UNITS))
            for (folio, length), c in sorted(counts.items())]


def raw(strata):
    def layer(attr):
        rows = [getattr(x, attr) for x in strata]
        n, o = sum(x.n for x in rows), sum(x.o for x in rows)
        return {"n": n, "prefix_o": o, "rate": o / n if n else None}

    label, paragraph = (layer(kind) for kind in ("label", "paragraph"))
    effective = label["rate"] is not None and paragraph["rate"] is not None
    return {"pages": len({s.folio for s in strata}), "strata": len(strata),
            "label": label, "paragraph_line": paragraph,
            "difference": label["rate"] - paragraph["rate"] if effective else None}


def standardized(strata):
    weight = fsum(s.weight for s in strata)
    if not weight:
        return {"weight": 0.0, "label_rate": None, "paragraph_line_rate": None, "difference": None}
    label = fsum(s.weight * s.label.o / s.label.n for s in strata) / weight
    paragraph = fsum(s.weight * s.paragraph.o / s.paragraph.n for s in strata) / weight
    return {"weight": weight, "label_rate": label, "paragraph_line_rate": paragraph, "difference": label - paragraph}


def _hypergeom(stratum):
    label, paragraph = stratum.label, stratum.paragraph
    hits = label.o + paragraph.o
    misses = label.n + paragraph.n - hits
    low = max(0, label.n - misses)
    high = min(label.n, hits)
    weights = [comb(hits, x) * comb(misses, label.n - x) for x in range(low, high + 1)]
    return low, tuple(accumulate(weights))


def conditional_shuffle(strata):
    if not strata:
        return None
    cases = [_hypergeom(s) for s in strata]
    observed = sum(s.label.o for s in strata)
    rng = random.Random(SEED)
    # With fixed stratum margins the weighted numerator for a cell simplifies
    # to X - n_L*(number of hits)/N. The one-sided tail can compare integer X.
    randomized = [sum(low + bisect_right(cumulative, rng.randrange(cumulative[-1]))
                      for low, cumulative in cases) for _ in range(PERMUTATIONS)]
    tail = sum(value >= observed for value in randomized)
    return {"seed": SEED, "draws": PERMUTATIONS, "observed_label_prefix_o": observed,
            "permuted_mean_label_prefix_o": fsum(randomized) / PERMUTATIONS,
            "upper_tail_including_ties": tail, "add_one_p": (tail + 1) / (PERMUTATIONS + 1)}


def summarize(strata):
    with_labels = {s.folio for s in strata if s.label.n}
    with_paragraphs = {s.folio for s in strata if s.paragraph.n}
    common_pages = with_labels & with_paragraphs
    matched = [s for s in strata if s.label.n and s.paragraph.n]
    by_quire = defaultdict(list)
    for row in matched:
        by_quire[row.quire].append(row)
    rows = {quire: {"raw": raw(q), "standardized": standardized(q)}
            for quire, q in sorted(by_quire.items())}
    effects = [r["standardized"]["difference"] for r in rows.values()]
    return {
        "overall": raw(strata),
        "same_pages_without_length_matching": raw([s for s in strata if s.folio in common_pages]),
        "same_page_and_length_raw": raw(matched),
        "same_page_and_length_standardized": standardized(matched),
        "within_stratum_shuffle": conditional_shuffle(matched),
        "quire_evidence": rows,
        "quire_balance": {"positive": sum(v > 1e-12 for v in effects),
                          "negative": sum(v < -1e-12 for v in effects),
                          "ties": sum(abs(v) <= 1e-12 for v in effects),
                          "equal_quire_mean_difference": fsum(effects) / len(effects) if effects else None},
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--language", choices=("A", "B"))
    parser.add_argument("--section", choices=tuple(ivtff.SECTIONS))
    parser.add_argument("--hand")
    parser.add_argument("--out", type=Path, default=Path(__file__).with_name("label_onset_sensitivity.json"))
    args = parser.parse_args()
    scope = {key: value for key in ("language", "section", "hand") if (value := getattr(args, key))}
    out = {"scope": scope, "sampling": "Public practice training and evaluation partitions, separately.",
           "selection": "Certain literal first words on L label and P paragraph lines, with no promotion of a later word.",
           "onset_and_length": "EVA-basic glyph segmentation. First glyph equals o; length is the number of segmented glyphs.",
           "matching": "Exact folio and glyph length. A cell contributes only with both kinds. Common weight n_L*n_P/(n_L+n_P).",
           "shuffle": "Shuffle onset indicators only within exact matched (folio, length) cells. This is a descriptive exchangeability sensitivity; the natural line kinds were not randomized.",
           "transliterations": {}}
    for edition in ("zl", "it"):
        train, test = corpus.split_pages("practice", translit=edition)
        out["transliterations"][edition] = {name: summarize(cells(pages, scope))
                                            for name, pages in (("training", train), ("evaluation", test))}
    args.out.write_text(json.dumps(out, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    for edition, entries in out["transliterations"].items():
        for split, report in entries.items():
            print(edition, split, report["same_page_and_length_raw"]["pages"],
                  report["same_page_and_length_standardized"]["difference"], report["quire_balance"])


if __name__ == "__main__":
    main()

reproduction.public_onsets.py:
"""Verify the proposed ratio and a stricter within-page, line-initial-only control."""
from collections import defaultdict
import json
import math
from pathlib import Path

from vs import corpus, dsl

ROOT = Path(__file__).resolve().parent
SPEC = json.loads((ROOT / "fact-spec.json").read_text())


def choose(n, k):
    return math.comb(n, k) if 0 <= k <= n else 0


def exact_tail(rows):
    coefficients = [1.0]
    observed = 0
    mixed = 0
    expected = 0.0
    for values in rows.values():
        lab, par, lab_o, par_o = values
        if not lab or not par:
            continue
        mixed += 1
        hits = lab_o + par_o
        n = lab + par
        observed += lab_o
        expected += lab * hits / n
        denominator = choose(n, lab)
        low, high = max(0, lab - (n - hits)), min(lab, hits)
        weights = [choose(hits, k) * choose(n - hits, lab - k) / denominator for k in range(low, high + 1)]
        new = [0.0] * (len(coefficients) + high)
        for current, value in enumerate(coefficients):
            for k, weight in enumerate(weights, low):
                new[current + k] += value * weight
        coefficients = new
    assert abs(math.fsum(coefficients) - 1) < 1e-10
    return {"mixed_pages": mixed, "expected_label_o": expected, "observed_label_o": observed,
            "exact_upper_tail": math.fsum(coefficients[observed:])}


def count(pages, with_dsl):
    tokens = dsl.select(dsl.tokens(pages), SPEC.get("select"))
    metric = SPEC["statistic"]["ratio"]
    selected = {kind: dsl.select(tokens, metric[selection])
                for kind, selection in (("L", "of"), ("P", "to"))}
    rows = defaultdict(lambda: [0, 0, 0, 0])
    for column, kind in enumerate(("L", "P")):
        for token in selected[kind]:
            rows[token["page"]][column] += 1
            starts_o = dsl.feature({"prefix": 1}, token["w"]) == ["o"]
            rows[token["page"]][2 + column] += int(starts_o)
    totals = [sum(row[i] for row in rows.values()) for i in range(4)]
    mixed = [row for row in rows.values() if row[0] and row[1]]
    restricted = [sum(row[i] for row in mixed) for i in range(4)]
    result = {
        "pages": len(pages), "label_first": {"o_initial": totals[2], "tokens": totals[0]},
        "paragraph_first": {"o_initial": totals[3], "tokens": totals[1]},
        "ratio": (totals[2] / totals[0]) / (totals[3] / totals[1]),
        "mixed_only": {
            "label_first": {"o_initial": restricted[2], "tokens": restricted[0]},
            "paragraph_first": {"o_initial": restricted[3], "tokens": restricted[1]},
        },
        "line_initial_only_exact_same_page_shuffle": exact_tail(rows),
    }
    if with_dsl:
        result["dsl"] = dsl.evaluate(SPEC, pages)
        assert abs(result["ratio"] - result["dsl"]["value"]) < 1e-6
    return result


def main():
    confirmed = {}
    for variant in ("zl", "it", "rf"):
        train, evaluation = corpus.split_pages("practice", variant)
        confirmed[variant] = {
            "public_train": count(train, False),
            "public_eval": count(evaluation, True),
        }
    (ROOT / "practice-results.json").write_text(json.dumps(confirmed, indent=2) + "\n")
    print(json.dumps(confirmed, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.match_positions.py:
"""Locate frozen v101 contrast members using complete aligned EVA word rows."""
from collections import defaultdict
import csv
import json
from pathlib import Path

from vs import corpus

ROOT = Path(__file__).resolve().parent
CANDIDATES = json.loads((ROOT / "candidates.json").read_text())["pairs"]


def table(filename):
    with (ROOT / filename).open(newline="") as source:
        yield from csv.DictReader(source, delimiter="\t")


def reading(row):
    return "".join(row["reading"].split())


def rect(row, prefix="", keys=("x0", "y0", "x1", "y1")):
    try:
        box = [int(row[prefix + key]) for key in keys]
    except (KeyError, ValueError):
        return None
    if box[0] >= box[2] or box[1] >= box[3]:
        return None
    return box


def lcs_table(a, b):
    out = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i, x in enumerate(a, 1):
        for j, y in enumerate(b, 1):
            out[i][j] = (out[i-1][j-1] + 1 if x == y
                         else max(out[i-1][j], out[i][j-1]))
    return out


def choose_position(zl_words, target_index, indexed):
    donor_words = [reading(row) for row in indexed]
    table_before = lcs_table(zl_words, donor_words)
    best = table_before[-1][-1]
    if len(donor_words) < 2 or best < min(2, len(zl_words)):
        return None, {"reason": "insufficient whole-line anchors", "optimal_anchors": best}
    after = lcs_table(list(reversed(zl_words)), list(reversed(donor_words)))
    admissible = [
        j for j, word in enumerate(donor_words)
        if word == zl_words[target_index]
        and table_before[target_index][j] + 1
        + after[len(zl_words) - target_index - 1][len(donor_words) - j - 1] == best
    ]
    absent = lcs_table(zl_words[:target_index] + zl_words[target_index+1:], donor_words)[-1][-1] == best
    context = {"optimal_anchors": best, "donor_word_count": len(donor_words),
               "zl_word_count": len(zl_words), "omission_is_optimal": absent,
               "admissible_word_ids": [indexed[j]["word_id"] for j in admissible]}
    if len(admissible) != 1 or absent:
        return None, dict(context, reason="target missing or ambiguous across optimal alignments")
    return indexed[admissible[0]], context


def geometry(candidates, page_map, words, letters, pages):
    result = []
    for pair in candidates:
        for symbol in ("o", "A"):
            member = pair["members"][symbol]
            locus = member["locus"]
            zi = int(member["word_ordinal_1based"]) - 1
            line = next(ln for ln in page_map[pair["page"]].lines if ln.id == locus)
            assert line.words[zi] == member["zl"] == member["it"] == pair["common_eva"]
            row, detail = choose_position(list(line.words), zi, words[locus])
            entry = {
                "pair_id": pair["pair_id"], "symbol": symbol, "page": pair["page"], "hand": pair["hand"],
                "locus": locus, "zl_word_rank_1based": zi + 1, "expected_word": member["zl"],
                "join": detail, "available": False,
            }
            if row is not None:
                glyphs = letters[row["word_id"]]
                if "".join(g["eva"] for g in glyphs) != member["zl"]:
                    detail["reason"] = "letter-coordinate sequence differs from the matched EVA word"
                else:
                    possible = [g for g in glyphs if g["eva"] == "o" and rect(g)]
                    if len(possible) != 1:
                        detail["reason"] = "no unique geometrically located EVA o in the aligned word"
                    elif possible[0]["image"] != row["image"] or not rect(row, "box_"):
                        detail["reason"] = "incompatible raster or word box"
                    else:
                        letter = possible[0]
                        entry.update({
                            "available": True, "image": row["image"],
                            "iiif_image": pages[row["image"]]["iiif_image"],
                            "iiif_canvas": pages[row["image"]]["iiif_canvas"],
                            "word_rect": rect(row, "box_"), "glyph_rect": rect(letter),
                            "glyph_center": [float(letter["cx"]), float(letter["cy"])],
                            "word_box_id": row["word_id"], "letter_ordinal_1based": int(letter["letter"]),
                            "glyph_trust": letter["trust"],
                        })
            result.append(entry)
    return result


def main():
    relevant = {i["locus"] for pair in CANDIDATES for i in pair["members"].values()}
    words = defaultdict(list)
    for row in table("words.tsv"):
        if row["locus"] in relevant:
            words[row["locus"]].append(row)
    for word_rows in words.values():
        word_rows.sort(key=lambda row: int(row["word"]))
    word_ids = {row["word_id"] for rows in words.values() for row in rows}
    letters = defaultdict(list)
    for glyph in table("letters.tsv"):
        if glyph["word_id"] in word_ids:
            letters[glyph["word_id"]].append(glyph)
    for glyphs in letters.values():
        glyphs.sort(key=lambda row: int(row["letter"]))
    scan_index = {row["image"]: row for row in table("pages.tsv")}
    training, _ = corpus.split_pages("practice")
    page_map = {p.id: p for p in training}
    identified = geometry(CANDIDATES, page_map, words, letters, scan_index)
    (ROOT / "geometry-frozen.json").write_text(json.dumps(identified, indent=2) + "\n")
    for row in identified:
        print(row["pair_id"], row["symbol"], row["available"],
              row.get("word_box_id", row["join"].get("reason")),
              row.get("glyph_rect", row["join"].get("admissible_word_ids")))


if __name__ == "__main__":
    main()

scripts_as_text.match_v101.py:
"""Freeze all public-practice GC o/A pairs with corroborated EVA word identities."""

import argparse
from collections import Counter, defaultdict
import csv
from hashlib import sha256
import json
from pathlib import Path
import re
import sys


WORK = Path(__file__).resolve().parent
DEFAULT_REPO = WORK.parent / "voynich-swarm"
DEFAULT_ALLEN = WORK.parent / "voynich-plume-spacing-work"
TRANSCRIPTIONS = {"gc": "GC2a-n.txt", "zl": "ZL3b-n.txt", "it": "IT2a-n.txt"}
LINE = re.compile(r"^<(f\d+[rv]\d*\.\d+),[^>]+>\s*(.*)$")
VARIANTS = "oA"


def hash_file(path):
    return sha256(path.read_bytes()).hexdigest()


def raw_lines(path):
    rows = {}
    for text in path.read_text(encoding="utf-8-sig").splitlines():
        match = LINE.fullmatch(text)
        if match:
            rows[match[1]] = text
    return rows


def matched_words(corpus, ivtff, paths):
    train, _ = corpus.split_pages("practice", "gc")
    languages = ("zl", "it")
    layers = {name: {line.id: line for page in corpus.pages(name) for line in page.lines} for name in languages}
    raw = {name: raw_lines(path) for name, path in paths.items()}
    groups = defaultdict(lambda: {letter: [] for letter in VARIANTS})
    for page in train:
        for line in page.lines:
            if line.unit != "P" or any(
                line.id not in layers[name] or len(layers[name][line.id].words) != len(line.words)
                for name in languages
            ):
                continue
            for word_index, spelling in enumerate(line.words):
                if len(spelling) < 2 or ivtff.uncertain(spelling) or sum(spelling.count(c) for c in VARIANTS) != 1:
                    continue
                zl, it = (layers[name][line.id].words[word_index] for name in languages)
                if zl != it or ivtff.uncertain(zl):
                    continue
                gc_index = next(index for index, char in enumerate(spelling) if char in VARIANTS)
                target = spelling[gc_index]
                frame = spelling[:gc_index] + "_" + spelling[gc_index + 1:]
                groups[(page.id, page.hand, frame, zl)][target].append({
                    "locus": line.id,
                    "word_ordinal_1based": word_index + 1,
                    "glyph_index_0based_in_gc_word": gc_index,
                    "gc": spelling,
                    "zl": zl,
                    "it": it,
                    "preceding_zl_word": layers["zl"][line.id].words[word_index - 1] if word_index else None,
                    "following_zl_word": (
                        layers["zl"][line.id].words[word_index + 1] if word_index + 1 < len(line.words) else None
                    ),
                    "parsed_line_word_count": len(line.words),
                    "raw_locus_rows": {name: layer[line.id] for name, layer in raw.items()},
                })

    pairs = []
    for (page, hand, frame, eva), twins in groups.items():
        # Counterfactual word-pairs are paired in source encounter order, with no reuse.
        for lower, upper in zip(twins["o"], twins["A"]):
            pairs.append({
                "pair_id": f"pair-{len(pairs) + 1:02}", "page": page, "hand": hand,
                "v101_frame": frame, "common_eva": eva, "members": {"o": lower, "A": upper},
            })
    return pairs


def coordinate_hints(pairs, words_path, pages_path):
    pages = {}
    loci = {row["locus"] for pair in pairs for row in pair["members"].values()}
    rows_by_locus = defaultdict(list)
    with words_path.open(newline="") as stream:
        for row in csv.DictReader(stream, delimiter="\t"):
            if row["locus"] in loci:
                rows_by_locus[row["locus"]].append(row)
    if pages_path:
        with pages_path.open(newline="") as stream:
            pages = {row["image"]: row for row in csv.DictReader(stream, delimiter="\t")}

    for pair in pairs:
        for member in pair["members"].values():
            hints = []
            for row in rows_by_locus[member["locus"]]:
                if "".join(row["reading"].split()) != member["zl"]:
                    continue
                fields = ("box_x0", "box_y0", "box_x1", "box_y1")
                if not all(row.get(key) for key in fields):
                    continue
                hints.append({
                    "allen_word_id": row["word_id"], "allen_word_ordinal_1based": int(row["word"]),
                    "allen_same_ordinal": int(row["word"]) == member["word_ordinal_1based"],
                    "native_xyxy": [int(row[key]) for key in fields], "image": row["image"],
                    "canvas": pages.get(row["image"], {}).get("iiif_canvas"),
                    "native_image": pages.get(row["image"], {}).get("iiif_image"),
                })
            member["allen_coordinate_hints"] = hints


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=DEFAULT_REPO)
    parser.add_argument("--allen-words", type=Path, default=DEFAULT_ALLEN / "words.tsv")
    parser.add_argument("--allen-pages", type=Path, default=DEFAULT_ALLEN / "pages.tsv")
    args = parser.parse_args()
    sys.path.insert(0, str(args.repo.resolve()))
    from vs import corpus, ivtff

    paths = {name: args.repo / "data" / "raw" / file for name, file in TRANSCRIPTIONS.items()}
    pairs = matched_words(corpus, ivtff, paths)
    if args.allen_words.is_file():
        coordinate_hints(pairs, args.allen_words, args.allen_pages if args.allen_pages.is_file() else None)
    by_hand = dict(sorted(Counter(pair["hand"] for pair in pairs).items()))
    assert len(pairs) == 23 and len({pair["page"] for pair in pairs}) == 20
    assert by_hand == {"1": 2, "2": 11, "3": 10}
    dataset = {
        "split": "public practice training only from the pinned ZL split definition",
        "selection": "Certain paragraph words with exactly one GC o/A at the same position in a complete same-page GC word frame. Require equal GC/ZL/IT parsed counts on each source locus and identical certain ZL and IT words at both reparsed ordinals. Keep all matched pairs, using source encounter order without reusing occurrences. No images are consulted for selection.",
        "ordinal_limits": "Equal-length line frames and matching independent words do not establish physical registration. Word ordinals refer to the Swarm parser, which splits uncertain commas. Allen readings are geometric leads only, even when an ordinal agrees. A unique or repeated EVA name requires independent whole-word location on native scans.",
        "sources": {
            "glyph_key": "https://voynich.nu/img/extra/v101a.jpg",
            "scan_catalogue": "https://collections.library.yale.edu/manifests/2002046",
            "allen_boxes": "https://ryanallen.com/voynich/glyph-map.html",
            "transcriptions": {name: {"file": file, "sha256": hash_file(paths[name]),
                                         "url": f"https://www.voynich.nu/data/{file}"}
                               for name, file in TRANSCRIPTIONS.items()},
        },
        "counts": {"pairs": len(pairs), "pages": len({pair["page"] for pair in pairs}), "pairs_by_hand": by_hand},
        "pairs": pairs,
    }
    if args.allen_words.is_file():
        dataset["sources"]["allen_words_sha256"] = hash_file(args.allen_words)
    if args.allen_pages.is_file():
        dataset["sources"]["allen_pages_sha256"] = hash_file(args.allen_pages)
    print(json.dumps(dataset, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

scripts_as_text.measure_outline_proxy.py:
"""Measure a simple lower-right ink extent proxy, separate from visual ratings."""
import hashlib
import json
from pathlib import Path
import re
from statistics import median

import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parent
LEVELS = (0.45, 0.55, 0.65)
REGION = re.compile(r"/(\d+),(\d+),\d+,\d+/full/0/default\.jpg$")


def height_proxy(record, gray_fraction, margin=0, reference_band="center"):
    url = record["native_crop_url"]
    origin_x, origin_y = map(int, REGION.search(url).groups())
    path = ROOT / "native-cache" / (hashlib.sha256(url.encode()).hexdigest() + ".jpg")
    native_xyxy = record["glyph_rect"]
    xyxy = [value - origin for value, origin in zip(native_xyxy, (origin_x, origin_y) * 2, strict=True)]
    image = Image.open(path).convert("L")
    expanded = (
        max(0, xyxy[0] - margin), max(0, xyxy[1] - margin),
        min(image.width, xyxy[2] + margin), min(image.height, xyxy[3] + margin),
    )
    assert expanded[0] < expanded[2] and expanded[1] < expanded[3]
    part = image.crop(expanded)
    gray = np.array(part, dtype=float)
    low, upper = np.quantile(gray, (0.12, 0.85))
    if upper - low < 18:
        return None
    foreground = gray <= upper - gray_fraction * (upper - low)
    height, width = gray.shape
    low, high = (0.35, 0.62) if reference_band == "center" else (0.08, 0.36)
    mid = foreground[:, int(low * width):int(high * width)]
    right = foreground[:, int(0.64 * width):int(0.94 * width)]
    positions = [np.nonzero(np.count_nonzero(block, axis=1) >= 2)[0] for block in (mid, right)]
    if any(len(rows) < 3 for rows in positions):
        return None
    # Quantile rather than final pixel protects against a single isolated dark pixel row.
    quantiles = [np.quantile(rows, 0.93) for rows in positions]
    return float((quantiles[1] - quantiles[0]) / height)


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    secondary = {row["pair_id"] for row in key if "geometry_sensitivity" in row}

    def record_level(level, margin, reference_band):
        by_pair = {}
        for record in key:
            pair = by_pair.setdefault(record["pair_id"], {})
            pair[record["symbol"]] = height_proxy(record, level, margin, reference_band)
        contrasts = {
            pair: result["A"] - result["o"] for pair, result in sorted(by_pair.items())
            if all(result.get(symbol) is not None for symbol in ("o", "A"))
        }
        return {
            "available_pairs": len(contrasts),
            "A_has_larger_proxy": sum(delta > 1e-10 for delta in contrasts.values()),
            "o_has_larger_proxy": sum(delta < -1e-10 for delta in contrasts.values()),
            "ties": sum(abs(delta) <= 1e-10 for delta in contrasts.values()),
            "median_A_minus_o": median(contrasts.values()) if contrasts else None,
            "strict_pairs": sum(pair not in secondary for pair in contrasts),
            "strict_A_has_larger_proxy": sum(delta > 1e-10 for pair, delta in contrasts.items() if pair not in secondary),
            "per_pair_contrast": contrasts,
        }

    per_level = {str(level): record_level(level, 0, "center") for level in LEVELS}
    stress_results = {
        f"band={band},padding={margin},contrast={level}": record_level(level, margin, band)
        for band in ("left", "center")
        for margin in (-2, 0, 2)
        for level in LEVELS
    }
    result = {
        "method": (
            "Measure position of low rows with ink in the central and right bands of each "
            "located glyph's native bounding rectangle. The 93rd percentile of accepted "
            "rows on the right minus the corresponding central percentile, divided by "
            "glyph height, is an exploratory projection proxy. Three contrast fractions "
            "and every available comparison are shown. This proxy depends on the "
            "letter-coordinate crop and cannot determine pen continuity or the class."
        ),
        "results": per_level,
        "supplementary_crop_and_reference_band_sensitivity": stress_results,
    }
    (ROOT / "outline-proxy.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({key: {k: v for k, v in row.items() if k != "per_pair_contrast"}
                      for key, row in per_level.items()}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.score_blind_shapes.py:
"""Unmask two frozen blind ratings against v101 and summarize paired shapes."""

import argparse
from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path


V101_REFERENCE = {"o": "R1", "A": "R2"}
PROJECTION_REFERENCE = {"absent": "R1", "present": "R2"}
DEFINITE = {
    "family": ("loop_family", "other_family"),
    "closure": ("closed", "visibly_open"),
    "aperture": ("top", "bottom", "left", "right", "none"),
    "projection": ("present", "absent"),
    "reference": ("R1", "R2"),
}
FIELD_ALIASES = {
    "aperture": "aperture_side",
    "projection": "lower_right_projection",
    "reference": "neutral_reference",
}
VALUE_ALIASES = {
    "family": {"loop": "loop_family", "other": "other_family"},
    "closure": {"open": "visibly_open"},
    "aperture": {},
    "projection": {"yes": "present", "no": "absent"},
    "reference": {"r1": "R1", "r2": "R2"},
}
EXTRA = {"aperture": ("ambiguous",), "reference": ("neither",)}
ORIENTATIONS = ("expected", "reverse", "both_R1", "both_R2", "no_consensus")


def normalized_rating(rating):
    """Keep unresolved, neither, ambiguity and missing data distinct."""
    result = {}
    for field, definite in DEFINITE.items():
        raw = rating.get(field, rating.get(FIELD_ALIASES.get(field)))
        if raw is None:
            result[field] = "missing"
            continue
        if not isinstance(raw, str):
            raise ValueError(f"{field}: expected a rating string, received {raw!r}")
        value = raw.strip().lower()
        if value in ("u", "unclear"):
            value = "unresolved"
        value = VALUE_ALIASES[field].get(value, value)
        if value not in (*definite, *EXTRA.get(field, ()), "unresolved"):
            raise ValueError(f"{field}: unrecognized rating {raw!r}")
        result[field] = value
    return result


def ratio(num, den):
    return num / den if den else None


def agreement(series, fields):
    """Exact agreement over all cards and among jointly definite ratings."""
    complete = agreeing = definite = agreeing_definite = 0
    table = defaultdict(Counter)
    for left, right in series:
        a = tuple(left[f] for f in fields)
        b = tuple(right[f] for f in fields)
        if len(fields) == 1:
            table[a[0]][b[0]] += 1
        rated = "missing" not in a and "missing" not in b
        jointly_definite = all(left[f] in DEFINITE[f] and right[f] in DEFINITE[f] for f in fields)
        complete += rated
        agreeing += rated and a == b
        definite += jointly_definite
        agreeing_definite += jointly_definite and a == b
    result = {
        "n_cards": len(series), "n_jointly_rated": complete, "exact_agreements": agreeing,
        "agreement_all_cards": ratio(agreeing, len(series)),
        "agreement_jointly_rated": ratio(agreeing, complete),
        "n_jointly_definite": definite, "definite_exact_agreements": agreeing_definite,
        "agreement_jointly_definite": ratio(agreeing_definite, definite),
    }
    if len(fields) == 1:
        result["confusion_reader1_to_reader2"] = dict(table)
    return result


def decision(row, field):
    """Return a shared definite class, or the reason for withholding it."""
    left, right = (reader[field] for reader in row["ratings"])
    if "missing" in (left, right):
        return "missing"
    if left != right:
        return "disagreement"
    return left


def class_rates(rows, field, mapping):
    """Evaluate each reader and definite consensus against the v101 chart."""
    decisions = {
        "reader1": lambda row: row["ratings"][0][field],
        "reader2": lambda row: row["ratings"][1][field],
        "consensus": lambda row: decision(row, field),
    }
    report = {}
    for observer, classify in decisions.items():
        by_symbol = {}
        for symbol, expected in V101_REFERENCE.items():
            observed = Counter(classify(row) for row in rows if row["symbol"] == symbol)
            n = observed.total()
            definite = sum(observed[result] for result in mapping)
            correct = sum(observed[result] for result, label in mapping.items() if label == expected)
            by_symbol[symbol] = {
                "n_cards": n, "decisions": dict(observed), "n_definite": definite,
                "n_chart_agreement": correct, "coverage": ratio(definite, n),
                "chart_agreement_all_cards": ratio(correct, n),
                "chart_agreement_definite": ratio(correct, definite),
            }
        total = sum(v["n_cards"] for v in by_symbol.values())
        definite = sum(v["n_definite"] for v in by_symbol.values())
        correct = sum(v["n_chart_agreement"] for v in by_symbol.values())
        report[observer] = {"by_symbol": by_symbol, "n_cards": total, "n_definite": definite,
                            "n_chart_agreement": correct, "coverage": ratio(definite, total),
                            "chart_agreement_all_cards": ratio(correct, total),
                            "chart_agreement_definite": ratio(correct, definite)}
    return report


def crop_summary(rows):
    series = [row["ratings"] for row in rows]
    return {
        "agreement": {field: agreement(series, (field,)) for field in DEFINITE},
        "all_variant_features_together": agreement(series, ("closure", "aperture", "projection", "reference")),
        "chart_reference": class_rates(rows, "reference", {"R1": "R1", "R2": "R2"}),
        "chart_projection_sensitivity": class_rates(rows, "projection", PROJECTION_REFERENCE),
    }


def pair_result(members, field, mapping):
    shared = {symbol: decision(row, field) for symbol, row in members.items()}
    mapped = tuple(mapping.get(shared[symbol]) for symbol in ("o", "A"))
    orientation = {
        ("R1", "R2"): "expected", ("R2", "R1"): "reverse",
        ("R1", "R1"): "both_R1", ("R2", "R2"): "both_R2",
    }.get(mapped, "no_consensus")
    return {"decisions": shared, "orientation": orientation}


def orientation_counts(rows, field):
    counts = dict.fromkeys(ORIENTATIONS, 0)
    for row in rows:
        counts[row[field]["orientation"]] += 1
    eligible = len(rows) - counts["no_consensus"]
    complementary = counts["expected"] + counts["reverse"]
    return {
        "n_complete_located_pairs": len(rows), "n_jointly_definite_agreed_pairs": eligible,
        "n_complementary": complementary, "counts": counts,
        "complementary_among_definite": ratio(complementary, eligible),
        "expected_among_definite": ratio(counts["expected"], eligible),
        "expected_among_complementary": ratio(counts["expected"], complementary),
    }


def grouped_pairs(rows, field):
    result = {"all": orientation_counts(rows, field)}
    for dimension in ("hand", "panel", "canvas"):
        groups = defaultdict(list)
        for row in rows:
            groups[row[dimension]].append(row)
        result[f"by_{dimension}"] = {name: orientation_counts(group, field)
                                     for name, group in groups.items()}
    return result


def panel_and_canvas(row):
    geometry = row.get("geometry") or {}
    panel = row.get("page") or row.get("panel") or geometry.get("page")
    canvas = row.get("iiif_canvas") or geometry.get("iiif_canvas")
    return panel or "unknown", canvas or "unknown"


def _pairs(key, positions):
    def pair_index(rows):
        indexed = defaultdict(dict)
        for row in rows:
            pair, symbol = str(row["pair_id"]), row["symbol"]
            if symbol not in V101_REFERENCE or symbol in indexed[pair]:
                raise ValueError(f"Unexpected or duplicate pair member: {pair}, {symbol!r}")
            indexed[pair][symbol] = row
        return indexed

    located = pair_index(key)
    assessed = pair_index(positions or [])
    complete = []
    incomplete = []
    for pair in sorted(set(located) | set(assessed)):
        members = located[pair]
        if members.keys() != V101_REFERENCE.keys():
            missing = {}
            for symbol in V101_REFERENCE.keys() - members.keys():
                prior = assessed.get(pair, {}).get(symbol, {})
                missing[symbol] = (prior.get("join", {}).get("reason") or
                                   ("not in the blind deck" if prior.get("available") else "no located crop"))
            incomplete.append({"pair_id": pair, "located": list(members), "missing": missing})
            continue
        paired = list(members.values())
        hands = {str(row["hand"]) for row in paired}
        panels = {panel_and_canvas(row)[0] for row in paired}
        canvases = sorted({panel_and_canvas(row)[1] for row in paired})
        if len(hands) != 1 or len(panels) != 1:
            raise ValueError(f"Matched pair {pair} spans conflicting hands or panels")
        complete.append({
            "pair_id": pair, "hand": hands.pop(), "panel": panels.pop(),
            "canvas": " + ".join(canvases),
            "blind_codes": {symbol: row["blind_code"] for symbol, row in members.items()},
            "geometry_sensitivity": {symbol: row["geometry_sensitivity"] for symbol, row in members.items()
                                     if row.get("geometry_sensitivity")},
            "reference": pair_result(members, "reference", {"R1": "R1", "R2": "R2"}),
            "projection": pair_result(members, "projection", PROJECTION_REFERENCE),
        })
    return complete, incomplete


def score(key, reader1, reader2, positions=None):
    codes = [row["blind_code"] for row in key]
    known = set(codes)
    if len(codes) != len(known):
        raise ValueError("Duplicate blind crop code")
    for n, reader in enumerate((reader1, reader2), 1):
        extra = sorted(set(reader) - known)
        if extra:
            raise ValueError(f"Reader {n} returned unknown crop codes: {', '.join(extra)}")
    crops = [
        {**row, "ratings": [normalized_rating(reader.get(row["blind_code"], {}))
                             for reader in (reader1, reader2)]}
        for row in key
    ]
    complete, incomplete = _pairs(crops, positions)
    strict = [row for row in complete if not row["geometry_sensitivity"]]
    populations = {}
    for name, pairs in (("strict_complete_pairs", strict),
                        ("all_complete_pairs_with_geometry_sensitivity", complete)):
        included = {pair["pair_id"] for pair in pairs}
        rows = [crop for crop in crops if str(crop["pair_id"]) in included]
        populations[name] = {
            "n_hands": len({pair["hand"] for pair in pairs}),
            "n_panels": len({pair["panel"] for pair in pairs}),
            "n_canvases": len({panel_and_canvas(crop)[1] for crop in rows} - {"unknown"}),
            "crop_summary": crop_summary(rows),
            "reference_orientations": grouped_pairs(pairs, "reference"),
            "projection_orientations": grouped_pairs(pairs, "projection"),
        }
    return {
        "v101_chart_reference": V101_REFERENCE,
        "projection_sensitivity_reference": PROJECTION_REFERENCE,
        "denominators": {
            "agreement": "All cards includes missing cards. Exact agreements require a rating from both readers.",
            "reference_class": "Only R1 and R2 are definite. Neither, unresolved, disagreement and missing remain visible.",
            "projection_class": "Only a shared present or absent call gives a consensus projection decision.",
            "pair_orientation": "Each member must independently receive the same definite class from both readers.",
            "geometry": "Strict pairs exclude the entire pair if either crop has a geometry_sensitivity flag.",
        },
        "all_deck_crops": crop_summary(crops),
        "pair_populations": populations,
        "complete_pairs": complete,
        "incomplete_pairs": incomplete,
        "input_position_roster_included": positions is not None,
        "ratings": [{"blind_code": row["blind_code"], "reader1": reader1.get(row["blind_code"]),
                     "reader2": reader2.get(row["blind_code"])} for row in key],
    }


def plot_projection(report, path):
    """Plot counts by v101 symbol, retaining unresolved and conflicting ratings."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.ticker import MaxNLocator

    layout = (
        ("present", "Yes", "#216a8b"),
        ("absent", "No", "#c89552"),
        ("unresolved", "Unresolved", "#8d737e"),
        ("disagreement", "Disagreement", "#6f7c55"),
        ("missing", "Missing rating", "#a6abae"),
    )
    populations = report["pair_populations"]
    chart_titles = {
        "strict_complete_pairs": "Strict complete pairs",
        "all_complete_pairs_with_geometry_sensitivity": "With secondary geometry",
    }
    symbols = tuple(V101_REFERENCE)
    fig, axes = plt.subplots(1, len(chart_titles), figsize=(8.5, 4), sharey=True)
    for ax, (name, title) in zip(axes, chart_titles.items(), strict=True):
        by_symbol = populations[name]["crop_summary"]["chart_projection_sensitivity"]["consensus"]["by_symbol"]
        base = [0] * len(symbols)
        for result, label, color in layout:
            heights = [by_symbol[symbol]["decisions"].get(result, 0) for symbol in symbols]
            ax.bar(symbols, heights, bottom=base, label=label, color=color)
            base = [prior + added for prior, added in zip(base, heights, strict=True)]
        ax.set_title(title)
        ax.set_xlabel("v101 symbol")
        ax.yaxis.set_major_locator(MaxNLocator(integer=True))
    axes[0].set_ylabel("Located glyphs")
    fig.suptitle("Lower-right projection calls by two blind readers")
    handles, labels = axes[0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="lower center", ncol=len(layout), frameon=False)
    fig.tight_layout(rect=(0, 0.1, 1, 0.95))
    fig.savefig(path, dpi=160)
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reader1", type=Path)
    parser.add_argument("reader2", type=Path)
    parser.add_argument("--key", type=Path, default=Path(__file__).with_name("private-crop-key.json"))
    parser.add_argument("--positions", type=Path, help="Full geometry roster, including unresolved crops.")
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--projection-plot", type=Path, help="Optional image of consensus projection counts.")
    args = parser.parse_args()
    paths = {"key": args.key, "reader1": args.reader1, "reader2": args.reader2}
    if args.positions:
        paths["positions"] = args.positions
    outputs = [path.resolve() for path in (args.out, args.projection_plot) if path]
    if len(set(outputs)) != len(outputs) or set(outputs) & {path.resolve() for path in paths.values()}:
        parser.error("Output paths must be distinct from one another and from inputs")
    raw = {name: path.read_bytes() for name, path in paths.items()}
    report = score(**{name: json.loads(data) for name, data in raw.items()})
    report["input_sha256"] = {name: sha256(data).hexdigest() for name, data in raw.items()}
    args.out.write_text(json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    if args.projection_plot:
        plot_projection(report, args.projection_plot)


if __name__ == "__main__":
    main()

scripts_as_text.slope_sensitivity.py:
"""Stress-test the geometric proxy against independent row-slope estimates."""
from collections import defaultdict
import csv
from itertools import combinations
import json
from pathlib import Path
from statistics import median

from measure_outline_proxy import height_proxy, LEVELS


ROOT = Path(__file__).resolve().parent


def line_slope(words, ordinate):
    anchors = []
    for r in words:
        try:
            x0, y0, x1, y1 = (int(r[f"box_{key}"]) for key in ("x0", "y0", "x1", "y1"))
        except ValueError:
            continue
        y = y1 if ordinate == "bottom_envelope" else (y0 + y1) / 2
        anchors.append(((x0 + x1) / 2, y))
    if len(anchors) < 4:
        return None
    ratios = [(yb - ya) / (xb - xa) for (xa, ya), (xb, yb) in combinations(anchors, 2)
              if abs(xb - xa) >= 100]
    return median(ratios) if len(ratios) >= 4 else None


def corrected_proxy(row, words, threshold, ordinate):
    line = [w for w in words[row["locus"]] if w["image"] == row["image"]]
    slope = line_slope(line, ordinate)
    estimate = height_proxy(row, threshold)
    if slope is None or estimate is None:
        return None
    x0, y0, x1, y1 = row["glyph_rect"]
    # Difference in nominal horizontal midpoints of the center and right bands.
    x_displacement = (0.79 - 0.485) * (x1 - x0)
    correction = slope * x_displacement / (y1 - y0)
    return {"native_dx_between_bands": x_displacement, "relative_correction": correction,
            "raw_proxy": estimate, "corrected_proxy": estimate - correction,
            "slope_px_y_per_px_x": slope}


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    required = {r["locus"] for r in key}
    words = defaultdict(list)
    with (ROOT / "words.tsv").open(newline="") as src:
        for row in csv.DictReader(src, delimiter="\t"):
            if row["locus"] in required:
                words[row["locus"]].append(row)
    estimates = {}
    for ordinate in ("bottom_envelope", "center"):
        for threshold in LEVELS:
            members = defaultdict(dict)
            for row in key:
                e = corrected_proxy(row, words, threshold, ordinate)
                if e is not None:
                    members[row["pair_id"]][row["symbol"]] = e
            pairs = {}
            by_hand = defaultdict(list)
            hands = {row["pair_id"]: row["hand"] for row in key}
            for pair, results in members.items():
                if results.keys() == {"A", "o"}:
                    delta = results["A"]["corrected_proxy"] - results["o"]["corrected_proxy"]
                    by_hand[hands[pair]].append(delta)
                    pairs[pair] = {**results, "difference_A_minus_o": delta}
            estimates[f"{ordinate}-{threshold}"] = {
                "available_pairs": len(pairs),
                "A_larger": sum(row["difference_A_minus_o"] > 1e-10 for row in pairs.values()),
                "by_hand": {
                    hand: {"pairs": len(values), "A_larger": sum(v > 1e-10 for v in values)}
                    for hand, values in sorted(by_hand.items())
                },
                "matched_pairs": pairs,
            }
    result = {
        "method": (
            "Estimate local line slope from the median of all same-image word box slopes "
            "with horizontal separation at least 100 pixels. Require at least four boxes "
            "and four qualifying slopes. Subtract the estimated y change between the "
            "nominal center of the two glyph bands. Consider word-box center and bottom "
            "as two imperfect measures of row position. This is an exploratory sensitivity "
            "to writing inclination on the originally frozen deck."
        ),
        "results": estimates,
    }
    (ROOT / "outline-slope-sensitivity.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({k: {field: value for field, value in row.items() if field != "matched_pairs"}
                      for k, row in estimates.items()}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.match_positions.py:
"""Locate frozen v101 contrast members using complete aligned EVA word rows."""
from collections import defaultdict
import csv
import json
from pathlib import Path

from vs import corpus

ROOT = Path(__file__).resolve().parent
CANDIDATES = json.loads((ROOT / "candidates.json").read_text())["pairs"]


def table(filename):
    with (ROOT / filename).open(newline="") as source:
        yield from csv.DictReader(source, delimiter="\t")


def reading(row):
    return "".join(row["reading"].split())


def rect(row, prefix="", keys=("x0", "y0", "x1", "y1")):
    try:
        box = [int(row[prefix + key]) for key in keys]
    except (KeyError, ValueError):
        return None
    if box[0] >= box[2] or box[1] >= box[3]:
        return None
    return box


def lcs_table(a, b):
    out = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i, x in enumerate(a, 1):
        for j, y in enumerate(b, 1):
            out[i][j] = (out[i-1][j-1] + 1 if x == y
                         else max(out[i-1][j], out[i][j-1]))
    return out


def choose_position(zl_words, target_index, indexed):
    donor_words = [reading(row) for row in indexed]
    table_before = lcs_table(zl_words, donor_words)
    best = table_before[-1][-1]
    if len(donor_words) < 2 or best < min(2, len(zl_words)):
        return None, {"reason": "insufficient whole-line anchors", "optimal_anchors": best}
    after = lcs_table(list(reversed(zl_words)), list(reversed(donor_words)))
    admissible = [
        j for j, word in enumerate(donor_words)
        if word == zl_words[target_index]
        and table_before[target_index][j] + 1
        + after[len(zl_words) - target_index - 1][len(donor_words) - j - 1] == best
    ]
    absent = lcs_table(zl_words[:target_index] + zl_words[target_index+1:], donor_words)[-1][-1] == best
    context = {"optimal_anchors": best, "donor_word_count": len(donor_words),
               "zl_word_count": len(zl_words), "omission_is_optimal": absent,
               "admissible_word_ids": [indexed[j]["word_id"] for j in admissible]}
    if len(admissible) != 1 or absent:
        return None, dict(context, reason="target missing or ambiguous across optimal alignments")
    return indexed[admissible[0]], context


def geometry(candidates, page_map, words, letters, pages):
    result = []
    for pair in candidates:
        for symbol in ("o", "A"):
            member = pair["members"][symbol]
            locus = member["locus"]
            zi = int(member["word_ordinal_1based"]) - 1
            line = next(ln for ln in page_map[pair["page"]].lines if ln.id == locus)
            assert line.words[zi] == member["zl"] == member["it"] == pair["common_eva"]
            row, detail = choose_position(list(line.words), zi, words[locus])
            entry = {
                "pair_id": pair["pair_id"], "symbol": symbol, "page": pair["page"], "hand": pair["hand"],
                "locus": locus, "zl_word_rank_1based": zi + 1, "expected_word": member["zl"],
                "join": detail, "available": False,
            }
            if row is not None:
                glyphs = letters[row["word_id"]]
                if "".join(g["eva"] for g in glyphs) != member["zl"]:
                    detail["reason"] = "letter-coordinate sequence differs from the matched EVA word"
                else:
                    possible = [g for g in glyphs if g["eva"] == "o" and rect(g)]
                    if len(possible) != 1:
                        detail["reason"] = "no unique geometrically located EVA o in the aligned word"
                    elif possible[0]["image"] != row["image"] or not rect(row, "box_"):
                        detail["reason"] = "incompatible raster or word box"
                    else:
                        letter = possible[0]
                        entry.update({
                            "available": True, "image": row["image"],
                            "iiif_image": pages[row["image"]]["iiif_image"],
                            "iiif_canvas": pages[row["image"]]["iiif_canvas"],
                            "word_rect": rect(row, "box_"), "glyph_rect": rect(letter),
                            "glyph_center": [float(letter["cx"]), float(letter["cy"])],
                            "word_box_id": row["word_id"], "letter_ordinal_1based": int(letter["letter"]),
                            "glyph_trust": letter["trust"],
                        })
            result.append(entry)
    return result


def main():
    relevant = {i["locus"] for pair in CANDIDATES for i in pair["members"].values()}
    words = defaultdict(list)
    for row in table("words.tsv"):
        if row["locus"] in relevant:
            words[row["locus"]].append(row)
    for word_rows in words.values():
        word_rows.sort(key=lambda row: int(row["word"]))
    word_ids = {row["word_id"] for rows in words.values() for row in rows}
    letters = defaultdict(list)
    for glyph in table("letters.tsv"):
        if glyph["word_id"] in word_ids:
            letters[glyph["word_id"]].append(glyph)
    for glyphs in letters.values():
        glyphs.sort(key=lambda row: int(row["letter"]))
    scan_index = {row["image"]: row for row in table("pages.tsv")}
    training, _ = corpus.split_pages("practice")
    page_map = {p.id: p for p in training}
    identified = geometry(CANDIDATES, page_map, words, letters, scan_index)
    (ROOT / "geometry-frozen.json").write_text(json.dumps(identified, indent=2) + "\n")
    for row in identified:
        print(row["pair_id"], row["symbol"], row["available"],
              row.get("word_box_id", row["join"].get("reason")),
              row.get("glyph_rect", row["join"].get("admissible_word_ids")))


if __name__ == "__main__":
    main()

scripts_as_text.match_v101.py:
"""Freeze all public-practice GC o/A pairs with corroborated EVA word identities."""

import argparse
from collections import Counter, defaultdict
import csv
from hashlib import sha256
import json
from pathlib import Path
import re
import sys


WORK = Path(__file__).resolve().parent
DEFAULT_REPO = WORK.parent / "voynich-swarm"
DEFAULT_ALLEN = WORK.parent / "voynich-plume-spacing-work"
TRANSCRIPTIONS = {"gc": "GC2a-n.txt", "zl": "ZL3b-n.txt", "it": "IT2a-n.txt"}
LINE = re.compile(r"^<(f\d+[rv]\d*\.\d+),[^>]+>\s*(.*)$")
VARIANTS = "oA"


def hash_file(path):
    return sha256(path.read_bytes()).hexdigest()


def raw_lines(path):
    rows = {}
    for text in path.read_text(encoding="utf-8-sig").splitlines():
        match = LINE.fullmatch(text)
        if match:
            rows[match[1]] = text
    return rows


def matched_words(corpus, ivtff, paths):
    train, _ = corpus.split_pages("practice", "gc")
    languages = ("zl", "it")
    layers = {name: {line.id: line for page in corpus.pages(name) for line in page.lines} for name in languages}
    raw = {name: raw_lines(path) for name, path in paths.items()}
    groups = defaultdict(lambda: {letter: [] for letter in VARIANTS})
    for page in train:
        for line in page.lines:
            if line.unit != "P" or any(
                line.id not in layers[name] or len(layers[name][line.id].words) != len(line.words)
                for name in languages
            ):
                continue
            for word_index, spelling in enumerate(line.words):
                if len(spelling) < 2 or ivtff.uncertain(spelling) or sum(spelling.count(c) for c in VARIANTS) != 1:
                    continue
                zl, it = (layers[name][line.id].words[word_index] for name in languages)
                if zl != it or ivtff.uncertain(zl):
                    continue
                gc_index = next(index for index, char in enumerate(spelling) if char in VARIANTS)
                target = spelling[gc_index]
                frame = spelling[:gc_index] + "_" + spelling[gc_index + 1:]
                groups[(page.id, page.hand, frame, zl)][target].append({
                    "locus": line.id,
                    "word_ordinal_1based": word_index + 1,
                    "glyph_index_0based_in_gc_word": gc_index,
                    "gc": spelling,
                    "zl": zl,
                    "it": it,
                    "preceding_zl_word": layers["zl"][line.id].words[word_index - 1] if word_index else None,
                    "following_zl_word": (
                        layers["zl"][line.id].words[word_index + 1] if word_index + 1 < len(line.words) else None
                    ),
                    "parsed_line_word_count": len(line.words),
                    "raw_locus_rows": {name: layer[line.id] for name, layer in raw.items()},
                })

    pairs = []
    for (page, hand, frame, eva), twins in groups.items():
        # Counterfactual word-pairs are paired in source encounter order, with no reuse.
        for lower, upper in zip(twins["o"], twins["A"]):
            pairs.append({
                "pair_id": f"pair-{len(pairs) + 1:02}", "page": page, "hand": hand,
                "v101_frame": frame, "common_eva": eva, "members": {"o": lower, "A": upper},
            })
    return pairs


def coordinate_hints(pairs, words_path, pages_path):
    pages = {}
    loci = {row["locus"] for pair in pairs for row in pair["members"].values()}
    rows_by_locus = defaultdict(list)
    with words_path.open(newline="") as stream:
        for row in csv.DictReader(stream, delimiter="\t"):
            if row["locus"] in loci:
                rows_by_locus[row["locus"]].append(row)
    if pages_path:
        with pages_path.open(newline="") as stream:
            pages = {row["image"]: row for row in csv.DictReader(stream, delimiter="\t")}

    for pair in pairs:
        for member in pair["members"].values():
            hints = []
            for row in rows_by_locus[member["locus"]]:
                if "".join(row["reading"].split()) != member["zl"]:
                    continue
                fields = ("box_x0", "box_y0", "box_x1", "box_y1")
                if not all(row.get(key) for key in fields):
                    continue
                hints.append({
                    "allen_word_id": row["word_id"], "allen_word_ordinal_1based": int(row["word"]),
                    "allen_same_ordinal": int(row["word"]) == member["word_ordinal_1based"],
                    "native_xyxy": [int(row[key]) for key in fields], "image": row["image"],
                    "canvas": pages.get(row["image"], {}).get("iiif_canvas"),
                    "native_image": pages.get(row["image"], {}).get("iiif_image"),
                })
            member["allen_coordinate_hints"] = hints


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=DEFAULT_REPO)
    parser.add_argument("--allen-words", type=Path, default=DEFAULT_ALLEN / "words.tsv")
    parser.add_argument("--allen-pages", type=Path, default=DEFAULT_ALLEN / "pages.tsv")
    args = parser.parse_args()
    sys.path.insert(0, str(args.repo.resolve()))
    from vs import corpus, ivtff

    paths = {name: args.repo / "data" / "raw" / file for name, file in TRANSCRIPTIONS.items()}
    pairs = matched_words(corpus, ivtff, paths)
    if args.allen_words.is_file():
        coordinate_hints(pairs, args.allen_words, args.allen_pages if args.allen_pages.is_file() else None)
    by_hand = dict(sorted(Counter(pair["hand"] for pair in pairs).items()))
    assert len(pairs) == 23 and len({pair["page"] for pair in pairs}) == 20
    assert by_hand == {"1": 2, "2": 11, "3": 10}
    dataset = {
        "split": "public practice training only from the pinned ZL split definition",
        "selection": "Certain paragraph words with exactly one GC o/A at the same position in a complete same-page GC word frame. Require equal GC/ZL/IT parsed counts on each source locus and identical certain ZL and IT words at both reparsed ordinals. Keep all matched pairs, using source encounter order without reusing occurrences. No images are consulted for selection.",
        "ordinal_limits": "Equal-length line frames and matching independent words do not establish physical registration. Word ordinals refer to the Swarm parser, which splits uncertain commas. Allen readings are geometric leads only, even when an ordinal agrees. A unique or repeated EVA name requires independent whole-word location on native scans.",
        "sources": {
            "glyph_key": "https://voynich.nu/img/extra/v101a.jpg",
            "scan_catalogue": "https://collections.library.yale.edu/manifests/2002046",
            "allen_boxes": "https://ryanallen.com/voynich/glyph-map.html",
            "transcriptions": {name: {"file": file, "sha256": hash_file(paths[name]),
                                         "url": f"https://www.voynich.nu/data/{file}"}
                               for name, file in TRANSCRIPTIONS.items()},
        },
        "counts": {"pairs": len(pairs), "pages": len({pair["page"] for pair in pairs}), "pairs_by_hand": by_hand},
        "pairs": pairs,
    }
    if args.allen_words.is_file():
        dataset["sources"]["allen_words_sha256"] = hash_file(args.allen_words)
    if args.allen_pages.is_file():
        dataset["sources"]["allen_pages_sha256"] = hash_file(args.allen_pages)
    print(json.dumps(dataset, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()

scripts_as_text.measure_outline_proxy.py:
"""Measure a simple lower-right ink extent proxy, separate from visual ratings."""
import hashlib
import json
from pathlib import Path
import re
from statistics import median

import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parent
LEVELS = (0.45, 0.55, 0.65)
REGION = re.compile(r"/(\d+),(\d+),\d+,\d+/full/0/default\.jpg$")


def height_proxy(record, gray_fraction, margin=0, reference_band="center"):
    url = record["native_crop_url"]
    origin_x, origin_y = map(int, REGION.search(url).groups())
    path = ROOT / "native-cache" / (hashlib.sha256(url.encode()).hexdigest() + ".jpg")
    native_xyxy = record["glyph_rect"]
    xyxy = [value - origin for value, origin in zip(native_xyxy, (origin_x, origin_y) * 2, strict=True)]
    image = Image.open(path).convert("L")
    expanded = (
        max(0, xyxy[0] - margin), max(0, xyxy[1] - margin),
        min(image.width, xyxy[2] + margin), min(image.height, xyxy[3] + margin),
    )
    assert expanded[0] < expanded[2] and expanded[1] < expanded[3]
    part = image.crop(expanded)
    gray = np.array(part, dtype=float)
    low, upper = np.quantile(gray, (0.12, 0.85))
    if upper - low < 18:
        return None
    foreground = gray <= upper - gray_fraction * (upper - low)
    height, width = gray.shape
    low, high = (0.35, 0.62) if reference_band == "center" else (0.08, 0.36)
    mid = foreground[:, int(low * width):int(high * width)]
    right = foreground[:, int(0.64 * width):int(0.94 * width)]
    positions = [np.nonzero(np.count_nonzero(block, axis=1) >= 2)[0] for block in (mid, right)]
    if any(len(rows) < 3 for rows in positions):
        return None
    # Quantile rather than final pixel protects against a single isolated dark pixel row.
    quantiles = [np.quantile(rows, 0.93) for rows in positions]
    return float((quantiles[1] - quantiles[0]) / height)


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    secondary = {row["pair_id"] for row in key if "geometry_sensitivity" in row}

    def record_level(level, margin, reference_band):
        by_pair = {}
        for record in key:
            pair = by_pair.setdefault(record["pair_id"], {})
            pair[record["symbol"]] = height_proxy(record, level, margin, reference_band)
        contrasts = {
            pair: result["A"] - result["o"] for pair, result in sorted(by_pair.items())
            if all(result.get(symbol) is not None for symbol in ("o", "A"))
        }
        return {
            "available_pairs": len(contrasts),
            "A_has_larger_proxy": sum(delta > 1e-10 for delta in contrasts.values()),
            "o_has_larger_proxy": sum(delta < -1e-10 for delta in contrasts.values()),
            "ties": sum(abs(delta) <= 1e-10 for delta in contrasts.values()),
            "median_A_minus_o": median(contrasts.values()) if contrasts else None,
            "strict_pairs": sum(pair not in secondary for pair in contrasts),
            "strict_A_has_larger_proxy": sum(delta > 1e-10 for pair, delta in contrasts.items() if pair not in secondary),
            "per_pair_contrast": contrasts,
        }

    per_level = {str(level): record_level(level, 0, "center") for level in LEVELS}
    stress_results = {
        f"band={band},padding={margin},contrast={level}": record_level(level, margin, band)
        for band in ("left", "center")
        for margin in (-2, 0, 2)
        for level in LEVELS
    }
    result = {
        "method": (
            "Measure position of low rows with ink in the central and right bands of each "
            "located glyph's native bounding rectangle. The 93rd percentile of accepted "
            "rows on the right minus the corresponding central percentile, divided by "
            "glyph height, is an exploratory projection proxy. Three contrast fractions "
            "and every available comparison are shown. This proxy depends on the "
            "letter-coordinate crop and cannot determine pen continuity or the class."
        ),
        "results": per_level,
        "supplementary_crop_and_reference_band_sensitivity": stress_results,
    }
    (ROOT / "outline-proxy.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({key: {k: v for k, v in row.items() if k != "per_pair_contrast"}
                      for key, row in per_level.items()}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.score_blind_shapes.py:
"""Unmask two frozen blind ratings against v101 and summarize paired shapes."""

import argparse
from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path


V101_REFERENCE = {"o": "R1", "A": "R2"}
PROJECTION_REFERENCE = {"absent": "R1", "present": "R2"}
DEFINITE = {
    "family": ("loop_family", "other_family"),
    "closure": ("closed", "visibly_open"),
    "aperture": ("top", "bottom", "left", "right", "none"),
    "projection": ("present", "absent"),
    "reference": ("R1", "R2"),
}
FIELD_ALIASES = {
    "aperture": "aperture_side",
    "projection": "lower_right_projection",
    "reference": "neutral_reference",
}
VALUE_ALIASES = {
    "family": {"loop": "loop_family", "other": "other_family"},
    "closure": {"open": "visibly_open"},
    "aperture": {},
    "projection": {"yes": "present", "no": "absent"},
    "reference": {"r1": "R1", "r2": "R2"},
}
EXTRA = {"aperture": ("ambiguous",), "reference": ("neither",)}
ORIENTATIONS = ("expected", "reverse", "both_R1", "both_R2", "no_consensus")


def normalized_rating(rating):
    """Keep unresolved, neither, ambiguity and missing data distinct."""
    result = {}
    for field, definite in DEFINITE.items():
        raw = rating.get(field, rating.get(FIELD_ALIASES.get(field)))
        if raw is None:
            result[field] = "missing"
            continue
        if not isinstance(raw, str):
            raise ValueError(f"{field}: expected a rating string, received {raw!r}")
        value = raw.strip().lower()
        if value in ("u", "unclear"):
            value = "unresolved"
        value = VALUE_ALIASES[field].get(value, value)
        if value not in (*definite, *EXTRA.get(field, ()), "unresolved"):
            raise ValueError(f"{field}: unrecognized rating {raw!r}")
        result[field] = value
    return result


def ratio(num, den):
    return num / den if den else None


def agreement(series, fields):
    """Exact agreement over all cards and among jointly definite ratings."""
    complete = agreeing = definite = agreeing_definite = 0
    table = defaultdict(Counter)
    for left, right in series:
        a = tuple(left[f] for f in fields)
        b = tuple(right[f] for f in fields)
        if len(fields) == 1:
            table[a[0]][b[0]] += 1
        rated = "missing" not in a and "missing" not in b
        jointly_definite = all(left[f] in DEFINITE[f] and right[f] in DEFINITE[f] for f in fields)
        complete += rated
        agreeing += rated and a == b
        definite += jointly_definite
        agreeing_definite += jointly_definite and a == b
    result = {
        "n_cards": len(series), "n_jointly_rated": complete, "exact_agreements": agreeing,
        "agreement_all_cards": ratio(agreeing, len(series)),
        "agreement_jointly_rated": ratio(agreeing, complete),
        "n_jointly_definite": definite, "definite_exact_agreements": agreeing_definite,
        "agreement_jointly_definite": ratio(agreeing_definite, definite),
    }
    if len(fields) == 1:
        result["confusion_reader1_to_reader2"] = dict(table)
    return result


def decision(row, field):
    """Return a shared definite class, or the reason for withholding it."""
    left, right = (reader[field] for reader in row["ratings"])
    if "missing" in (left, right):
        return "missing"
    if left != right:
        return "disagreement"
    return left


def class_rates(rows, field, mapping):
    """Evaluate each reader and definite consensus against the v101 chart."""
    decisions = {
        "reader1": lambda row: row["ratings"][0][field],
        "reader2": lambda row: row["ratings"][1][field],
        "consensus": lambda row: decision(row, field),
    }
    report = {}
    for observer, classify in decisions.items():
        by_symbol = {}
        for symbol, expected in V101_REFERENCE.items():
            observed = Counter(classify(row) for row in rows if row["symbol"] == symbol)
            n = observed.total()
            definite = sum(observed[result] for result in mapping)
            correct = sum(observed[result] for result, label in mapping.items() if label == expected)
            by_symbol[symbol] = {
                "n_cards": n, "decisions": dict(observed), "n_definite": definite,
                "n_chart_agreement": correct, "coverage": ratio(definite, n),
                "chart_agreement_all_cards": ratio(correct, n),
                "chart_agreement_definite": ratio(correct, definite),
            }
        total = sum(v["n_cards"] for v in by_symbol.values())
        definite = sum(v["n_definite"] for v in by_symbol.values())
        correct = sum(v["n_chart_agreement"] for v in by_symbol.values())
        report[observer] = {"by_symbol": by_symbol, "n_cards": total, "n_definite": definite,
                            "n_chart_agreement": correct, "coverage": ratio(definite, total),
                            "chart_agreement_all_cards": ratio(correct, total),
                            "chart_agreement_definite": ratio(correct, definite)}
    return report


def crop_summary(rows):
    series = [row["ratings"] for row in rows]
    return {
        "agreement": {field: agreement(series, (field,)) for field in DEFINITE},
        "all_variant_features_together": agreement(series, ("closure", "aperture", "projection", "reference")),
        "chart_reference": class_rates(rows, "reference", {"R1": "R1", "R2": "R2"}),
        "chart_projection_sensitivity": class_rates(rows, "projection", PROJECTION_REFERENCE),
    }


def pair_result(members, field, mapping):
    shared = {symbol: decision(row, field) for symbol, row in members.items()}
    mapped = tuple(mapping.get(shared[symbol]) for symbol in ("o", "A"))
    orientation = {
        ("R1", "R2"): "expected", ("R2", "R1"): "reverse",
        ("R1", "R1"): "both_R1", ("R2", "R2"): "both_R2",
    }.get(mapped, "no_consensus")
    return {"decisions": shared, "orientation": orientation}


def orientation_counts(rows, field):
    counts = dict.fromkeys(ORIENTATIONS, 0)
    for row in rows:
        counts[row[field]["orientation"]] += 1
    eligible = len(rows) - counts["no_consensus"]
    complementary = counts["expected"] + counts["reverse"]
    return {
        "n_complete_located_pairs": len(rows), "n_jointly_definite_agreed_pairs": eligible,
        "n_complementary": complementary, "counts": counts,
        "complementary_among_definite": ratio(complementary, eligible),
        "expected_among_definite": ratio(counts["expected"], eligible),
        "expected_among_complementary": ratio(counts["expected"], complementary),
    }


def grouped_pairs(rows, field):
    result = {"all": orientation_counts(rows, field)}
    for dimension in ("hand", "panel", "canvas"):
        groups = defaultdict(list)
        for row in rows:
            groups[row[dimension]].append(row)
        result[f"by_{dimension}"] = {name: orientation_counts(group, field)
                                     for name, group in groups.items()}
    return result


def panel_and_canvas(row):
    geometry = row.get("geometry") or {}
    panel = row.get("page") or row.get("panel") or geometry.get("page")
    canvas = row.get("iiif_canvas") or geometry.get("iiif_canvas")
    return panel or "unknown", canvas or "unknown"


def _pairs(key, positions):
    def pair_index(rows):
        indexed = defaultdict(dict)
        for row in rows:
            pair, symbol = str(row["pair_id"]), row["symbol"]
            if symbol not in V101_REFERENCE or symbol in indexed[pair]:
                raise ValueError(f"Unexpected or duplicate pair member: {pair}, {symbol!r}")
            indexed[pair][symbol] = row
        return indexed

    located = pair_index(key)
    assessed = pair_index(positions or [])
    complete = []
    incomplete = []
    for pair in sorted(set(located) | set(assessed)):
        members = located[pair]
        if members.keys() != V101_REFERENCE.keys():
            missing = {}
            for symbol in V101_REFERENCE.keys() - members.keys():
                prior = assessed.get(pair, {}).get(symbol, {})
                missing[symbol] = (prior.get("join", {}).get("reason") or
                                   ("not in the blind deck" if prior.get("available") else "no located crop"))
            incomplete.append({"pair_id": pair, "located": list(members), "missing": missing})
            continue
        paired = list(members.values())
        hands = {str(row["hand"]) for row in paired}
        panels = {panel_and_canvas(row)[0] for row in paired}
        canvases = sorted({panel_and_canvas(row)[1] for row in paired})
        if len(hands) != 1 or len(panels) != 1:
            raise ValueError(f"Matched pair {pair} spans conflicting hands or panels")
        complete.append({
            "pair_id": pair, "hand": hands.pop(), "panel": panels.pop(),
            "canvas": " + ".join(canvases),
            "blind_codes": {symbol: row["blind_code"] for symbol, row in members.items()},
            "geometry_sensitivity": {symbol: row["geometry_sensitivity"] for symbol, row in members.items()
                                     if row.get("geometry_sensitivity")},
            "reference": pair_result(members, "reference", {"R1": "R1", "R2": "R2"}),
            "projection": pair_result(members, "projection", PROJECTION_REFERENCE),
        })
    return complete, incomplete


def score(key, reader1, reader2, positions=None):
    codes = [row["blind_code"] for row in key]
    known = set(codes)
    if len(codes) != len(known):
        raise ValueError("Duplicate blind crop code")
    for n, reader in enumerate((reader1, reader2), 1):
        extra = sorted(set(reader) - known)
        if extra:
            raise ValueError(f"Reader {n} returned unknown crop codes: {', '.join(extra)}")
    crops = [
        {**row, "ratings": [normalized_rating(reader.get(row["blind_code"], {}))
                             for reader in (reader1, reader2)]}
        for row in key
    ]
    complete, incomplete = _pairs(crops, positions)
    strict = [row for row in complete if not row["geometry_sensitivity"]]
    populations = {}
    for name, pairs in (("strict_complete_pairs", strict),
                        ("all_complete_pairs_with_geometry_sensitivity", complete)):
        included = {pair["pair_id"] for pair in pairs}
        rows = [crop for crop in crops if str(crop["pair_id"]) in included]
        populations[name] = {
            "n_hands": len({pair["hand"] for pair in pairs}),
            "n_panels": len({pair["panel"] for pair in pairs}),
            "n_canvases": len({panel_and_canvas(crop)[1] for crop in rows} - {"unknown"}),
            "crop_summary": crop_summary(rows),
            "reference_orientations": grouped_pairs(pairs, "reference"),
            "projection_orientations": grouped_pairs(pairs, "projection"),
        }
    return {
        "v101_chart_reference": V101_REFERENCE,
        "projection_sensitivity_reference": PROJECTION_REFERENCE,
        "denominators": {
            "agreement": "All cards includes missing cards. Exact agreements require a rating from both readers.",
            "reference_class": "Only R1 and R2 are definite. Neither, unresolved, disagreement and missing remain visible.",
            "projection_class": "Only a shared present or absent call gives a consensus projection decision.",
            "pair_orientation": "Each member must independently receive the same definite class from both readers.",
            "geometry": "Strict pairs exclude the entire pair if either crop has a geometry_sensitivity flag.",
        },
        "all_deck_crops": crop_summary(crops),
        "pair_populations": populations,
        "complete_pairs": complete,
        "incomplete_pairs": incomplete,
        "input_position_roster_included": positions is not None,
        "ratings": [{"blind_code": row["blind_code"], "reader1": reader1.get(row["blind_code"]),
                     "reader2": reader2.get(row["blind_code"])} for row in key],
    }


def plot_projection(report, path):
    """Plot counts by v101 symbol, retaining unresolved and conflicting ratings."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.ticker import MaxNLocator

    layout = (
        ("present", "Yes", "#216a8b"),
        ("absent", "No", "#c89552"),
        ("unresolved", "Unresolved", "#8d737e"),
        ("disagreement", "Disagreement", "#6f7c55"),
        ("missing", "Missing rating", "#a6abae"),
    )
    populations = report["pair_populations"]
    chart_titles = {
        "strict_complete_pairs": "Strict complete pairs",
        "all_complete_pairs_with_geometry_sensitivity": "With secondary geometry",
    }
    symbols = tuple(V101_REFERENCE)
    fig, axes = plt.subplots(1, len(chart_titles), figsize=(8.5, 4), sharey=True)
    for ax, (name, title) in zip(axes, chart_titles.items(), strict=True):
        by_symbol = populations[name]["crop_summary"]["chart_projection_sensitivity"]["consensus"]["by_symbol"]
        base = [0] * len(symbols)
        for result, label, color in layout:
            heights = [by_symbol[symbol]["decisions"].get(result, 0) for symbol in symbols]
            ax.bar(symbols, heights, bottom=base, label=label, color=color)
            base = [prior + added for prior, added in zip(base, heights, strict=True)]
        ax.set_title(title)
        ax.set_xlabel("v101 symbol")
        ax.yaxis.set_major_locator(MaxNLocator(integer=True))
    axes[0].set_ylabel("Located glyphs")
    fig.suptitle("Lower-right projection calls by two blind readers")
    handles, labels = axes[0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="lower center", ncol=len(layout), frameon=False)
    fig.tight_layout(rect=(0, 0.1, 1, 0.95))
    fig.savefig(path, dpi=160)
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reader1", type=Path)
    parser.add_argument("reader2", type=Path)
    parser.add_argument("--key", type=Path, default=Path(__file__).with_name("private-crop-key.json"))
    parser.add_argument("--positions", type=Path, help="Full geometry roster, including unresolved crops.")
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--projection-plot", type=Path, help="Optional image of consensus projection counts.")
    args = parser.parse_args()
    paths = {"key": args.key, "reader1": args.reader1, "reader2": args.reader2}
    if args.positions:
        paths["positions"] = args.positions
    outputs = [path.resolve() for path in (args.out, args.projection_plot) if path]
    if len(set(outputs)) != len(outputs) or set(outputs) & {path.resolve() for path in paths.values()}:
        parser.error("Output paths must be distinct from one another and from inputs")
    raw = {name: path.read_bytes() for name, path in paths.items()}
    report = score(**{name: json.loads(data) for name, data in raw.items()})
    report["input_sha256"] = {name: sha256(data).hexdigest() for name, data in raw.items()}
    args.out.write_text(json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    if args.projection_plot:
        plot_projection(report, args.projection_plot)


if __name__ == "__main__":
    main()

scripts_as_text.slope_sensitivity.py:
"""Stress-test the geometric proxy against independent row-slope estimates."""
from collections import defaultdict
import csv
from itertools import combinations
import json
from pathlib import Path
from statistics import median

from measure_outline_proxy import height_proxy, LEVELS


ROOT = Path(__file__).resolve().parent


def line_slope(words, ordinate):
    anchors = []
    for r in words:
        try:
            x0, y0, x1, y1 = (int(r[f"box_{key}"]) for key in ("x0", "y0", "x1", "y1"))
        except ValueError:
            continue
        y = y1 if ordinate == "bottom_envelope" else (y0 + y1) / 2
        anchors.append(((x0 + x1) / 2, y))
    if len(anchors) < 4:
        return None
    ratios = [(yb - ya) / (xb - xa) for (xa, ya), (xb, yb) in combinations(anchors, 2)
              if abs(xb - xa) >= 100]
    return median(ratios) if len(ratios) >= 4 else None


def corrected_proxy(row, words, threshold, ordinate):
    line = [w for w in words[row["locus"]] if w["image"] == row["image"]]
    slope = line_slope(line, ordinate)
    estimate = height_proxy(row, threshold)
    if slope is None or estimate is None:
        return None
    x0, y0, x1, y1 = row["glyph_rect"]
    # Difference in nominal horizontal midpoints of the center and right bands.
    x_displacement = (0.79 - 0.485) * (x1 - x0)
    correction = slope * x_displacement / (y1 - y0)
    return {"native_dx_between_bands": x_displacement, "relative_correction": correction,
            "raw_proxy": estimate, "corrected_proxy": estimate - correction,
            "slope_px_y_per_px_x": slope}


def main():
    key = json.loads((ROOT / "private-crop-key.json").read_text())
    required = {r["locus"] for r in key}
    words = defaultdict(list)
    with (ROOT / "words.tsv").open(newline="") as src:
        for row in csv.DictReader(src, delimiter="\t"):
            if row["locus"] in required:
                words[row["locus"]].append(row)
    estimates = {}
    for ordinate in ("bottom_envelope", "center"):
        for threshold in LEVELS:
            members = defaultdict(dict)
            for row in key:
                e = corrected_proxy(row, words, threshold, ordinate)
                if e is not None:
                    members[row["pair_id"]][row["symbol"]] = e
            pairs = {}
            by_hand = defaultdict(list)
            hands = {row["pair_id"]: row["hand"] for row in key}
            for pair, results in members.items():
                if results.keys() == {"A", "o"}:
                    delta = results["A"]["corrected_proxy"] - results["o"]["corrected_proxy"]
                    by_hand[hands[pair]].append(delta)
                    pairs[pair] = {**results, "difference_A_minus_o": delta}
            estimates[f"{ordinate}-{threshold}"] = {
                "available_pairs": len(pairs),
                "A_larger": sum(row["difference_A_minus_o"] > 1e-10 for row in pairs.values()),
                "by_hand": {
                    hand: {"pairs": len(values), "A_larger": sum(v > 1e-10 for v in values)}
                    for hand, values in sorted(by_hand.items())
                },
                "matched_pairs": pairs,
            }
    result = {
        "method": (
            "Estimate local line slope from the median of all same-image word box slopes "
            "with horizontal separation at least 100 pixels. Require at least four boxes "
            "and four qualifying slopes. Subtract the estimated y change between the "
            "nominal center of the two glyph bands. Consider word-box center and bottom "
            "as two imperfect measures of row position. This is an exploratory sensitivity "
            "to writing inclination on the originally frozen deck."
        ),
        "results": estimates,
    }
    (ROOT / "outline-slope-sensitivity.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({k: {field: value for field, value in row.items() if field != "matched_pairs"}
                      for k, row in estimates.items()}, indent=2))


if __name__ == "__main__":
    main()

reproduction.count_exposure.py:
"""Public-practice exposure of label and paragraph onsets to line token counts."""

import argparse
from bisect import bisect_left
from collections import Counter, defaultdict
from dataclasses import dataclass
from fractions import Fraction
import json
from pathlib import Path

from vs import corpus, dsl, ivtff


BUCKETS = ("1", "2", "3", "4", "5–7", "8–11", "12+")
UPPER_BOUNDS = (1, 2, 3, 4, 7, 11)
TARGET_UNITS = ("L", "P")


@dataclass(frozen=True)
class Count:
    lines: int
    starts_o: int

    @property
    def rate(self):
        return Fraction(self.starts_o, self.lines) if self.lines else None


def exposure(pages):
    """Count literal eligible first words by unit and full parsed line length."""
    result = defaultdict(Counter)
    tokens = dsl.select(dsl.tokens(pages), {"position": "line_initial", "certain": True})
    for token in tokens:
        glyphs = ivtff.segment(token["w"], "eva-basic")
        if glyphs:
            bucket = BUCKETS[bisect_left(UPPER_BOUNDS, token["n"])]
            result[token["unit"], bucket][glyphs[0] == "o"] += 1
    return {(unit, bucket): Count(sum(c.values()), c[True]) for (unit, bucket), c in result.items()}


def combined(table, buckets, unit=None):
    counts = [v for (u, b), v in table.items() if b in buckets and (unit is None or u == unit)]
    return Count(sum(v.lines for v in counts), sum(v.starts_o for v in counts))


def number(value):
    return float(value) if value is not None else None


def observed_row(table, unit):
    total = combined(table, BUCKETS, unit)
    buckets = {}
    for bucket in BUCKETS:
        count = combined(table, (bucket,), unit)
        buckets[bucket] = {"lines": count.lines, "starts_o": count.starts_o,
                           "line_share": number(Fraction(count.lines, total.lines)) if total.lines else None,
                           "observed_rate": number(count.rate)}
    return {"lines": total.lines, "starts_o": total.starts_o,
            "observed_rate": number(total.rate), "buckets": buckets}


def contrast(rates):
    label, paragraph = (rates[u] for u in TARGET_UNITS)
    return {"label_minus_paragraph": number(label - paragraph) if label is not None and paragraph is not None else None,
            "label_divided_by_paragraph": number(label / paragraph) if label is not None and paragraph else None}


def counterfactual(training, evaluation, calibration_unit=None):
    calibration = {bucket: combined(training, (bucket,), calibration_unit) for bucket in BUCKETS}
    supported = {bucket for bucket, count in calibration.items() if count.lines}
    rates = {bucket: calibration[bucket].rate for bucket in supported}
    denominators, expected_rates, observed_rates = {}, {}, {}
    for unit in TARGET_UNITS:
        total = combined(evaluation, BUCKETS, unit)
        covered = combined(evaluation, supported, unit)
        predicted_hits = sum(combined(evaluation, (b,), unit).lines * rate for b, rate in rates.items())
        expected_rates[unit] = predicted_hits / covered.lines if covered.lines else None
        observed_rates[unit] = covered.rate
        denominators[unit] = {
            "evaluation_lines": total.lines, "covered_lines": covered.lines,
            "covered_share": number(Fraction(covered.lines, total.lines)) if total.lines else None,
            "unsupported_evaluation_lines": {b: combined(evaluation, (b,), unit).lines
                                             for b in BUCKETS if b not in supported},
            "expected_starts_o": number(predicted_hits),
            "expected_rate_on_covered_lines": number(expected_rates[unit]),
            "observed_rate_on_covered_lines": number(observed_rates[unit]),
        }
    observed_delta = contrast(observed_rates)
    expected_delta = contrast(expected_rates)
    observed_gap = observed_delta["label_minus_paragraph"]
    expected_gap = expected_delta["label_minus_paragraph"]
    return {
        "calibration_buckets": {bucket: {"training_lines": count.lines, "training_starts_o": count.starts_o,
                                         "training_rate": number(count.rate)}
                                for bucket, count in calibration.items()},
        "evaluation": denominators,
        "expected_contrast_on_covered_lines": expected_delta,
        "observed_contrast_on_covered_lines": observed_delta,
        "expected_fraction_of_observed_absolute_rate_gap":
            expected_gap / observed_gap if expected_gap is not None and observed_gap else None,
    }


def analyze(training, evaluation):
    return {
        "observed": {
            name: {
                "by_unit": {unit: observed_row(table, unit) for unit in TARGET_UNITS},
                "contrast": contrast({unit: combined(table, BUCKETS, unit).rate for unit in TARGET_UNITS}),
                "eligible_lines_by_unit": {unit: combined(table, BUCKETS, unit).lines
                                           for unit in sorted({u for u, _ in table})},
            }
            for name, table in (("training", training), ("evaluation", evaluation))
        },
        "calibration": {
            "pooled_all_units_training": counterfactual(training, evaluation),
            "paragraph_only_training": counterfactual(training, evaluation, "P"),
        },
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", type=Path, default=Path(__file__).with_name("length-exposure.json"))
    args = parser.parse_args()
    report = {
        "split": "Public project practice split only, no folio-level data in output.",
        "scope": "All manuscript sections, languages and scribal hands, reported separately for ZL and IT.",
        "selection": "Literal first word on each IVTFF line. Exclude uncertain first words without promoting another word.",
        "onset": "First glyph equals o under eva-basic.",
        "exposure": "Full parsed line word count, including uncertain noninitial tokens. Line kind is absent from bucket calibration.",
        "bucket_order": BUCKETS,
        "estimand": "Apply observed training-bucket rates to evaluation L and P exposure weights. "
                    "In each calibration omit unsupported buckets and compare observed rates on the same covered evaluation words. "
                    "Pooled rates include all kinds, including labels, so this is descriptive rather than an independent generator test.",
        "transliterations": {},
    }
    for edition in ("zl", "it"):
        training, evaluation = corpus.split_pages("practice", translit=edition)
        report["transliterations"][edition] = analyze(exposure(training), exposure(evaluation))
    args.out.write_text(json.dumps(report, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

