"""Public diagnostic: edge association conditional on both word lengths."""
import hashlib, json, math, random, sys
from collections import Counter, defaultdict
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent / 'voynich-swarm'
sys.path.insert(0, str(REPO))
from vs import corpus, ivtff

ROOT = Path(__file__).resolve().parent
PLAN = {
 'hypothesis': 'Adjacent word edges remain associated beyond the exact lengths of both words and the line word inventory.',
 'statistic': 'Weighted conditional mutual information of last/first EVA-basic glyph given exact left/right EVA-basic lengths; bits per adjacent pair.',
 'selection': 'Certain literal adjacent words of P lines only. Uncertain/empty words stay barriers; never join across a line.',
 'null': 'Permute intact certain words only within (original line, exact EVA-basic length) cells; all positions and uncertain barriers fixed.',
 'replicates': 199, 'seed': 2711202601, 'alpha': 0.01,
 'partitions': ['public practice training','public practice evaluation'],
 'editions': ['zl','it'],
 'decision': 'Report all four tests. The primary replication requires evaluation p<=.01 in both editions and at least30 potentially movable adjacent pairs each. No threshold selection after results.',
 'limits': 'Exploratory new diagnostic relative to existing edge-MI facts, not a trusted DSL metric or hidden-page fact. No causal or linguistic interpretation from a rejection alone.'}

def lines(pages):
    out=[]
    for p in pages:
        for ln in p.lines:
            if ln.unit!='P': continue
            row=[None if ivtff.uncertain(w) else tuple(ivtff.segment(w,'eva-basic')) or None for w in ln.words]
            groups=defaultdict(list)
            for i,w in enumerate(row):
                if w: groups[len(w)].append(i)
            out.append((row,list(groups.values())))
    return out

def measure(rows):
    joint=Counter(); left=Counter(); right=Counter(); strata=Counter()
    for row,_ in rows:
        for a,b in zip(row,row[1:]):
            if not a or not b: continue
            z=(len(a),len(b)); x,y=a[-1],b[0]
            joint[z,x,y]+=1;left[z,x]+=1;right[z,y]+=1;strata[z]+=1
    n=sum(joint.values())
    value=sum(c*math.log2(c*strata[z]/(left[z,x]*right[z,y])) for (z,x,y),c in joint.items())/n
    return value,n,len(strata)

def run(pages):
    rows=lines(pages); observed,n,k=measure(rows)
    movable=0
    for row,groups in rows:
        indices={i for g in groups if len({row[j] for j in g})>1 for i in g}
        movable+=sum(bool(a and b) and (i in indices or i+1 in indices) for i,(a,b) in enumerate(zip(row,row[1:])))
    rng=random.Random(PLAN['seed']); values=[]
    for _ in range(PLAN['replicates']):
        shuffled=[]
        for row,groups in rows:
            target=list(row)
            for g in groups:
                words=[row[i] for i in g];rng.shuffle(words)
                for i,w in zip(g,words): target[i]=w
            shuffled.append((target,groups))
        values.append(measure(shuffled)[0])
    p=(1+sum(x>=observed for x in values))/(1+len(values))
    return {'pages':len(pages),'adjacent_pairs':n,'length_pair_strata':k,'potentially_movable_pairs':movable,
            'observed_bits':observed,'null_mean':sum(values)/len(values),'null_min':min(values),'null_max':max(values),
            'excess_over_null_mean':observed-sum(values)/len(values),'p':p,'passes':p<=PLAN['alpha'] and movable>=30,
            'null_values':values}

if __name__=='__main__':
    if sys.argv[-1]=='--plan':
        (ROOT/'plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8')
        print('plan saved');sys.exit()
    assert json.loads((ROOT/'plan.json').read_text())==PLAN
    results={}
    for ed in PLAN['editions']:
        tr,ev=corpus.split_pages('practice',ed)
        results[ed]={}
        for label,pages in [('train',tr),('eval',ev)]:
            results[ed][label]=run(pages)
            print(ed,label,{k:v for k,v in results[ed][label].items() if k!='null_values'},flush=True)
    files={s:hashlib.sha256((REPO/'data/raw'/s).read_bytes()).hexdigest() for s in ['ZL3b-n.txt','IT2a-n.txt']}
    (ROOT/'results.json').write_text(json.dumps({'plan':PLAN,'source_sha256':files,'results':results},indent=2)+'\n',encoding='utf-8')

