        train,ev=corpus.split_pages('practice',ed);rng=random.Random(221)
        pool=[w for p in train for ln in p.lines for w in ln.words if w and not ivtff.uncertain(w)]
        sample={'manuscript':ev,'G-line-chain':generators.g_line_chain(train,ev,seed=4,order=4),'unigram':generators._shape_like(ev,lambda p,ln,i:rng.choice(pool))}
