"""A fixed, space-delimited, marker-free mixed-radix codebook control."""
import hashlib,json,random,statistics,math
from collections import Counter
from vs import corpus,ivtff,refcorpus

BITS=('a','o','d','y','n','r','l','ch','sh')
GALLOWS=('k','t','p','f','ckh','cth','cph','cfh')
N=25000; SEEDS=(17,37,73)
BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')

def encode(mask,repeats,g):
    # Gallow and e-run are ordinary optional slots, not compulsory terminators.
    a=[BITS[i] for i in range(4) if mask&(1<<i)]
    if g: a.append(GALLOWS[g-1])
    a+=['e']*repeats
    a += [BITS[i] for i in range(4,9) if mask&(1<<i)]
    return ''.join(a)

def vocabulary():
    codes=[encode(mask,r,g) for mask in range(1<<9) for r in range(3) for g in range(9) if mask or r or g]
    assert len(codes)==13823 and len(set(codes))==len(codes)
    # Ensure no cross-glyph ambiguity introduced by concatenating EVA-basic units.
    for mask in range(1<<9):
      for r in range(3):
       for g in range(9):
        if not (mask or r or g):continue
        expected=[BITS[i] for i in range(4) if mask&(1<<i)]+([GALLOWS[g-1]] if g else [])+['e']*r+[BITS[i] for i in range(4,9) if mask&(1<<i)]
        assert ivtff.segment(encode(mask,r,g))==expected
    return codes

def stats(words, valid):
    types=list(set(words)); result={}
    for name,seq in [('tokens',words),('types',types)]:
        segs=[ivtff.segment(w) for w in seq]
        gc=[sum(g in GALLOWS for g in s) for s in segs]
        ends=Counter(s[-1] for s in segs)
        result[name]={'n':len(seq),'mean_length':sum(map(len,segs))/len(seq),
           'repeated_glyph_share':sum(len(set(s))<len(s) for s in segs)/len(seq),
           'adjacent_repeat_share':sum(any(a==b for a,b in zip(s,s[1:])) for s in segs)/len(seq),
           'gallows_present_share':sum(n>0 for n in gc)/len(seq),
           'multiple_gallows_share':sum(n>1 for n in gc)/len(seq),
           'distinct_gallows_share':sum(len(set(s)&set(GALLOWS))>1 for s in segs)/len(seq),
           'length_hist':dict(sorted(Counter(map(len,segs)).items())),
           'top_final':ends.most_common(5), 'grammar_membership':sum(w in valid for w in seq)/len(seq)}
    return result

def witness(name):
    train,_=corpus.split_pages('practice',name)
    ws=[w for p in train for line in p.lines if line.unit=='P' for w in line.words
        if not ivtff.uncertain(w) and w.isascii() and w.isalpha() and w.islower()]
    assert len(ws)>=N
    return ws[:N]

def planted(words,codes,seed):
    assert len(set(words))<=len(codes)
    rng=random.Random(seed); shuffled=codes[:];rng.shuffle(shuffled)
    # First occurrence assignment is independent of manuscript and reversible given the codebook.
    table={w:shuffled[i] for i,w in enumerate(dict.fromkeys(words))}; reverse={v:k for k,v in table.items()}
    encoded=[table[w] for w in words]
    assert [reverse[w] for w in encoded]==words and len(table)==len(reverse)
    return encoded, len(table)

if __name__=='__main__':
    codes=vocabulary();valid=set(codes)
    stolfi=Counter(1+bin(mask).count('1') for mask in range(1<<9))
    assert all(stolfi[k+1]==math.comb(9,k) for k in range(10))
    # Spaces are structural: a+o and ao are both valid, so removing them is ambiguous.
    assert {'a','o','ao'}<=valid
    pins={e['id']:e for e in refcorpus.pins()}
    for b in BOOKS:
        with open(pins[b]['file'],'rb') as f: assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256'],b
    for w in ('zl','it'):
        fn={'zl':'ZL3b-n.txt','it':'IT2a-n.txt'}[w]
        h={'zl':'bf5b6d4ac1e3a51b1847a9c388318d609020441ccd56984c901c32b09beccafc','it':'7f27a8b0feed8f6de0a99900df6bf912dd1d295c38e5f830bac8b41c3f536fb5'}[w]
        with open('data/raw/'+fn,'rb') as f: assert hashlib.sha256(f.read()).hexdigest()==h
    out={'code_space':len(codes),'fixed_bits':BITS,'repeat_glyph':'e','gallows':GALLOWS,'n':N,'stolfi_9bit_type_length_counts':dict(sorted(stolfi.items())), 'unspaced_ambiguity':['a o','ao'], 'witnesses':{},'planted':{}}
    for w in ('zl','it'):out['witnesses'][w]=stats(witness(w),valid)
    for b in BOOKS:
        words=' '.join(refcorpus.blocks_of(b)).split()[:N]; assert len(words)==N
        out['planted'][b]={}
        for seed in SEEDS:
            enc,n=planted(words,codes,seed);out['planted'][b][seed]={'dictionary_size':n,'decoded_exact':True,'stats':stats(enc,valid)}
    print(json.dumps(out,indent=2))

