from collections import Counter
from fractions import Fraction
import json
from pathlib import Path

from vs import corpus, dsl, ivtff, path

WORK = Path(__file__).resolve().parent
SPEC = json.loads((WORK / "fact-spec.json").read_text())
WITH_NULL = {**SPEC, "compare": [
    {"null": "shuffle_within_line", "direction": "greater", "p": .01, "perms": 199}
]}


def load(transliteration, mode):
    training, practice = corpus.split_pages("practice", transliteration)
    if mode == "split":
        return training, practice
    joined = {page.id: page for page in ivtff.parse(
        path("data", "raw", corpus.TRANSLITERATIONS[transliteration]), uncertain_space="join"
    )}
    return [joined[p.id] for p in training], [joined[p.id] for p in practice]


def exact_null(eval_tokens, classes):
    hits = Fraction(0)
    pairs = 0
    for run in dsl.runs_of([token for token in eval_tokens if dsl._boundary_eligible(token)]):
        if len(run) < 2:
            continue
        states = []
        for token in run:
            glyphs = dsl._boundary_seg(token["w"])
            states.append((classes.get(glyphs[0]) == "start", classes.get(glyphs[-1]) == "end"))
        ending = sum(b for a, b in states)
        starting = sum(a for a, b in states)
        both = sum(a and b for a, b in states)
        hits += Fraction(ending * starting - both, len(run))
        pairs += len(run) - 1
    return float(hits / pairs), pairs


def main():
    report = {}
    for trans in corpus.EVA_TRANSLITERATIONS:
        for mode in ("split", "join"):
            training, practice = load(trans, mode)
            official = dsl.evaluate(SPEC, practice, training)
            classes = dsl._boundary_classes(dsl.tokens(training))
            expected, pairs = exact_null(dsl.tokens(practice), classes)
            assert official["detail"]["boundary_class_rate"]["pairs"] == pairs
            try:
                direction = dsl.evaluate(WITH_NULL, practice, training)["detail"]["shuffle_within_line"]
            except dsl.SpecError as exc:
                direction = {"undefined": str(exc)}
            row = {"official_threshold": official, "class_counts": dict(Counter(classes.values())),
                   "classes": classes,
                   "exact_run_shuffle_expectation": expected,
                   "observed_minus_expected": official["value"] - expected,
                   "shuffle_diagnostic": direction}
            print(trans, mode, official["value"], official["pass"], pairs, expected, direction, flush=True)
            report[f"{trans}:{mode}"] = row
    (WORK / "primitive-results.json").write_text(json.dumps(report, indent=2) + "\n")


if __name__ == "__main__":
    main()

independent_null_tails.py.text:
"""Finite-sample tails under the exact full eligible-run shuffling null."""

from collections import Counter
from functools import cache

import numpy as np

from independent_replay import MODES, adjacency_runs, edges, is_end_start, learn, line_index
from vs import corpus, ivtff, path


@cache
def sequence_counts(remaining, previous_ends):
    """Count category sequences by their number of end-to-start edges.

    Category bit 0 indicates an initial start class and bit 1 a final end
    class. With a fixed category multiset, every category sequence has the
    same number of underlying whole-word permutations.
    """
    size = sum(remaining)
    if size == 0:
        return (1,)
    answer = [0] * (size + int(previous_ends))
    for category, occurrences in enumerate(remaining):
        if occurrences == 0:
            continue
        reduced = list(remaining)
        reduced[category] -= 1
        increment = int(previous_ends and (category & 1))
        for count, frequency in enumerate(sequence_counts(tuple(reduced), bool(category & 2))):
            answer[count + increment] += frequency
    return tuple(answer)


def permutation_distribution(runs, classes):
    category_bags = Counter()
    for run in runs:
        if len(run) < 2:
            continue
        bag = Counter(
            int(classes.get(first) == "start") + 2 * int(classes.get(last) == "end")
            for first, last in run
        )
        category_bags[tuple(bag[i] for i in range(4))] += 1
    distribution = np.array([1], dtype=np.longdouble)
    for category_bag, repetitions in category_bags.items():
        frequencies = sequence_counts(category_bag, False)
        weights = np.array(frequencies, dtype=np.longdouble) / np.longdouble(sum(frequencies))
        for _ in range(repetitions):
            distribution = np.convolve(distribution, weights)
    return distribution


def main():
    training, evaluation = corpus.split_pages("practice")
    train_ids, eval_ids = ({page.id for page in pages} for pages in (training, evaluation))
    for transliteration in corpus.EVA_TRANSLITERATIONS:
        for space_policy in MODES:
            index = line_index(ivtff.parse(
                path("data", "raw", corpus.TRANSLITERATIONS[transliteration]),
                uncertain_space=space_policy,
            ))
            classes = learn(adjacency_runs(index, train_ids, index))
            runs = list(adjacency_runs(index, eval_ids, index))
            distribution = permutation_distribution(runs, classes)
            observed = sum(count for pair, count in edges(runs).items() if is_end_start(pair, classes))
            assert np.isclose(distribution.sum(), 1)
            mean = (distribution * np.arange(len(distribution))).sum()
            print(transliteration, space_policy, observed, float(mean),
                  float(distribution[observed:].sum()))


if __name__ == "__main__":
    main()

